window.__BOOK__ = {"meta":{"title_ar":"الأمير الصغير","title_zh":"小王子","author_ar":"أنطوان دو سانت إكزوبيري","author_zh":"安托万·德·圣埃克苏佩里","voice":"ar-AE-FatimaNeural (edge-tts)","ipa_note":"阿拉伯语读音为拉丁转写，供参考。","n_chapters":28,"n_paras":762,"n_sents":1635,"audio_paras":762,"ar_source":"الأمير الصغير (أنطوان دو سانت إكزوبيري) 阿语出版译本原文"},"chapters":[{"id":"ch00","title_ar":"إلى ليون وورث","title_en":"To Leon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":"ch00p00.mp3","sents":[{"ar":"إلى ليون وورث.. أطلب الصبر من الأطفال الذين ربما قرؤوا هذا الكتاب؛","zh":"请孩子们原谅我把这本书献给一位大人。","t":[103,6776]},{"ar":"الإهداء إلى راشد. إن سببي الأول والأكثر","zh":"他是我世间最好的朋友。","t":[6776,11145]},{"ar":"أهمية هو أنه أفضل صديق لي في العالم. وسببي الثاني هو أن هذا الراشد يفهم كل شيء،","zh":"这位大人洞察一切，即便是对孩子的书也能心领神会。","t":[11145,19605]},{"ar":"حتى كتب الأطفال. وسببي الثالث هو أنه يعيش","zh":"他住在法国，忍饥受寒。","t":[19605,24342]},{"ar":"في فرنسا يعاني الجوع","zh":"他亟需慰藉。","t":[24342,26013]},{"ar":"والبرد؛ إنه بحاجة إلى البهجة. إن لم تكن هذه الأسباب كافية، فإنني أهدي الكتاب إلى الصبي الصغير","zh":"若这些理由仍不足够，我便将此书献予那位成人曾是的孩童。","t":[26013,35237]},{"ar":"الذي منه نشأ هذا الراشد. إن كل الراشدين كانوا أطفالًا ذات يوم، مع أن قلة منهم يتذكرون ذلك.","zh":"所有大人曾经都是孩子——尽管他们中的许多人已不记得。","t":[35237,45342]},{"ar":"وهكذا فإني أصحح إهدائي: إلى ليون وورث عندما كان ولدًا صغيرًا. أنطوان دو سانت إكزوبيري ١٩٤٤.","zh":"因此，我将献词更正：献予列翁·维尔特，他曾是孩童时。","t":[45342,57013]}]}]},{"id":"ch01","title_ar":"الفصل الأول","title_en":"Chapter I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":"ch01p00.mp3","sents":[{"ar":"ذات مرة، عندما كنت في السادسة من عمري، رأيت صورة جميلة في كتاب عن غابة بدائية، اسمه « قصص","zh":"六岁那年，我在一本名为《自然奇观》的书里，瞥见了一幅描绘原始森林的壮丽图画。","t":[103,9418]},{"ar":"حقيقية »، قد أظهر حية عاصرة تبتلع حيوانًا.","zh":"这是一幅蟒蛇正在吞食动物的图画。","t":[9418,14921]},{"ar":"هنا نسخة عن الصورة.","zh":"这是这幅画的复印件。","t":[14921,16789]}]},{"id":"ch01p01","audio":"ch01p01.mp3","sents":[{"ar":"جاء في الكتاب: « تبتلع الحيات العاصرة فرائسها كاملة","zh":"书中记载：“蟒蛇将猎物整个吞下，不嚼就吞。”","t":[103,4655]},{"ar":"من دون أن تمضغها، ثم لا تعود قادرة على الحراك","zh":"它们便无法动弹，需在消化过程中沉睡六个月。","t":[4655,9037]}]},{"id":"ch01p02","audio":"ch01p02.mp3","sents":[{"ar":"والنوم طوال ستة أشهر وهي تهضمها ». بعد","zh":"我沉思良久，对丛林奇遇心生遐想。","t":[103,4737]},{"ar":"ذلك فكرت مليًّا في المغامرات في الغابة، وبالتالي نجحت في","zh":"经过一番用彩色铅笔的练习，我终于完成了我的第一幅画。","t":[4737,9447]},{"ar":"تحقيق رسمي الأول","zh":"我的第一幅画。","t":[9447,11053]},{"ar":"بقلم تلوين. رسمي رقم ١","zh":"它看起来是这样的：","t":[11053,14882]}]},{"id":"ch01p03","audio":"ch01p03.mp3","sents":[{"ar":"كان كما يلي: عرضت تحفتي على الراشدين وسألتهم إن كان رسمي يخيفهم.","zh":"我把我的杰作展示给大人看，问他们这幅画是否吓到了他们。","t":[103,6248]}]},{"id":"ch01p04","audio":"ch01p04.mp3","sents":[{"ar":"أجابوا:","zh":"吓什么？","t":[103,997]},{"ar":"« لماذا يخاف أي شخص من قبعة؟!","zh":"帽子有什么好怕的？","t":[997,3655]}]},{"id":"ch01p05","audio":"ch01p05.mp3","sents":[{"ar":"»، إن رسمي لا يمثل قبعة،","zh":"我的画作并非帽子图。","t":[103,2471]},{"ar":"بل كان من المفترض أن يمثل حية","zh":"这是一幅蟒蛇消化大象的图画。","t":[2471,5155]},{"ar":"عاصرة وهي تهضم فيلًا. وهكذا وضعت رسمًا آخر عن باطن الحية العاصرة لكي أمكن الراشدين من فهمها.","zh":"但既然大人们无法理解，我便又画了一张：我画了蟒蛇的内部，好让大人们能看得一清二楚。","t":[5155,15697]},{"ar":"إنهم يحتاجون دائمًا إلى تفسيرات.","zh":"他们总需要有人给他们解释。","t":[15697,19474]},{"ar":"وقد بدا رسمي رقم ۲ كما يلي:","zh":"我的第二号画看起来是这样的：","t":[19474,21934]}]},{"id":"ch01p06","audio":"ch01p06.mp3","sents":[{"ar":"ثم نصحني الراشدون بالتخلي عن رسم الحيات العاصرة، سواء من الداخل أو من الخارج، وأن أكرس نفسي عوضًا عن ذلك للجغرافيا والتاريخ والحساب وعلم الصرف","zh":"大人们这次则劝我放下对蟒蛇的描绘，无论是从内部还是外部，转而投身于地理、历史、算术和语法的学习。","t":[103,12866]},{"ar":"والنحو. وهكذا تخليت عن مهنة رائعة كرسام في سن السادسة. خاب أملي من","zh":"六岁那年，我便放弃了可能成为辉煌画家的生涯。","t":[12866,21039]},{"ar":"افتقار رسمي رقم ١ ورسمي رقم ۲ إلى النجاح. لا يفهم الراشدون شيئًا بأنفسهم،","zh":"我的第一幅画和第二幅画均以失败告终，令我心灰意冷。","t":[21039,28934]},{"ar":"وإنه لأمر شاق للأطفال أن يفسروا الأشياء لهم مرة بعد أخرى. وهكذا كان علي أن أختار عملًا آخر،","zh":"大人自己永远不懂，孩子们总是不断地向他们解释，这实在令人厌烦。","t":[28934,38250]}]},{"id":"ch01p07","audio":"ch01p07.mp3","sents":[{"ar":"فتعلمت قيادة الطائرات. حلقت بالطائرة فوق العالم بأسره تقريبًا.","zh":"于是，我选择了另一门职业，学会了驾驶飞机。","t":[103,7895]},{"ar":"وبالفعل كانت الجغرافيا مفيدة جدًّا لي، فأنا أستطيع التمييز بين الصين","zh":"我驾驶飞机飞越了世界的各个角落；确实，地理学对我帮助极大。","t":[7895,13711]},{"ar":"وأريزونا بلمحة بصر. وهي تساعد كثيرًا","zh":"一目了然，便能分辨出中国与亚利桑那。","t":[13711,18211]},{"ar":"إذا ما تاه المرء في الليل. ونتيجة","zh":"若夜航迷失，此等知识便显宝贵。","t":[18211,21842]}]},{"id":"ch01p08","audio":"ch01p08.mp3","sents":[{"ar":"لذلك التقيت، خلال حياتي، بكل أنواع الناس الجديين. لقد أمضيت وقتًا كافيًا مع","zh":"在这漫长的人生旅程中，我与众多关注重大事务的人们有过无数次的相遇。","t":[103,8303]},{"ar":"الراشدين، رأيتهم عن مسافة قريبة","zh":"我在成人世界中度过许多时光。","t":[8303,11566]},{"ar":"جدًّا، وأخشى القول إن رأيي","zh":"我近距离地与他们亲密接触。","t":[11566,13908]},{"ar":"فيهم لم يتحسن كثيرًا. وكنت كلما","zh":"我对他们的看法并未有多大改观。","t":[13908,18171]}]},{"id":"ch01p09","audio":"ch01p09.mp3","sents":[{"ar":"التقيت بشخص بدا لي صائب التفكير، أُظهر له رسمي رقم ١، الذي احتفظت به، على سبيل التجربة. أردت أن أكتشف","zh":"每当我遇到一个在我看来还算有洞察力的大人，我便尝试向他展示我始终保留的那幅《第一号画》。","t":[103,11158]},{"ar":"إن كان هو، أو هي، فهيمًا حقًّا. لكن الجواب كان دائمًا:","zh":"我试图探查，看这究竟是否是一个真正懂得理解的人。","t":[11158,17579]},{"ar":"« إنها قبعة.","zh":"但无论他是谁，他或她总是会说：“那是一顶帽子。”","t":[17579,18789]}]},{"id":"ch01p10","audio":"ch01p10.mp3","sents":[{"ar":"»، وهكذا تخليت عن ذكر الحيات العاصرة أو الغابات","zh":"于是，我便不再与那个人谈论蟒蛇、原始森林或星星。","t":[103,3813]},{"ar":"البدائية أو النجوم.","zh":"我降低自己的身份以适应他。","t":[3813,6526]},{"ar":"وكنت لا أنزل نفسي إلى مستواه أو مستواها وأتحدث عن البريدج والغولف","zh":"我与他说起桥牌、高尔夫、政治和领带。","t":[6526,12276]},{"ar":"والسياسة وربطات العنق. والراشدون سيفرحون كثيرًا بلقاء مثل هذا الشخص الواعي.","zh":"这位大人对结识如此明理的人感到非常满意。","t":[12276,19815]}]}]},{"id":"ch02","title_ar":"الفصل الثاني","title_en":"Chapter II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":"ch02p00.mp3","sents":[{"ar":"وهكذا عشت وحيدًا، من دون أي إنسان أستطيع التحدث إليه حقًّا، إلى أن تعرضت لحادث في الصحراء الكبرى منذ ست سنوات.","zh":"于是，我独自一人生活，无人可倾诉衷肠，直至六年前，我的飞机在撒哈拉沙漠遭遇事故。","t":[103,11118]},{"ar":"تحطم شيء ما في محركي،","zh":"发动机里出了故障。","t":[11118,13474]},{"ar":"وبما أنه لا يوجد ميكانيكي أو مسافر معي، هيأت نفسي للقيام بعملية إصلاح شاقة أملت أن تكون","zh":"于是，身边既无机械师，又无乘客相伴，我便孤身一人尝试着艰难地修理。","t":[13474,21829]},{"ar":"ناجحة. إنها.. مسألة حياة أو موت بالنسبة لي. وقلما","zh":"生死攸关，我仅有的饮用水只够维持一周。","t":[21829,29684]},{"ar":"كان في حوزتي مياه شرب كافية لأسبوع. في الليلة الأولى نمت على","zh":"那第一夜，我便在千里之外、人迹罕至的沙地上安睡。","t":[29684,35605]},{"ar":"الرمال، على بعد ألف ميل من أي مسكن بشري. كنت معزولًا","zh":"我比孤舟在茫茫大海中的遇险者还要孤独。","t":[35605,41447]},{"ar":"أكثر من بحَّار على طوافة في وسط المحيط، وقد تحطمت سفينته، وهكذا","zh":"晨曦初露，那奇异的细小声音将我惊醒，我惊愕不已。","t":[41447,47829]},{"ar":"تستطيع","zh":"它说：","t":[47829,48645]}]},{"id":"ch02p01","audio":"ch02p01.mp3","sents":[{"ar":"أن تتخيل دهشتي عند بزوغ","zh":"请给我画一只绵羊吧！","t":[103,2629]}]},{"id":"ch02p02","audio":"ch02p02.mp3","sents":[{"ar":"الشمس عندما","zh":"什么！","t":[103,1366]}]},{"id":"ch02p03","audio":"ch02p03.mp3","sents":[{"ar":"أيقظني صوت خافت","zh":"画只绵羊吧！","t":[103,1932]}]},{"id":"ch02p04","audio":"ch02p04.mp3","sents":[{"ar":"غريب. قال: - أرجوك... ارسم لي","zh":"我惊得跳了起来，如遭雷击。","t":[103,4908]},{"ar":"خروفًا. - ماذا؟ - ارسم لي خروفًا.","zh":"我紧闭双眼，用力眨动。","t":[4908,10513]},{"ar":"قفزت وأنا مصعوق تمامًا فركت","zh":"我环顾四周，仔细打量。","t":[10513,13039]},{"ar":"عيني، فتحتهما وأغلقتهما ونظرت بانتباه حولي. اكتشفت وجود صبي صغير غير","zh":"我瞥见一个极为奇特的小人儿，他正一本正经地打量着我。","t":[13039,21211]},{"ar":"عادي يراقبني بجدية. هنا أفضل رسم استطعت أن أرسمه","zh":"这里可见我后来为他画的最成功的肖像。","t":[21211,27079]},{"ar":"له مؤخرًا. لكن رسمي بالطبع ليس بنصف روعة","zh":"但我的画作显然远不及它的原型迷人。","t":[27079,32237]}]},{"id":"ch02p05","audio":"ch02p05.mp3","sents":[{"ar":"شخصه. إن هذا ليس خطئي؛","zh":"这并非我的过错。","t":[103,3592]},{"ar":"لقد أحبطني الكبار في مهنتي كرسام عندما كنت في السادسة من عمري، فلم أتعلم رسم شيء عدا","zh":"六岁那年，大人们便扼杀了我的画家梦想，我从未学会画任何东西，除了从外面看的蟒蛇和从里面看的蟒蛇。","t":[3592,11685]}]},{"id":"ch02p06","audio":"ch02p06.mp3","sents":[{"ar":"حيات عاصرة من الخارج وحيات عاصرة من الداخل. ولذلك حدقت","zh":"我惊愕地瞪大了眼睛，几乎要目不转睛地凝视着这个突如其来的身影。","t":[103,6618]},{"ar":"بدهشة تامة إلى هذا الشبح المفاجئ. لا تنس","zh":"记得，我在人烟稀少的沙漠中，千里之外遭遇了坠机。","t":[6618,11118]},{"ar":"أنني كنت على بعد ألف ميل من أي منطقة سكنية. لكن الفتى الصغير","zh":"他似乎既不是在沙中迷失方向，也不是因疲惫、饥饿、口渴或恐惧而昏倒。","t":[11118,17539]},{"ar":"لم يظهر أنه تائه أو منهك أو ميت من العطش والجوع،","zh":"他身上丝毫没有在沙漠中迷失方向、远离人烟千里的孩子的痕迹。","t":[17539,22434]},{"ar":"أو الخوف. لم يبد أنه","zh":"终于开口说话，我对他说：","t":[22434,25316]}]},{"id":"ch02p07","audio":"ch02p07.mp3","sents":[{"ar":"طفل تائه في وسط","zh":"但——你在此做什么？","t":[103,1892]}]},{"id":"ch02p08","audio":"ch02p08.mp3","sents":[{"ar":"الصحراء، على بعد ألف ميل من أي منطقة","zh":"他缓缓地回答，仿佛在谈论一件极重要的事情：","t":[103,3747]}]},{"id":"ch02p09","audio":"ch02p09.mp3","sents":[{"ar":"مأهولة. عندما تمكنت","zh":"请给我画一只羊吧……","t":[103,3237]}]},{"id":"ch02p10","audio":"ch02p10.mp3","sents":[{"ar":"من الكلام أخيرًا، سألته: -","zh":"当神秘的力量压倒一切，人不敢违抗。","t":[103,2695]},{"ar":"لكن... ما الذي تفعله هنا؟ فأجاب برقة وجدية: - أرجوك ارسم لي خروفًا.","zh":"荒诞至极，远离人烟千里，生死攸关之际，我还是从口袋里掏出了一张纸和一支钢笔。","t":[2695,12105]},{"ar":"عندما يكون اللغز طاغيًا بشدة، لا يجرؤ أحد على عدم الطاعة، ومع أن ذلك بدا لي سخيفًا وأنا أبعد ألف ميل عن أي مسكن بشري، تناولت ورقة وقلمي","zh":"然而，我回想起我的学业专注于地理、历史、算术和语法，便有些不悦地对那个小家伙说，我不会画画。","t":[12105,25158]},{"ar":"الحبر من جيبي،","zh":"他回答道：","t":[25158,26552]}]},{"id":"ch02p11","audio":"ch02p11.mp3","sents":[{"ar":"لكنني تذكرت","zh":"这无妨。","t":[103,1432]},{"ar":"فجأة أن دراساتي","zh":"画一只羊吧……","t":[1432,3169]}]},{"id":"ch02p12","audio":"ch02p12.mp3","sents":[{"ar":"تركزت على الجغرافيا والتاريخ","zh":"但我从未画过羊。","t":[103,2234]},{"ar":"والحساب والنحو، فأخبرت الفتى الصغير (بغضب قليل)","zh":"于是，我为他画出了我常画的其中一幅。","t":[2234,7208]},{"ar":"أنني لا أعرف كيف أرسم. أجاب: -","zh":"这是从外面看的蟒蛇。","t":[7208,11000]},{"ar":"لا بأس. ارسم لي خروفًا. وبما أنني لم أرسم","zh":"我惊愕地听见那小家伙对它说：","t":[11000,16908]}]},{"id":"ch02p13","audio":"ch02p13.mp3","sents":[{"ar":"خروفًا قط، رسمت","zh":"不！不！不！","t":[103,2142]},{"ar":"له إحدى الصورتين اللتين رسمتهما من قبل: صورة","zh":"我不想在蟒蛇肚子里有一只大象。","t":[2142,6366]},{"ar":"الحيَّة العاصرة من الخارج. إليكم أفضل رسمة","zh":"蟒蛇极为危险，而大象又非常笨重。","t":[6366,11013]},{"ar":"استطعت رسمها له بعد ذلك.. وقد دُهشت عندما","zh":"在我居住的地方，一切都极小。","t":[11013,15737]},{"ar":"سمعت المخلوق الصغير يقول: -","zh":"我需要的是一只羊。","t":[15737,18092]},{"ar":"لا! لا! لا أريد","zh":"画一只羊吧。","t":[18092,21724]}]},{"id":"ch02p14","audio":"ch02p14.mp3","sents":[{"ar":"فيلًا في باطن حية، إن الحية","zh":"于是，我画了一幅画。","t":[103,2984]}]},{"id":"ch02p15","audio":"ch02p15.mp3","sents":[{"ar":"العاصرة مخلوق خطير جدًّا، والفيل ثقيل","zh":"他仔细端详着，然后说道：","t":[103,4090]}]},{"id":"ch02p16","audio":"ch02p16.mp3","sents":[{"ar":"جدًّا.","zh":"不！","t":[103,1776]},{"ar":"إن كل شيء صغير جدًّا حيث","zh":"这羊已经病得很重了。","t":[1776,4066]},{"ar":"أعيش. إنني بحاجة إلى","zh":"再给我画一个。","t":[4066,7303]}]},{"id":"ch02p17","audio":"ch02p17.mp3","sents":[{"ar":"خروف، ارسم لي خروفًا. وهكذا رسمت.","zh":"于是，我又画了一张。","t":[103,4802]}]},{"id":"ch02p18","audio":"ch02p18.mp3","sents":[{"ar":"نظر إليه بانتباه وقال: - لا. إن هذا الخروف","zh":"我的朋友微笑着，既温柔又宽容。","t":[103,5342]}]},{"id":"ch02p19","audio":"ch02p19.mp3","sents":[{"ar":"سقيم جدًّا. ارسم لي خروفًا","zh":"这显然不是一只羊。","t":[103,3526]},{"ar":"آخر. فرسمت. قال","zh":"这是一只公羊。","t":[3526,7105]},{"ar":"صديقي الصغير بلطف","zh":"它长着角哩。","t":[7105,8750]}]},{"id":"ch02p20","audio":"ch02p20.mp3","sents":[{"ar":"وتسامح: - ألا ترى أنه ليس خروفًا،","zh":"于是，我又重新画了一次。","t":[103,3524]}]},{"id":"ch02p21","audio":"ch02p21.mp3","sents":[{"ar":"إنه كبش. إن لديه قرونًا... ومرة أخرى رسمت رسمًا لكنه رفضه","zh":"但这幅画也被拒绝了，就像其他那些一样。","t":[103,7776]}]},{"id":"ch02p22","audio":"ch02p22.mp3","sents":[{"ar":"أيضًا كالرسمين","zh":"这只太老了。","t":[103,1287]},{"ar":"السابقين. - إن هذا عجوز جدًّا.","zh":"我要一只能活很久的羊。","t":[1287,4947]}]},{"id":"ch02p23","audio":"ch02p23.mp3","sents":[{"ar":"أريد خروفًا يعيش وقتًا طويلًا. عندئذ نفد صبري لأنني كنت في","zh":"我的耐心已耗尽，急于开始拆卸我的发动机。","t":[103,6526]}]},{"id":"ch02p24","audio":"ch02p24.mp3","sents":[{"ar":"عجلة من أمري لأفكك محركي في أسرع وقت","zh":"于是，我草草地画了这幅画。","t":[103,3879]},{"ar":"ممكن، وهكذا خربشت هذا الرسم.","zh":"于是，我随口解释道。","t":[3879,6879]}]},{"id":"ch02p25","audio":"ch02p25.mp3","sents":[{"ar":"وأوضحت: - إن هذا ليس سوى الصندوق.","zh":"这不过是他的一只箱子。","t":[103,4224]},{"ar":"إن الخروف الذي طلبته يوجد داخله.","zh":"那你要的绵羊就在里面。","t":[4224,7079]}]},{"id":"ch02p26","audio":"ch02p26.mp3","sents":[{"ar":"لكنني دهشت جدًّا لأرى وجه القاضي الصغير مشرقًا: - هذا تمامًا ما","zh":"我惊讶地看到，我的这位小法官脸上露出了光芒：","t":[103,5642]}]},{"id":"ch02p27","audio":"ch02p27.mp3","sents":[{"ar":"أردت. هل تظن أن هذا","zh":"这正是我想要的！","t":[103,2737]},{"ar":"الخروف سيحتاج إلى الكثير من العشب؟","zh":"这只绵羊需要很多草吗？","t":[2737,5592]}]},{"id":"ch02p28","audio":"ch02p28.mp3","sents":[{"ar":"- لماذا؟","zh":"为什么？","t":[103,866]}]},{"id":"ch02p29","audio":"ch02p29.mp3","sents":[{"ar":"- لأنه حيث أعيش كل شيء صغير جدًّا... - لا","zh":"因为在我住的地方，一切都极小。","t":[103,3945]}]},{"id":"ch02p30","audio":"ch02p30.mp3","sents":[{"ar":"بد أن هناك عشبًا كافيًا له؛","zh":"我说：“肯定够了。”","t":[103,2734]},{"ar":"لقد أعطيتك خروفًا صغيرًا جدًّا. أحنى رأسه","zh":"我给你的是一只很小很小的绵羊。","t":[2734,7500]}]},{"id":"ch02p31","audio":"ch02p31.mp3","sents":[{"ar":"فوق الرسم وقال: - ليس صغيرًّا","zh":"他俯身细看那幅画。","t":[103,3050]}]},{"id":"ch02p32","audio":"ch02p32.mp3","sents":[{"ar":"جدًّا كما... انظر!","zh":"如此小巧，看哪！","t":[103,3566]},{"ar":"لقد خلد إلى النوم.","zh":"它已经入睡……","t":[3566,5211]}]},{"id":"ch02p33","audio":"ch02p33.mp3","sents":[{"ar":"وعلى هذا النحو التقيت الأميرالصغير.","zh":"就这样，我结识了小王子。","t":[103,3090]}]}]},{"id":"ch03","title_ar":"الفصل الثالث","title_en":"Chapter III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":"ch03p00.mp3","sents":[{"ar":"استغرقت وقتًا طويلًا لأكتشف من أين أتى.","zh":"我费了好长时间才弄清他来自何方。","t":[103,4434]},{"ar":"لم يبد الأمير الصغير الذي سألني الكثير من الأسئلة أنه يصغي لي. والفضل في","zh":"小王子虽向我提问无数，却似乎对我的问题充耳不闻。","t":[4434,11500]},{"ar":"كشف كل شيء يعود إلى الكلمة الغريبة التي نطق بها هنا وهناك..","zh":"偶然间的话语，渐渐向我揭示了所有真相。","t":[11500,16776]}]},{"id":"ch03p01","audio":"ch03p01.mp3","sents":[{"ar":"فمثلًا، عندما شاهد طائرتي أول مرة (لن أرسم طائرتي؛ إن ذلك معقد جدًّا بالنسبة لي)،","zh":"例如，他头一回见到我的飞机时（我不愿画飞机，那太复杂了），便问我：","t":[103,8813]}]},{"id":"ch03p02","audio":"ch03p02.mp3","sents":[{"ar":"سألني: - ما هذا الشيء؟","zh":"那是什么玩意儿？","t":[103,2182]}]},{"id":"ch03p03","audio":"ch03p03.mp3","sents":[{"ar":"- إنها ليست شيئًا.","zh":"那不是玩意儿。","t":[103,2592]},{"ar":"إنها تطير.","zh":"它会飞。","t":[2592,4645]},{"ar":"إنها طائرة.","zh":"这是飞机。","t":[4645,6789]},{"ar":"إنها طائرتي.","zh":"这是我的飞机。","t":[6789,8132]}]},{"id":"ch03p04","audio":"ch03p04.mp3","sents":[{"ar":"وكنت فخورًا لأن بوسعي أن أخبره بأنني","zh":"我为他能知道我会飞而自豪。","t":[103,3681]}]},{"id":"ch03p05","audio":"ch03p05.mp3","sents":[{"ar":"أستطيع الطيران.","zh":"他突然喊道：","t":[103,1563]}]},{"id":"ch03p06","audio":"ch03p06.mp3","sents":[{"ar":"فهتف","zh":"怎么！","t":[103,800]},{"ar":"قائلًا: - ماذا؟! هبطت من","zh":"你是从天上掉下来的吗？","t":[800,4223]}]},{"id":"ch03p07","audio":"ch03p07.mp3","sents":[{"ar":"السماء؟ أجبت بتواضع: - نعم.","zh":"是的，我谦逊地回答。","t":[103,3961]}]},{"id":"ch03p08","audio":"ch03p08.mp3","sents":[{"ar":"-","zh":"啊！","t":[0,200]},{"ar":"أوه، هذا مضحك.","zh":"这倒有趣！","t":[103,1826]}]},{"id":"ch03p09","audio":"ch03p09.mp3","sents":[{"ar":"وانفجرالأمير الصغير في رنين من الضحك اللطيف، الأمر الذي أزعجني","zh":"那小王子突然发出一阵清脆的笑声，这笑声让我非常恼火。","t":[103,5432]},{"ar":"كثيرًا. فأنا أحب أن تؤخَذ","zh":"我愿我的不幸得到认真对待。","t":[5432,8908]}]},{"id":"ch03p10","audio":"ch03p10.mp3","sents":[{"ar":"مصائبي بجدية.","zh":"他接着又说：","t":[103,1616]}]},{"id":"ch03p11","audio":"ch03p11.mp3","sents":[{"ar":"- إذن أنت أيضًا آت من","zh":"你们也是从天上来的！","t":[103,1787]},{"ar":"السماء. من أي كوكب؟","zh":"这是你的星球吗？","t":[1787,4658]}]},{"id":"ch03p12","audio":"ch03p12.mp3","sents":[{"ar":"وسرعان ما لاحظت شعاعًا من الضوء في وجوده الغامض، فسألته على الفور:","zh":"那一刻，我瞥见了他神秘身影中的光芒；于是，我突兀地问道：","t":[103,5800]}]},{"id":"ch03p13","audio":"ch03p13.mp3","sents":[{"ar":"- وأنت أيضًا آت من كوكب آخر؟","zh":"你们也是从另一个星球来的吗？","t":[103,2774]}]},{"id":"ch03p14","audio":"ch03p14.mp3","sents":[{"ar":"لكنه لم يجب.","zh":"他并未回答。","t":[103,2395]},{"ar":"هز رأسه بلطف فيما كان يحدق إلى طائرتي.","zh":"他轻轻摇晃着头，目光未离我的飞机。","t":[2395,6303]}]},{"id":"ch03p15","audio":"ch03p15.mp3","sents":[{"ar":"- الحقيقة أنه لا يمكن أن تكون قد أتيت من","zh":"那确实，你不可能从很远处来到这里……","t":[103,3707]}]},{"id":"ch03p16","audio":"ch03p16.mp3","sents":[{"ar":"مكان بعيد جدًّا على متن هذا.","zh":"他陷入沉思，久久未能自拔。","t":[103,3724]},{"ar":"وغرق في تفكير عميق، ثم بعد أن تناول خروفي من جيبه، أخذ","zh":"他掏出我的绵羊，便沉浸在心爱宝物的沉思之中。","t":[3724,9381]}]},{"id":"ch03p17","audio":"ch03p17.mp3","sents":[{"ar":"يتأمل في كنزه. يمكنك أن تتخيل كم أُثير فضولي بهذا النصف من الثقة بشأن « الكواكب الأخرى ». وهكذا حاولت أن أكتشف","zh":"我好奇之心被他对“其他星球”的这种半信半疑所激起，因此我竭力想了解更多关于这个话题。","t":[103,11789]}]},{"id":"ch03p18","audio":"ch03p18.mp3","sents":[{"ar":"المزيد. - من أين أنت آت أيها","zh":"我的小家伙，你从哪里来？","t":[103,3526]},{"ar":"المخلوق الصغير؟ أين هذه « حيث أعيش » التي تتحدث عنها؟","zh":"这“我住在哪里”，你所说的那是什么意思？","t":[3526,10158]},{"ar":"إلى أين تريد أن تأخذ خروفي؟ أجاب بعد","zh":"你打算把你的绵羊带到哪里去？","t":[10158,14421]}]},{"id":"ch03p19","audio":"ch03p19.mp3","sents":[{"ar":"استغراق في التفكير: - ما يعجبني","zh":"沉思片刻后，他回答道：","t":[103,3142]}]},{"id":"ch03p20","audio":"ch03p20.mp3","sents":[{"ar":"في الصندوق الذي أعطيتني إياه أن باستطاعته أن يستخدمه كبيت له","zh":"这箱子你送给我真是太好了，夜里他可以用它做屋子。","t":[103,5379]}]},{"id":"ch03p21","audio":"ch03p21.mp3","sents":[{"ar":"أثناء الليل.","zh":"这倒是。","t":[103,2118]},{"ar":"- طبعًا. وإن كنت صالحًا سأعطيك حبلًا تربطه به أثناء النهار، وعمودًا لتربطه إليه.","zh":"若你听话，我还会给你一根绳子，白天用来拴住它，再给你一个桩子。","t":[2118,10473]}]},{"id":"ch03p22","audio":"ch03p22.mp3","sents":[{"ar":"بدا الأمير الصغير مصعوقًا من","zh":"小王子对这个提议似乎感到震惊：","t":[103,2511]}]},{"id":"ch03p23","audio":"ch03p23.mp3","sents":[{"ar":"اقتراحي.","zh":"拴住他！","t":[103,2039]},{"ar":"- أربطه؟ يا لها","zh":"真是个古怪的主意！","t":[2039,4434]}]},{"id":"ch03p24","audio":"ch03p24.mp3","sents":[{"ar":"من فكرة مضحكة! - لكن إن لم تربطه فإنه سيتجول ويضيع. انفجر","zh":"“可是，如果你不拴住他，”我说，“他会到处乱跑，然后走失的。”","t":[103,8184]}]},{"id":"ch03p25","audio":"ch03p25.mp3","sents":[{"ar":"صديقي بالضحك مرة أخرى: -","zh":"我的朋友又爆发出一阵笑声：","t":[103,2458]}]},{"id":"ch03p26","audio":"ch03p26.mp3","sents":[{"ar":"لكن إلى أين سيذهب؟ - إلى","zh":"他以为它会跑到哪里去呢？","t":[103,3302]}]},{"id":"ch03p27","audio":"ch03p27.mp3","sents":[{"ar":"أي مكان.","zh":"无论哪里。","t":[103,2066]},{"ar":"سيهيم على وجهه.","zh":"前方，就在他面前。","t":[2066,3606]}]},{"id":"ch03p28","audio":"ch03p28.mp3","sents":[{"ar":"الأمير الصغير فوق كوكبه « ب","zh":"小王子认真地说：","t":[103,2708]}]},{"id":"ch03p29","audio":"ch03p29.mp3","sents":[{"ar":"٦١٢ » عندئذ علق الأمير","zh":"那无关紧要。","t":[103,3129]},{"ar":"الصغير بجدية: - لا يهم، فكل شيء صغير جدًّا حيث","zh":"我所在之处的万物都如此渺小。","t":[3129,8155]}]},{"id":"ch03p30","audio":"ch03p30.mp3","sents":[{"ar":"أعيش. (وربما بشيء من الدهاء أضاف قائلًا)","zh":"带着一丝忧伤，他补充道：","t":[103,4763]}]},{"id":"ch03p31","audio":"ch03p31.mp3","sents":[{"ar":"لا يمكن للمرء أن يضيع إذا سار مستقيمًا...","zh":"前方，无人能走得太远……","t":[103,3484]}]}]},{"id":"ch04","title_ar":"الفصل الرابع","title_en":"Chapter IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":"ch04p00.mp3","sents":[{"ar":"وهكذا تعلمت شيئًا آخر مهمًّا جدًّا؛ وذلك أن كوكبه ليس أكبر من بيت. لكن ذلك لم يدهشني في الواقع","zh":"我因此得知了第二个重要的事实：小王子来自的星球，其大小不过是一座房子的规模。","t":[103,10066]}]},{"id":"ch04p01","audio":"ch04p01.mp3","sents":[{"ar":"كثيرًا؛ كنت أعرف حق المعرفة أنه","zh":"但这并未真正让我感到惊讶。","t":[103,3300]},{"ar":"إلى جانب أكبر الكواكب مثل الأرض وجوبيتر والمريخ وفينوس، التي أُعطيت أسماء، هنالك المئات من الكواكب الأخرى التي هي أحيانًا صغيرة جدًّا، بحيث إن","zh":"除了那些被我们命名的巨大行星——如地球、木星、火星、金星——之外，还有数百颗其他行星，其中一些小得连望远镜都难以辨认。","t":[3300,16211]},{"ar":"من الصعب مشاهدتها من خلال التلسكوب. عندما يكتشف فلكي أحدها، فإنه لا يعطيه","zh":"天文学家发现这类星球时，并不赋予它们名字，而只赋予它们编号。","t":[16211,24079]},{"ar":"اسمًا، بل رقمًا. ولربما سماه، مثلًا، «","zh":"他或许会称之为“小行星325号”。","t":[24079,29013]}]},{"id":"ch04p02","audio":"ch04p02.mp3","sents":[{"ar":"الكويكب ۳۲٥ ». لدي أسباب جدية لأعتقد أن كوكب الأمير الصغير هو الكوكب","zh":"我有充分的理由相信，小王子来自的星球是B-612号小行星。","t":[103,6908]}]},{"id":"ch04p03","audio":"ch04p03.mp3","sents":[{"ar":"المعروف باسم ب-٦١٢، وقد شوهد هذا الكويكب","zh":"这颗小行星仅被望远镜观测过一次。","t":[103,5405]},{"ar":"مرة واحدة فقط من خلال تلسكوب بواسطة فلكي تركي في العام","zh":"那是一位土耳其天文学家在1909年观测到的。","t":[5405,11063]}]},{"id":"ch04p04","audio":"ch04p04.mp3","sents":[{"ar":"۱۹۰۹. في ذلك الوقت، وضع رسمًا كبيرًا لاكتشافه في مؤتمر فلكي عالمي. لكن","zh":"天文学家在发现之际，曾于国际天文大会上作了一场盛大的演示。","t":[103,7211]},{"ar":"بسبب زيه التركي المزخرَف، لم يصدقه أحد. فالكبار","zh":"但他身着土耳其服装，因此无人相信他的话。","t":[7211,13066]}]},{"id":"ch04p05","audio":"ch04p05.mp3","sents":[{"ar":"هم على هذا المنوال.","zh":"大人就是这样……","t":[103,1655]}]},{"id":"ch04p06","audio":"ch04p06.mp3","sents":[{"ar":"ولحسن حظ الكويكب ب-٦١٢، فرض ديكتاتور تركي الزي الأوروبي على رعاياه تحت طائلة العقوبة بالموت. وهكذا كرر الفلكي رسمه في العام","zh":"幸而，为了B-612小行星的声誉，土耳其独裁者颁布了一道法令，规定臣民必须改穿欧洲服装，违者处以死刑。","t":[103,13842]},{"ar":"۱۹۲۰ وهو يرتدي بذلة أنيقة. وفي هذه المرة، اقتنع الجميع. إذا كنت أخبرتكم بتلك التفاصيل عن الكويكب","zh":"于是，1920年，这位天文学家再次身着考究的服饰，仪态万方地展示了他的演示。","t":[13842,24263]},{"ar":"ب-٦١٢ وكشفت لكم رقمه، فإن ذلك بسبب","zh":"这一次，众人都接受了他的报告。","t":[24263,29710]}]},{"id":"ch04p07","audio":"ch04p07.mp3","sents":[{"ar":"الكبار. فالكبار يحبون الأرقام. عندما تتحدث إليهم عن صديق جديد، لا يطرحون أبدًا أسئلة عن أمور","zh":"若非为了这些大人及其习性，我才不会向你们详述这颗小行星的细节，并记下它的编号。","t":[103,10961]},{"ar":"أساسية. لن يقولوا لك أبدًا: « كيف صوته؟ ما هي ألعابه المفضلة؟ هل","zh":"告诉他们你交了一个新朋友，他们从不询问任何重要的事情。","t":[10961,19566]},{"ar":"يجمع الفراشات؟ » بل يسألونك: « كم عمره؟ كم أخًا","zh":"他们从不会问你：“他的嗓音是怎样的？”","t":[19566,24750]},{"ar":"لديه؟ كم يبلغ وزنه؟ كم","zh":"他最喜欢玩什么游戏？","t":[24750,28671]},{"ar":"من المال يجني والده؟ »،","zh":"他是否采集蝴蝶标本？","t":[28671,31263]},{"ar":"وعندئذ فقط يشعرون بأنهم","zh":"他有多少个兄弟？","t":[31263,33618]},{"ar":"يعرفونه.","zh":"他体重多少？","t":[33618,35316]},{"ar":"وإذا ذكرت للكبار: « رأيت منزلًا جميلًا مبنيًّا من","zh":"他们只从这些数字中认为他们已经了解了他。","t":[35316,39816]}]},{"id":"ch04p08","audio":"ch04p08.mp3","sents":[{"ar":"القرميد الوردي، وزهر إبرة الراعي ينمو على عتبات نوافذه، واليمام على سطحه... »، فإنهم لن يتمكنوا من تخيل مثل هذا المنزل. ولربما عليك أن","zh":"若你对大人说：“我看见一幢红砖砌成的美丽房子，窗台上种着天竺葵，屋顶栖息着鸽子，”他们便无法想象这房子的模样。","t":[103,13934]},{"ar":"تقول: « رأيت منزلًا يساوي مئة ألف جنيه. »، وسيقولون بإعجاب: « أوه! هذا رائع! ». وهكذا إذا قلت لهم: « إن","zh":"你们得对他们说：“我看见一幢价值两万法郎的房子。”他们就会惊叹：“哦，多美的房子啊！”","t":[13934,26645]}]},{"id":"ch04p09","audio":"ch04p09.mp3","sents":[{"ar":"الدليل على أن الأمير الصغير موجود حقًّا هو أنه فاتن، وأنه ضحك وأراد خروفًا.","zh":"小王子存在的证据，便是他风度翩翩、笑声朗朗，且在寻找一只绵羊。","t":[103,7908]},{"ar":"والآن عندما تريد خروفًا، فإن ذلك يثبت أنك موجود »، سيهزون أكتافهم بلا مبالاة ويعاملونك","zh":"若有人想要一只绵羊，这便是他存在的证明。告诉他们这些又有什么用呢？","t":[7908,16434]},{"ar":"وكأنك طفل. ولكن إذا قلت لهم:","zh":"他们耸耸肩，把你当做个孩子。","t":[16434,20697]},{"ar":"«إن الكوكب الذي أتى منه هو الكويكب ب-٦١٢، فعندئذ سيقتنعون ويتركونك لشأنك. هذه هي الحال. لا ينبغي للمرء","zh":"若你对他们说：“他来自的星球是B-612号小行星，”他们便会信服，不再对你纠缠不休。","t":[20697,33869]}]},{"id":"ch04p10","audio":"ch04p10.mp3","sents":[{"ar":"أن يقف ضدهم. على","zh":"他们就是这样。","t":[103,2724]},{"ar":"الأطفال أن يُظهروا تفهمًا","zh":"不可因此而怪罪他们。","t":[2724,4684]},{"ar":"أكبر تجاه الكبار. لكن، طبعًا، بالنسبة","zh":"孩子们理应对大人怀有极大的宽容。","t":[4684,9684]}]},{"id":"ch04p11","audio":"ch04p11.mp3","sents":[{"ar":"إلى أولئك الذين يتفهمون الحياة منا، لا يمكننا الاهتمام بالأرقام على نحو","zh":"然而，对于我们这些懂得生活的人来说，数字不过是无关紧要之物。","t":[103,6576]},{"ar":"أقل. وكان ينبغي لي أن أبدأ هذه القصة مثلما","zh":"我本想以童话的形式开始这个故事。","t":[6576,11329]},{"ar":"تبدأ الأسطورة. وكنت أود لو بدأت بالقول: « ذات مرة كان هناك أمير صغير عاش على كوكب","zh":"从前有个小王子，他住在一颗比他自己大不了多少的星球上，需要一只绵羊。","t":[11329,19895]}]},{"id":"ch04p12","audio":"ch04p12.mp3","sents":[{"ar":"ليس أكبر منه، واحتاج إلى صديق. »، وكان ذلك سيبدو أقرب إلى الحقيقة","zh":"这会让我的故事显得更加真实，对于那些懂得生活的人来说。","t":[103,7066]}]},{"id":"ch04p13","audio":"ch04p13.mp3","sents":[{"ar":"بالنسبة إلى أولئك الذين يفهمون ماهية","zh":"我不愿有人漫不经心地读我的书。","t":[103,3116]},{"ar":"الحياة. لا أريد أن يُقرأ كتابي بلا","zh":"我记录这些回忆，心中满是哀伤。","t":[3116,6908]},{"ar":"مبالاة، فقد عانيت حزنًا شديدًا أثناء تسجيل","zh":"六年来，我的朋友带着他的羊离我远去。","t":[6908,10868]},{"ar":"هذه الذكريات. مرت ست سنوات منذ أن تركني صديقي الصغير مع","zh":"若我尝试在此描述他，那是为了确保我不会忘记他。","t":[10868,16868]},{"ar":"خروفه. وإذا كنت أحاول","zh":"遗忘朋友是可悲的。","t":[16868,19908]},{"ar":"وصفه، فإن ذلك كيلا أنساه.","zh":"并非人人都有过朋友。","t":[19908,23500]},{"ar":"من المحزن أن تنسى صديقًا. ليس لدى كل شخص صديق. وقد استطعت أن أكون","zh":"若我忘记了他，我或许会变成那些只对数字感兴趣的成年人……","t":[23500,31381]}]},{"id":"ch04p14","audio":"ch04p14.mp3","sents":[{"ar":"كالكبار الذين ينشغلون بالأرقام. فاشتريت علبة","zh":"为此，我又买了一盒颜料和几支铅笔。","t":[103,5092]},{"ar":"ألوان وأقلام رصاص. من الصعب أن أستأنف الرسم بعد أن تقدمت بي السن، وبعدما لم أقم بأي محاولة باستثناء رسم حية من الخارج وحية من الداخل في السادسة","zh":"在这个年纪重拾绘画，对我而言实属不易，自从六岁那年画过一条从外面看的蟒蛇和一条从里面看的蟒蛇后，我从未再画过其他图画。","t":[5092,18789]},{"ar":"من عمري، إلا أنني سأسعى من دون شك لأن","zh":"我将尽力让我的肖像画尽可能逼真。","t":[18789,22197]},{"ar":"أجعل من رسومي واقعية على","zh":"但我并不确信能成功。","t":[22197,24513]},{"ar":"قدر الإمكان. لكنني لست متأكدًا بأي حال من النجاح.","zh":"一幅画得还可以，另一幅却与原型相差甚远。","t":[24513,30934]},{"ar":"رسم على ما يرام، وآخر لا يُظهر أي شبه لموضوعه. الارتفاع ليس صحيحًا. هنا الأمير","zh":"我描绘小王子的身高时，也犯了一些错误：有时他画得太高，有时又太矮。","t":[30934,40329]},{"ar":"الصغير طويل جدًّا، وهناك صغير جدًّا.","zh":"我对他的服装颜色也有些疑虑。","t":[40329,42184]},{"ar":"وأنا لست متأكدًا من لون بذلته. وهكذا أثابر بالمحاولة والخطأ وبأفضل","zh":"我笨拙地摸索前行，时而出色，时而糟糕，但愿总体上还能过得去。","t":[42184,52486]}]},{"id":"ch04p15","audio":"ch04p15.mp3","sents":[{"ar":"قدرة لدي. سأقترف بعض الأخطاء في التفاصيل الأكثر","zh":"在某些更为重要的细节上，我也难免出错。","t":[103,5237]},{"ar":"أهمية. لكن يجب مسامحتي على","zh":"但这并非是我的过错。","t":[5237,8947]},{"ar":"ذلك. إن صديقي لم يشرح لي شيئًا قط.","zh":"我的朋友从不向我解释任何事。","t":[8947,13947]},{"ar":"وربما أعتقد بأنني مثله،","zh":"他或许以为我与他相似。","t":[13947,16487]},{"ar":"لكن لسوء الحظ، لا أستطيع أن أرى الخراف ضمن الصناديق.","zh":"然而，唉，我不知如何透过箱子的墙壁看到绵羊。","t":[16487,21842]},{"ar":"ربما أشبه الكبار قليلًا.","zh":"或许我也有点像大人了。","t":[21842,24908]},{"ar":"إنني أتقدم في السن.","zh":"我不得不变老。","t":[24908,26776]}]}]},{"id":"ch05","title_ar":"الفصل الخامس","title_en":"Chapter V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":"ch05p00.mp3","sents":[{"ar":"كنت كل يوم أكتشف شيئًا ما عن الكوكب، عن مغادرة الأمير الصغير له، وعن رحلته. وكانت المعلومات تأتي ببطء شديد، وتتبع مسار أفكار","zh":"随着日复一日，在与他的交谈中，我逐渐了解了小王子的星球、他离开那里的经过以及他的旅行。","t":[103,12632]},{"ar":"الأمير الصغير. وهكذا في اليوم الثالث، سمعت عن كارثة","zh":"信息缓缓而来，如同偶然自他思绪中飘落。","t":[12632,18079]},{"ar":"أشجار الباوباب. ومرة ثانية، كان ذلك بفضل الخروف، لأن","zh":"就这样，第三天，我听说了猴面包树的灾难。","t":[18079,24657]}]},{"id":"ch05p01","audio":"ch05p01.mp3","sents":[{"ar":"الأمير الصغير سألني فجأة وكأنما تملكه شك","zh":"这次，又是绵羊让我得以知晓。","t":[103,4103]},{"ar":"عميق: - إنه لأمر صحيح، أليس كذلك، أن الخراف تأكل الشجيرات الصغيرة؟","zh":"小王子突然严肃地问我：“羊真的会吃小灌木吗？”","t":[4103,10958]}]},{"id":"ch05p02","audio":"ch05p02.mp3","sents":[{"ar":"- أجل، هذا صحيح. - آه!","zh":"是的，千真万确。","t":[103,3197]}]},{"id":"ch05p03","audio":"ch05p03.mp3","sents":[{"ar":"أنا","zh":"啊！","t":[103,405]},{"ar":"مسرور لذلك. لم أفهم","zh":"啊，太好了！","t":[405,3618]}]},{"id":"ch05p04","audio":"ch05p04.mp3","sents":[{"ar":"لماذا تأكل الخراف شجيرات بهذه الأهمية. لكن الأمير","zh":"我不懂羊儿为何要吃那些小灌木如此重要。","t":[103,5658]},{"ar":"الصغير أضاف قائلًا: -","zh":"小王子接着说：","t":[5658,7421]}]},{"id":"ch05p05","audio":"ch05p05.mp3","sents":[{"ar":"وهكذا، فإنها تأكل أيضًا أشجار الباوباب؟","zh":"那么，它们也会吃猴面包树吗？","t":[103,3932]}]},{"id":"ch05p06","audio":"ch05p06.mp3","sents":[{"ar":"أوضحت للأمير الصغير أن أشجار الباوباب ليست شجيرات صغيرة، بل هي أشجار بعلو الكنائس، وأنه إذا ما أخذ قطيعًا من الفيلة معه، فإن القطيع لن يكون قادرًا على أكل شجرة باوباب واحدة.","zh":"我向小王子指出，猴面包树并非小灌木，相反，它们是像城堡一般巨大的树木；即便他带上一群大象，那群大象也无法吃掉一棵猴面包树。","t":[103,15724]}]},{"id":"ch05p07","audio":"ch05p07.mp3","sents":[{"ar":"ضحك الأمير الصغير من فكرة قطيع الفيلة وقال:","zh":"那群大象的念头让小王子忍不住笑了。","t":[103,3998]}]},{"id":"ch05p08","audio":"ch05p08.mp3","sents":[{"ar":"- على المرء أن يكدسهم الواحد فوق الآخر.","zh":"它们必须得一个挨一个地叠上去。","t":[103,3327]}]},{"id":"ch05p09","audio":"ch05p09.mp3","sents":[{"ar":"(ثم أشار بحكمة) قبل أن","zh":"但他却说了句明智的话：","t":[103,2682]}]},{"id":"ch05p10","audio":"ch05p10.mp3","sents":[{"ar":"تنمو إلى هذا الحجم، تكون أشجار الباوباب صغيرة. - هذا","zh":"在它们长得太大之前，猴面包树起初只是小小的。","t":[103,5579]}]},{"id":"ch05p11","audio":"ch05p11.mp3","sents":[{"ar":"صحيح. لكن لماذا","zh":"那完全正确。","t":[103,2645]},{"ar":"تريد كم من خرافك أنت أكل أشجار الباوباب الصغيرة؟","zh":"可你为何要让羊儿吃掉那些小猴面包树苗呢？","t":[2645,6368]}]},{"id":"ch05p12","audio":"ch05p12.mp3","sents":[{"ar":"ما أجابني به هو: - أوه! هيا، هيا! (وكأن هذا الأمر بَدَهِي)! كان علي أن أبذل","zh":"他立刻回答道：“哦，哦，当然啦！”仿佛在谈论一件不言而喻的事。","t":[103,9645]},{"ar":"جهدًا ذهنيًّا هائلًا كي أجد لنفسي حلًّا للمسألة. بدا","zh":"我不得不竭尽全力去解决这个问题，毫无助力。","t":[9645,15211]}]},{"id":"ch05p13","audio":"ch05p13.mp3","sents":[{"ar":"أن على كوكب الأمير الصغير، مثلما على سائر الكواكب، نباتات صالحة ونباتات رديئة. تأتي البذور الصالحة من","zh":"确实，正如我所了解的，小王子居住的星球上——就像所有星球一样——既有好植物也有坏植物。","t":[103,10197]},{"ar":"النباتات الصالحة والبذور الرديئة من النباتات الرديئة. إن البذور غير","zh":"因此，既有来自好植物的良种，也有来自坏植物的恶种。","t":[10197,16395]},{"ar":"منظورة، تبقى كامنة","zh":"种子是看不见的。","t":[16395,18395]},{"ar":"في عمق الأرض حتى يقرر أحدها فجأة أن يستيقظ، فيتمدد بحياء في بادئ الأمر،","zh":"它们在地球黑暗的深处沉睡，直至其中一颗被唤醒的欲望所攫获。","t":[18395,25487]},{"ar":"ثم يبدأ بدفع غصين صغير فاتن برفق في اتجاه الشمس. إذا كان مجرد برعم فجل أو قصب أو ورد، فيمكن","zh":"这颗小小的种子将伸展身躯，起初是胆怯地，开始向上向太阳推送一根迷人的小嫩枝。","t":[25487,35434]},{"ar":"تركه لينمو كما يحلو له، لكن إذا كان عشبة ضارة، فيجب اقتلاعها فورًا،","zh":"若它只是一株萝卜苗或玫瑰枝，便任其生长，无论它愿往何处。","t":[35434,42395]},{"ar":"وحالما تتحقق معرفتها. وقد حدث أيضًا أن هناك بذورًا رهيبة على","zh":"但若是恶草，一经辨认，便须立即铲除，绝不可拖延。","t":[42395,49171]}]},{"id":"ch05p14","audio":"ch05p14.mp3","sents":[{"ar":"كوكب الأمير الصغير إنها... بذور أشجار الباوباب. إن تربة","zh":"这颗星球上长着可怕的种子，那是猴面包树的种子。","t":[103,6447]},{"ar":"الكوكب حافلة بها. إن تدخلت في وقت","zh":"那颗星球的土壤被它们侵扰。","t":[6447,10526]},{"ar":"متأخر، فإنك لن تستطيع أبدًا التخلص من أشجار الباوباب. إنها","zh":"若你晚些时候才留意，那猴面包树你将永远无法摆脱。","t":[10526,16987]},{"ar":"تمتد فوق الكوكب بأسره،","zh":"它覆盖了整个星球。","t":[16987,19395]},{"ar":"وجذورها تخترقه بشكل","zh":"根须将它彻底穿透。","t":[19395,21592]},{"ar":"واضح. وإذا كان الكوكب صغيرًا جدًّا، وإذا كان هنالك الكثير من أشجار","zh":"若星球太小，而猴面包树太多，它们就会把星球撕裂成碎片。","t":[21592,28382]}]},{"id":"ch05p15","audio":"ch05p15.mp3","sents":[{"ar":"الباوباب، فإن الكوكب ينفجر. قال لي الأمير","zh":"“这关乎自律，”小王子后来对我说。","t":[103,4789]},{"ar":"الصغير فيما بعد: « إنها مسألة تدريب، عندما تنتهي من","zh":"清晨梳洗完毕，便要细心照料你那颗星球的清洁。","t":[4789,9684]},{"ar":"عملية التزين في الصباح، يحين وقت تنظيف الكوكب بعناية كبيرة. على المرء أن يقتلع","zh":"务必在猴面包树与玫瑰花苗初生时难以区分之际，立即将它们连根拔除。","t":[9684,17789]},{"ar":"أشجار الباوباب بانتظام بالغ حالما يتم","zh":"这活儿单调乏味，却也极易完成。","t":[17789,21158]}]},{"id":"ch05p16","audio":"ch05p16.mp3","sents":[{"ar":"تمييزها عن شجيرات الورد التي تشبهها كثيرًا عندما تكون صغيرة جدًّا. إنه لعمل ممل، لكنه أيضًا في غاية السهولة","zh":"于是有一天他对我说：“你应该画一幅漂亮的画，好让你们那里的孩子们能清楚地看到这一切。”","t":[103,12237]},{"ar":"». وذات يوم نصحني أن أرسم رسمًا جميلًا","zh":"若他们日后旅行，这将会很有用。","t":[12237,15368]},{"ar":"أُطلع عليه الأطفال حيث أسكن. قال لي: - إذا سافروا في","zh":"有时，他补充道，“推迟一件工作到另一天也无妨。","t":[15368,20816]},{"ar":"يوم من الأيام، فإنه يفيدهم، لعل من المناسب في بعض","zh":"但若是猴面包树的事，那就总是意味着灾难。","t":[20816,25855]},{"ar":"الأحيان أن يؤجل المرء عمله إلى يوم","zh":"那颗星球上住着一个懒惰的人。","t":[25855,29000]},{"ar":"آخر. لكن فيما يتعلق بأشجار","zh":"他忽略了三株小灌木……","t":[29000,32855]}]},{"id":"ch05p17","audio":"ch05p17.mp3","sents":[{"ar":"الباوباب، فإن القيام بذلك هو كارثة. أعرف كوكبًا يقطنه رجل كسول،","zh":"于是，按照小王子向我描述的那样，我画下了那颗星球。","t":[103,7618]},{"ar":"وقد أهمل ثلاث شجيرات صغيرة. وهكذا،","zh":"我不喜欢摆出一副道德家的嘴脸。","t":[7618,12447]},{"ar":"عندما ارتكز عملي على وصف الأمير الصغير، وضعت الرسم الذي تشاهدونه الآن. لا أحب أن أبدو كواعظ، لكن خطر أشجار الباوباب معروف جدًّا","zh":"然而，人们对猴面包树的危害认识不足，而在小行星上迷路的人面临的风险又如此之大，我不得不打破一贯的矜持。","t":[12447,25000]},{"ar":"والمخاطر جديرة بوضعها في","zh":"孩子们，当心猴面包树！","t":[25000,27566]}]},{"id":"ch05p18","audio":"ch05p18.mp3","sents":[{"ar":"الحسبان لمن يمكن أن يتوه على كوكب، حتى إنني لأول مرة أستثني تحفظي. أقول: أيها الأطفال، احذروا أشجار الباوباب! لقد عملت بجد على هذا الرسم كي","zh":"朋友们，就像我一样，他们长期以来一直在不知不觉中规避这个危险；因此，为了他们，我才在这幅画上倾注了如此多的心血。","t":[103,15526]},{"ar":"أُحذر أصدقائي من خطر لم يدركوه مثلي لوقت طويل.","zh":"这教训，虽费尽周折，却值得我付出所有。","t":[15526,20092]}]},{"id":"ch05p19","audio":"ch05p19.mp3","sents":[{"ar":"إن درسي يستحق ذلك العناء. ربما تتساءلون: لماذا لا توجد رسوم أخرى مؤثرة في هذا الكتاب كالرسم الخاص بأشجار الباوباب؟","zh":"或许你们会问我：“为什么这本书里的其他插画没有这幅猴面包树的画那么雄伟、那么令人印象深刻？”","t":[103,11514]}]},{"id":"ch05p20","audio":"ch05p20.mp3","sents":[{"ar":"الجواب بسيط","zh":"答案简单。","t":[103,1313]},{"ar":"للغاية:","zh":"我曾尝试。","t":[1313,2182]},{"ar":"لقد حاولت لكن أقل النجاح حالفني مع الرسوم","zh":"但画那些其他的画，我并不成功。","t":[2182,5563]},{"ar":"الأخرى. عندما رسمت أشجار الباوباب، كنت مدفوعًا بشعور بالحاجة الملحة.","zh":"在绘制猴面包树时，紧迫的需求激励着我，我的画笔超越了自我。","t":[5563,12631]}]}]},{"id":"ch06","title_ar":"الفصل السادس","title_en":"Chapter VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":"ch06p00.mp3","sents":[{"ar":"آه! أيها الأمير","zh":"哦，小王子！","t":[103,2289]},{"ar":"الصغير. شيئًا فشيئًا استطعت أن أفهم حياتك","zh":"逐渐地，我逐渐洞悉了你那悲伤的小生活的秘密……","t":[2289,6842]},{"ar":"المحدودة الحزينة... كانت تسليتك الوحيدة، لوقت طويل، مشاهدة","zh":"长久以来，你唯一的乐趣便是在观赏夕阳的宁静中寻找快乐。","t":[6842,13447]},{"ar":"غروب الشمس. علمت هذه التفاصيل الجديدة","zh":"第四天清晨，你向我提及了这个新细节：","t":[13447,17697]}]},{"id":"ch06p01","audio":"ch06p01.mp3","sents":[{"ar":"في صباح اليوم الرابع","zh":"我偏爱那夕阳的余晖。","t":[103,1682]},{"ar":"عندما قلتَ لي: -","zh":"让我们去看日落吧。","t":[1682,3050]}]},{"id":"ch06p02","audio":"ch06p02.mp3","sents":[{"ar":"إنني مولع جدًّا بغروب الشمس. لنذهب","zh":"但我道：“然而，我们必须等待。”","t":[103,4369]}]},{"id":"ch06p03","audio":"ch06p03.mp3","sents":[{"ar":"ونراقب غروب الشمس..","zh":"然而，为何等待？","t":[103,2961]},{"ar":"- لكن","zh":"为何等待？","t":[2961,3764]}]},{"id":"ch06p04","audio":"ch06p04.mp3","sents":[{"ar":"ينبغي أن ننتظر.","zh":"只为那日落。","t":[103,2539]},{"ar":"- ننتظر ماذا؟","zh":"我们得等到那时。","t":[2539,3829]}]},{"id":"ch06p05","audio":"ch06p05.mp3","sents":[{"ar":"- ننتظر الشمس لتغيب.","zh":"你起初显得非常惊讶。","t":[103,2882]},{"ar":"بدوت مذهولًا في بادئ","zh":"你自嘲地笑了。","t":[2882,4539]},{"ar":"الأمر، ثم ضحكت وقلتَ","zh":"你对我说：","t":[4539,6855]}]},{"id":"ch06p06","audio":"ch06p06.mp3","sents":[{"ar":"لي: - لا أنفك عن الاعتقاد بأنني في وطني.","zh":"我总以为我是在自己家里呢！","t":[103,3892]}]},{"id":"ch06p07","audio":"ch06p07.mp3","sents":[{"ar":"نعم بالتأكيد.","zh":"如此而已。","t":[103,2368]},{"ar":"عندما يكون النهار في منتصفه في الولايات المتحدة، تكون الشمس، كما يعلم كل شخص،","zh":"人人皆知，当美国正值正午时分，法国已是夕阳西下。","t":[2368,9250]}]},{"id":"ch06p08","audio":"ch06p08.mp3","sents":[{"ar":"تغرب في فرنسا. على المرء أن يسافر في دقيقة واحدة إلى فرنسا","zh":"若能瞬间飞往法国，便可从正午直奔日落。","t":[103,6434]},{"ar":"كي يتمكن من مراقبة غروب الشمس هناك.","zh":"遗憾的是，法国太远了。","t":[6434,10737]},{"ar":"لسوء الحظ، إن فرنسا بعيدة جدًّا، لكن على كوكبك الصغير، كل ما أنت بحاجة إليه هو تحريك كرسيك","zh":"然而，在你那小小的星球上，小王子，你只需挪动你的椅子几步。","t":[10737,20013]},{"ar":"بضع خطوات. وباستطاعتك مشاهدة الشفق وهو يتلاشى كلما","zh":"你随时都能目睹白昼落幕，暮色降临。","t":[20013,26171]}]},{"id":"ch06p09","audio":"ch06p09.mp3","sents":[{"ar":"رغبت في ذلك... قال لي: - ذات يوم رأيت الشمس تغرب أربعًا وأربعين مرة.","zh":"“有一天，”你对我说，“我看了四十四次日落！”","t":[103,7197]}]},{"id":"ch06p10","audio":"ch06p10.mp3","sents":[{"ar":"وقلت مضيفًا بعد ذلك بقليل:","zh":"你后来又补充道：","t":[103,2826]}]},{"id":"ch06p11","audio":"ch06p11.mp3","sents":[{"ar":"- هل تعلم... يعشق المرء غروب الشمس عندما يكون حزينًا للغاية... سألته: - هل كنت","zh":"你深知——当一个人愁绪满怀时，便偏爱那夕阳的余晖……","t":[103,8526]}]},{"id":"ch06p12","audio":"ch06p12.mp3","sents":[{"ar":"حزينًا يوم شاهدت الأربعة والأربعين غروبًا؟ لكن الأمير","zh":"那天，四十四次日落，你如此忧伤吗？","t":[103,6039]}]},{"id":"ch06p13","audio":"ch06p13.mp3","sents":[{"ar":"الصغير لم يعطِ أي جواب.","zh":"小王子默然不语。","t":[103,2339]}]}]},{"id":"ch07","title_ar":"الفصل السابع","title_en":"Chapter VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":"ch07p00.mp3","sents":[{"ar":"في اليوم الخامس، ومرة ثانية يعود الفضل إلى الخروف، تكشَّف لي سر حياة الأمير الصغير. فمن","zh":"第五天——又像往常一样，多亏了那只绵羊——小王子生活的秘密向我透露了出来。","t":[103,9171]},{"ar":"دون أي تمهيد، وكأن ذلك نتيجة تفكير عميق في مشكلة، سألني على حين غرة:","zh":"他突然提出，仿佛这个问题经过他长时间的沉默深思才诞生出来。","t":[9171,16394]}]},{"id":"ch07p01","audio":"ch07p01.mp3","sents":[{"ar":"- إن أكل الخروف الشجيرات، هل","zh":"绵羊若吃小灌木，也会吃花吗？","t":[103,2813]}]},{"id":"ch07p02","audio":"ch07p02.mp3","sents":[{"ar":"يأكل الأزهار أيضًا؟","zh":"绵羊，见什么吃什么。","t":[103,1813]}]},{"id":"ch07p03","audio":"ch07p03.mp3","sents":[{"ar":"- الخروف يأكل كل ما يصادفه.","zh":"连带刺的花也吃吗？","t":[103,2642]}]},{"id":"ch07p04","audio":"ch07p04.mp3","sents":[{"ar":"- حتى الأزهار ذات الأشواك؟","zh":"是的，连带刺的花也吃。","t":[103,2063]}]},{"id":"ch07p05","audio":"ch07p05.mp3","sents":[{"ar":"- أجل، حتى الأزهار","zh":"那刺还有什么用呢？","t":[103,2023]}]},{"id":"ch07p06","audio":"ch07p06.mp3","sents":[{"ar":"ذات الأشواك. -","zh":"我不知其所以然。","t":[103,2197]},{"ar":"الأشواك.. ما الفائدة منها؟ لم أعرف السبب؛","zh":"那时我正忙于拧下卡在发动机里的螺栓。","t":[2197,8013]},{"ar":"كنت منهمكًا أحاول فك مسمار علق في محركي، وكنت في أشد","zh":"我深感忧虑，因为我的飞机故障显然极其严重。","t":[8013,13289]},{"ar":"القلق لأن تحطم طائرتي بدأ يبدو لي أمرًا خطيرًا جدًّا،","zh":"我剩下的饮用水寥寥无几，不禁担忧着最坏的结果。","t":[13289,18066]}]},{"id":"ch07p07","audio":"ch07p07.mp3","sents":[{"ar":"فمياه الشرب بدأت","zh":"刺，它们有何用？","t":[103,1721]}]},{"id":"ch07p08","audio":"ch07p08.mp3","sents":[{"ar":"تنفد بسرعة ولم أستطع إلا خشية","zh":"小王子一旦提问，便锲而不舍。","t":[103,3024]},{"ar":"الأسوأ. - الأشواك - ما الفائدة منها؟","zh":"至于我，那螺栓让我心烦意乱。","t":[3024,8355]},{"ar":"لم يكن الأمير","zh":"我随口答道：","t":[8355,9632]}]},{"id":"ch07p09","audio":"ch07p09.mp3","sents":[{"ar":"الصغير ليتخلى","zh":"刺毫无用处。","t":[103,1484]},{"ar":"عن سؤال يطرحه في أي","zh":"花儿长刺，只为泄愤。","t":[1484,3537]}]},{"id":"ch07p10","audio":"ch07p10.mp3","sents":[{"ar":"وقت.","zh":"哦！","t":[103,748]}]},{"id":"ch07p11","audio":"ch07p11.mp3","sents":[{"ar":"كنت قلقًا بشأن","zh":"一时寂静无声。","t":[103,1418]},{"ar":"مسماري فأجبت بأول شيء خطر في بالي: - إن","zh":"小王子带着一丝怨恨，向我闪过一瞥。","t":[1418,5471]}]},{"id":"ch07p12","audio":"ch07p12.mp3","sents":[{"ar":"الأشواك عديمة الفائدة.","zh":"我不信你的话！","t":[103,3105]},{"ar":"الأزهار تكتسبها","zh":"花儿是脆弱的生物。","t":[3105,4592]},{"ar":"لمجرد الأذية.","zh":"她们天真无邪。","t":[4592,6868]},{"ar":"وبعد لحظة صمت، قال بنوع","zh":"她们尽力自我安慰。","t":[6868,9461]},{"ar":"من الازدراء: - لا أصدقك؛ إن الأزهار","zh":"它们以为自己的刺是可怕的武器……","t":[9461,12737]}]},{"id":"ch07p13","audio":"ch07p13.mp3","sents":[{"ar":"ضعيفة. إنها","zh":"我默然不语。","t":[103,2211]},{"ar":"ساذجة، وهي تضمن أنفسها بأفضل ما يمكن. إنها تعتقد بأن أشواكها رهيبة... لم أجب. وكنت أقول في تلك اللحظة لنفسي: « إن استمر","zh":"那一刻，我自言自语道：“如果这颗螺栓还是拧不动，我就用锤子把它砸下来。”小王子又一次打断了我在思考。","t":[2211,16461]}]},{"id":"ch07p14","audio":"ch07p14.mp3","sents":[{"ar":"هذا المسمار في مقاومتي،","zh":"而你竟然相信花儿——","t":[103,2247]}]},{"id":"ch07p15","audio":"ch07p15.mp3","sents":[{"ar":"سأضربه بالمطرقة ».","zh":"哦，不！我惊呼。","t":[103,2789]},{"ar":"ومرة أخرى","zh":"不，不，不！","t":[2789,3882]},{"ar":"تدخل الأمير الصغير","zh":"我不信任何事。","t":[3882,5355]},{"ar":"في أفكاري: - وهل تعتقد فعلًا بأن الأزهار... - لا!","zh":"随口应道，我脑海中浮现的第一个念头便是答案。","t":[5355,10658]},{"ar":"لا! لا أعتقد شيئًا. لقد أجبت","zh":"您忙于正事，无暇他顾。","t":[10658,15500]}]},{"id":"ch07p16","audio":"ch07p16.mp3","sents":[{"ar":"كيفما كان. إنني منهمك","zh":"他瞪着我，惊愕不已。","t":[103,3486]}]},{"id":"ch07p17","audio":"ch07p17.mp3","sents":[{"ar":"في أمور مهمة.","zh":"事关重大！","t":[103,1537]}]},{"id":"ch07p18","audio":"ch07p18.mp3","sents":[{"ar":"حدق إليَّ بدهشة تامة. - أمور مهمة؟ استطاع أن يراني والمطرقة في يدي وأصابعي سوداء من شحم","zh":"他瞧着我，手里握着锤子，指头沾满了发动机的机油，俯身对着在他看来极其丑陋的物件。","t":[103,9986]}]},{"id":"ch07p19","audio":"ch07p19.mp3","sents":[{"ar":"المحرك، أنحني فوق شيء بدا....","zh":"你说话就像大人一样！","t":[103,3181]}]},{"id":"ch07p20","audio":"ch07p20.mp3","sents":[{"ar":"قبيحًا للغاية. -","zh":"这让我感到有些羞愧。","t":[103,2408]},{"ar":"تتحدث مثل الكبار تماما. جعلني","zh":"但他却继续说，毫不留情。","t":[2408,6540]}]},{"id":"ch07p21","audio":"ch07p21.mp3","sents":[{"ar":"هذا أشعر بالخجل. أضاف مثابرًا:","zh":"你把一切都搅和在一起……","t":[103,4289]},{"ar":"- إنك تفسد كل شيء...","zh":"你把一切都混为一谈……","t":[4289,6157]}]},{"id":"ch07p22","audio":"ch07p22.mp3","sents":[{"ar":"تخلط كل شيء. كان","zh":"他真的非常生气。","t":[103,2855]},{"ar":"غاضبًا حقًّا. أخذ يحرك خصل شعره","zh":"他金黄色的卷发在风中飘扬。","t":[2855,6935]}]},{"id":"ch07p23","audio":"ch07p23.mp3","sents":[{"ar":"الذهبية في الريح: - أعرف كوكبًا حيث يوجد سيد","zh":"我知道有一个星球上住着一位红脸先生。","t":[103,4287]},{"ar":"ذو وجه أحمر، لم يسبق","zh":"他未曾嗅过一瓣花。","t":[4287,6471]},{"ar":"له أن شم زهرة. لم ينظر","zh":"他从未仰望过一颗星星。","t":[6471,9645]},{"ar":"قط إلى نجمة، لم يحب","zh":"他从未爱过任何人。","t":[9645,11842]},{"ar":"أحدًا، أمضى حياته","zh":"他一生只做加法。","t":[11842,13763]},{"ar":"كلها وهو يجمع الأرقام. كان يردد مثلك طوال النهار: إنني منهمك بأمور مهمة، إنني منهمك","zh":"他整天反复说着，就像你一样：“我正忙于要紧的事！”这让他骄傲得膨胀起来。","t":[13763,21395]},{"ar":"بأمور مهمة. مرارًا وتكرارًا وهو ينتفخ","zh":"但他并非凡人——他只是一朵蘑菇！","t":[21395,28131]}]},{"id":"ch07p24","audio":"ch07p24.mp3","sents":[{"ar":"كبرياء. لكنه ليس","zh":"“这是什么？”","t":[103,3000]}]},{"id":"ch07p25","audio":"ch07p25.mp3","sents":[{"ar":"رجلًا،","zh":"蘑菇！","t":[103,985]}]},{"id":"ch07p26","audio":"ch07p26.mp3","sents":[{"ar":"إنه فطر. - ماذا؟ - فطر.","zh":"小王子气得脸色煞白。","t":[103,4079]}]},{"id":"ch07p27","audio":"ch07p27.mp3","sents":[{"ar":"شحب وجه الأمير الصغير من","zh":"花儿已长刺数百万年。","t":[103,2155]},{"ar":"الغضب. - إن الأزهار تنتج الأشواك منذ","zh":"数百万年来，绵羊一直这样吃着它们。","t":[2155,6026]},{"ar":"ملايين السنين، وعلى مدى ملايين السنين تأكل الخراف الأزهار. أليس جديرًا","zh":"探究为何花儿费尽心机长出无用的刺，这难道不是一件重要的事吗？","t":[6026,12961]},{"ar":"بالاهتمام بذل الجهد لمحاولة فهم","zh":"羊与花的战争难道不重要吗？","t":[12961,15737]},{"ar":"لماذا تنتج الأشواك التي لا فائدة منها؟ أليست","zh":"这难道不是比那位红脸胖子的算术更重要吗？","t":[15737,20382]},{"ar":"الحرب بين الخراف والأزهار مهمة؟ أليست أكثر جدية وأكثر أهمية من مبالغ أموال السيد ذي الوجه الأحمر؟ وإذا أنا علمت بأمر زهرة فريدة من نوعها في العالم لا تنمو في أي مكان غير كوكبي ويمكن","zh":"哦！若我深知——我自己——世间仅此一朵独一无二的花，它只生长在我的星球，而一只小小的绵羊却能在某个清晨不经意间将它一口吞噬，甚至未曾察觉自己的行为——哦！","t":[20382,38447]},{"ar":"لخروف صغير أن","zh":"这难道不重要吗？","t":[38447,40013]}]},{"id":"ch07p28","audio":"ch07p28.mp3","sents":[{"ar":"يتلفها بقضمة واحدة، ببساطة هكذا،","zh":"他的脸色由白转红，继续说道：","t":[103,3945]}]},{"id":"ch07p29","audio":"ch07p29.mp3","sents":[{"ar":"ذات صباح، من دون أن يدرك ماذا يفعل، أليس هذا مهمًّا؟ احمر وجهه وتابع: - إذا أحب شخص ما زهرة","zh":"若有人爱上了一朵生长在亿万星辰中的一朵花，只需仰望星空，便足以使他心满意足。","t":[103,10066]},{"ar":"وحيدة على ملايين النجوم، النظر إليها يجعله سعيدًا، ويستطيع القول لنفسه: إن زهرتي في مكان ما هناك في الخارج...","zh":"他可以对自己说：“我的花儿在那儿……”但若绵羊吃掉了那朵花，他的所有星星在一瞬间都将黯淡无光……","t":[10066,21145]},{"ar":"وإذا أكل الخروف الزهرة، وبدا له أن النجوم","zh":"这难道不重要吗？他再也无法说下去了。","t":[21145,24803]},{"ar":"كافة أصبحت مظلمة فجأة!","zh":"他的话语被抽泣所哽咽。","t":[24803,27263]}]},{"id":"ch07p30","audio":"ch07p30.mp3","sents":[{"ar":"فأنت تعتقد بأن","zh":"夜幕降临。","t":[103,1589]},{"ar":"الأمر غير مهم! لم يستطع","zh":"我手中的工具纷纷落地。","t":[1589,4855]},{"ar":"قول المزيد لأن الدموع غلبته. هبط الليل، تركت عدتي، لم","zh":"我的锤子、螺栓、干渴或死亡，此刻又算得了什么？","t":[4855,11013]},{"ar":"أعد أكترث بمطرقتي ومسماري، بالعطش أو الموت، فهنالك","zh":"在地球，我的星球上，有一个小王子需要安慰。","t":[11013,16434]},{"ar":"على نجم، كوكب، هو الأرض، أمير صغير","zh":"将他紧紧抱在怀里，轻轻摇晃着他。","t":[16434,20303]},{"ar":"ينبغي تهدئته!","zh":"我对他说：","t":[20303,21645]}]},{"id":"ch07p31","audio":"ch07p31.mp3","sents":[{"ar":"حملته بذراعي وجعلته يتأرجح","zh":"你爱的那朵花并无危险。","t":[103,2984]},{"ar":"بلطف. قلت له: - ليست","zh":"我给你那绵羊画个口罩。","t":[2984,6132]},{"ar":"الزهرة التي تحب في خطر، سأرسم","zh":"我为你那朵花画一道栅栏。","t":[6132,9263]},{"ar":"لك كمامة","zh":"我将——","t":[9263,10303]}]},{"id":"ch07p32","audio":"ch07p32.mp3","sents":[{"ar":"لخروفك، سأرسم سياجًا لزهرتك...","zh":"我不知该如何向他开口。","t":[103,4171]},{"ar":"لم أعرف حقًّا","zh":"我感到尴尬而笨拙。","t":[4171,5316]},{"ar":"ماذا أقول له. شعرت بارتباك شديد، لم أعرف كيف أصل إليه وكيف ألحق به... إن","zh":"我不知如何才能追上他，在哪里才能与他并肩前行，再次携手同行。","t":[5316,13671]}]},{"id":"ch07p33","audio":"ch07p33.mp3","sents":[{"ar":"بلاد الدموع غامضة جدًّا.","zh":"泪水的王国，如此神秘。","t":[103,2379]}]}]},{"id":"ch08","title_ar":"الفصل الثامن","title_en":"Chapter VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":"ch08p00.mp3","sents":[{"ar":"سرعان ما تعلمت أن أعرف هذه الزهرة على نحو أفضل.","zh":"我很快便更深入地了解了这朵花。","t":[103,5342]},{"ar":"هنالك أزهار بسيطة جدًّا على كوكب الأمير الصغير، لها حلقة واحدة من البتلات، تحتل","zh":"小王子的星球上，花朵总是极为朴素。","t":[5342,13197]},{"ar":"فسحة صغيرة جدًّا ولا تتسبب بأي مشكلة لأي إنسان. كانت تظهر ذات صباح في","zh":"花瓣仅一环，不占空间，不惹尘埃。","t":[13197,21013]},{"ar":"العشب ثم تذوي في المساء. وفي يوم من الأيام، بذرة هبت من حيث لا أحد يدري، نبتت زهرة جديدة؛","zh":"清晨它们在草间绽放，夜晚便平静地凋谢。","t":[21013,30855]},{"ar":"وراقب الأمير الصغير عن كثب الفروع الصغيرة التي لا تشبه أبدًا الفروع الأخرى على كوكبه.","zh":"然而，一天，一朵来自无人知晓之处的种子发芽了；小王子密切地关注着这株与众不同的嫩芽，它不同于他星球上其他任何嫩芽。","t":[30855,38724]},{"ar":"ربما هي نوع جديد من الباوباب. وسرعان ما توقفت","zh":"或许，它可能是一种新型的猴面包树。","t":[38724,44145]}]},{"id":"ch08p01","audio":"ch08p01.mp3","sents":[{"ar":"النبتة عن النمو وبدأت تنمو زهرة. وفيما كان الأمير","zh":"灌木很快停止了生长，开始准备绽放花朵。","t":[103,5342]},{"ar":"الصغير يراقب نمو برعم كبير، أدرك أن ذلك يمكن أن يؤدي إلى ظهور عجائبي، لكن","zh":"小王子目睹那硕大的花蕾初现，便预感其中将诞生某种奇迹般的景象。","t":[5342,12882]},{"ar":"الزهرة واصلت الإعداد، لجمالها في ملجأ تجويفها الأخضر، اختارت ألوانها","zh":"但那朵花并不满足于只在绿屋的庇护下完成她美丽的准备。","t":[12882,19289]},{"ar":"بعناية فائقة. اكتست ببطء،","zh":"她挑选色彩极是用心。","t":[19289,23092]},{"ar":"ونسقت بتلاتها بعناية","zh":"她逐一调整着花瓣。","t":[23092,25158]},{"ar":"الواحدة بعد الأخرى. لم تشأ أن تبدو متغضنة كالخشخاش، شاءت","zh":"她不愿像野罂粟花那样，皱巴巴地闯进世界。","t":[25158,31671]},{"ar":"فقط أن تظهر بكل تألقها وجمالها. أوه","zh":"她只愿在美丽绽放的极致中露面。","t":[31671,36132]},{"ar":"نعم! كانت","zh":"哦，是的！","t":[36132,38092]},{"ar":"متكبرة جدًّا! استغرقت","zh":"她是个爱美的生灵。","t":[38092,41276]},{"ar":"استعداداتها الخفية أيامًا وأيامًا، ثم","zh":"她的神秘装扮持续了好多天。","t":[41276,45052]}]},{"id":"ch08p02","audio":"ch08p02.mp3","sents":[{"ar":"ذات صباح، عندما كانت الشمس تشرق، أظهرت نفسها فجأة.","zh":"就在一个清晨，正逢日出时分，她突然现身。","t":[103,5418]}]},{"id":"ch08p03","audio":"ch08p03.mp3","sents":[{"ar":"وبعد أن عملت بجد وبذلت مثل ذلك الجهد، تثاءبت وقالت: - آه!","zh":"经过这番苦心孤诣的精心打扮，她打了个哈欠说道：","t":[103,6050]}]},{"id":"ch08p04","audio":"ch08p04.mp3","sents":[{"ar":"أنا","zh":"唉！","t":[103,458]},{"ar":"نصف يقظة... سامحوني... فأنا ما","zh":"我刚刚醒来，尚感朦胧。","t":[458,5105]},{"ar":"زلت غير مرتبة... لكن","zh":"请您原谅我的冒昧。","t":[5105,8211]},{"ar":"الأمير الصغير لم يستطع أن","zh":"我的花瓣仍凌乱不堪……","t":[8211,10421]}]},{"id":"ch08p05","audio":"ch08p05.mp3","sents":[{"ar":"يخفي إعجابه، فقال: - أوه،","zh":"小王子忍不住赞叹：","t":[103,2708]}]},{"id":"ch08p06","audio":"ch08p06.mp3","sents":[{"ar":"كم","zh":"哦！","t":[103,326]},{"ar":"أنت جميلة!","zh":"您真美啊！","t":[326,1405]}]},{"id":"ch08p07","audio":"ch08p07.mp3","sents":[{"ar":"ألست كذلك؟ أجابت الزهرة بلطف: -","zh":"“是啊，”花儿柔声回应。","t":[103,4276]},{"ar":"لقد وُلدت في الوقت الذي","zh":"我与太阳同日而生。","t":[4276,6237]}]},{"id":"ch08p08","audio":"ch08p08.mp3","sents":[{"ar":"أشرقت فيه الشمس... كان على الأمير الصغير أن يعترف بأنها لم تكن متواضعة وأنها فاتنة","zh":"小王子不难看出她并不怎么谦逊——然而她是多么动人——多么令人兴奋！","t":[103,8277]}]},{"id":"ch08p09","audio":"ch08p09.mp3","sents":[{"ar":"للغاية! - أعتقد بأن وقت الفطور قد حان، (أضافت بعد","zh":"她随即又补充道：“现在是吃早餐的时候了。”","t":[103,5645]},{"ar":"لحظة) هلا تفضلت لتلبي حاجاتي؟","zh":"若您能体谅我的所需——","t":[5645,8974]}]},{"id":"ch08p10","audio":"ch08p10.mp3","sents":[{"ar":"في الحال جلب الأمير الصغير بارتباك تام","zh":"小王子羞愧难当，去找一壶清水。","t":[103,3011]},{"ar":"وعاء نثر منه الماء العذب على","zh":"于是，他照料着这朵花。","t":[3011,5708]}]},{"id":"ch08p11","audio":"ch08p11.mp3","sents":[{"ar":"الزهرة. وهكذا شرعت منذ البداية تعذبه بكبريائها الملحاحة. وعلى سبيل المثال، قالت ذات يوم","zh":"于是，她很快便开始用她的虚荣心折磨他——若真相大白，这实在有些难以应对。","t":[103,9803]},{"ar":"للأمير الصغير وهي تشير إلى أشواكها الأربعة: - ليأت النمور","zh":"有一天，当她谈到她那四根刺时，她对小王子说：","t":[9803,14632]}]},{"id":"ch08p12","audio":"ch08p12.mp3","sents":[{"ar":"بمخالبهم. اعترض الأمير الصغير:","zh":"让老虎带着它们的爪子来吧！","t":[103,4105]}]},{"id":"ch08p13","audio":"ch08p13.mp3","sents":[{"ar":"- لكن ليس هنالك نمور على كوكبي،","zh":"我的星球上没有老虎。","t":[103,3234]},{"ar":"وفي أي حال، لا تأكل","zh":"老虎不吃杂草。","t":[3234,5603]}]},{"id":"ch08p14","audio":"ch08p14.mp3","sents":[{"ar":"النمور الأعشاب الضارة. قالت الزهرة برقة: -","zh":"“我不是杂草。”花儿柔声回答。","t":[103,4369]}]},{"id":"ch08p15","audio":"ch08p15.mp3","sents":[{"ar":"لكنني لست عشبة","zh":"请原谅……","t":[103,1826]}]},{"id":"ch08p16","audio":"ch08p16.mp3","sents":[{"ar":"ضارة. - رجاء سامحيني... - لا أخاف النمور، لكنني أكره","zh":"“我对老虎毫不畏惧，却最怕穿堂风。”","t":[103,5842]},{"ar":"تيارات الهواء، ألن تأتيني","zh":"您这儿有屏风吗？","t":[5842,8328]}]},{"id":"ch08p17","audio":"ch08p17.mp3","sents":[{"ar":"بستارة؟ أشار الأمير الصغير وهو يفكر في نفسه: « رعب من تيَّارات الهواء... إن ذلك لحظ سيئ حقًّا بالنسبة إلى نبتة، وإن هذه الزهرة لهي بالفعل مخلوق معقد","zh":"“对穿堂风如此恐惧——这对植物来说可真是不幸，”小王子评论道，心中暗想，“这朵花真是个复杂的生物……”","t":[103,15737]}]},{"id":"ch08p18","audio":"ch08p18.mp3","sents":[{"ar":"جدًّا ». - في المساء أريد أن تضعني تحت قبة","zh":"夜晚，请您把我罩在玻璃球里。","t":[103,4539]},{"ar":"زجاجية؛ البرد قارس جدًّا هنا","zh":"你住的地方非常寒冷。","t":[4539,7566]},{"ar":"حيث تعيش. إن هذا الأمر غير","zh":"在我来的那个地方——","t":[7566,11184]}]},{"id":"ch08p19","audio":"ch08p19.mp3","sents":[{"ar":"مريح. والآن من حيث أنا أتيت...","zh":"她话未说完便打住了。","t":[103,4829]},{"ar":"قاطعت نفسها بعد وقت متأخر، لقد","zh":"她以种子的形式降临。","t":[4829,8053]},{"ar":"وصلَت كحبة، ولم تكن تعرف شيئًا عن","zh":"她不可能了解任何其他世界。","t":[8053,11461]},{"ar":"العوالم الأخرى، وعندما أحست بالارتباك لاكتشافها حقيقة هذا الوضع الساذج، سعلت مرات عدة كي تربك الأمير الصغير. -","zh":"羞愧于让自己陷入如此幼稚谎言的边缘，她咳嗽了两三声，企图让小王子承担过错。","t":[11461,22960]}]},{"id":"ch08p20","audio":"ch08p20.mp3","sents":[{"ar":"أين الستارة؟ - أردت","zh":"您有屏风吗？","t":[103,2697]}]},{"id":"ch08p21","audio":"ch08p21.mp3","sents":[{"ar":"أن آتي بها لكنك كنت تتحدثين إلي! عندئذ سعلت","zh":"我正要去找，是你和我说话的呀……","t":[103,5802]}]},{"id":"ch08p22","audio":"ch08p22.mp3","sents":[{"ar":"أكثر كي يشعر بالندم، وهكذا، على الرغم من النية الطيبة","zh":"她故意咳嗽得更重，让他也感到内疚。","t":[103,5458]}]},{"id":"ch08p23","audio":"ch08p23.mp3","sents":[{"ar":"التي ولدها حبه تجاهها، بدأ الأمير الصغير شيئًا فشيئًا يرتاب بها. أخذ كلمات ليست","zh":"尽管小王子对她的爱中充满了善意，但他很快便开始怀疑她了。","t":[103,8645]},{"ar":"بذي أهمية على محمل الجد وأصبح حزينًا جدًّا. أفضى لي بدخيلة نفسه ذات","zh":"他认真对待了无关紧要的话语，这让他非常不快乐。","t":[8645,16000]}]},{"id":"ch08p24","audio":"ch08p24.mp3","sents":[{"ar":"يوم: - كان ينبغي لي ألا أصغي","zh":"我那天不该听她的话。","t":[103,2655]},{"ar":"لها. لا ينبغي أن يصغي المرء إلى","zh":"永远也别信花儿讲的话。","t":[2655,6171]},{"ar":"الأزهار. على المرء أن يُعجب بها ويتنشق عطرها.","zh":"只需凝视它们，感受它们的芬芳。","t":[6171,12132]},{"ar":"لقد عطرت زهرتي كوكبي، لكنني","zh":"我的星球上弥漫着花香。","t":[12132,15263]},{"ar":"لم أعرف كيف أستمتع بها. كان ينبغي لحكاية","zh":"但我不知如何享受她的所有优雅。","t":[15263,19658]},{"ar":"المخالب التي أزعجتني كثيرًا أن تلامس قلبي ببساطة.. وأفضى","zh":"这关于爪子的故事，本应只在我心中激起温柔与怜悯。","t":[19658,25684]}]},{"id":"ch08p25","audio":"ch08p25.mp3","sents":[{"ar":"بالمزيد: - آنذاك","zh":"他继续倾诉着。","t":[103,2129]}]},{"id":"ch08p26","audio":"ch08p26.mp3","sents":[{"ar":"لم أستطع أن أفهم شيئًا! كان يجب أن أبني حكمي","zh":"事实上，我并不懂得如何理解任何事物！","t":[103,4974]},{"ar":"طبقًا للأفعال وليس للكلمات. لقد","zh":"应凭行为而非言语来评判。","t":[4974,9000]},{"ar":"غمرتني بعبيرها وتألقها. كان ينبغي","zh":"她的芬芳与光辉洒落在我身上。","t":[9000,13276]},{"ar":"ألا أهرب منها! كان ينبغي","zh":"我本不该逃离她……","t":[13276,16421]},{"ar":"أن أكتشف المحبة الكامنة وراء حيلها الصغيرة البسيطة،","zh":"我本应猜透她那可怜的小伎俩背后深藏的柔情。","t":[16421,21026]},{"ar":"فالأزهار متقلبة جدًّا!","zh":"花儿真是反复无常！","t":[21026,24184]},{"ar":"وقد كنت صغيرًا جدًّا، فلم أعرف كيف أحبها.","zh":"那时我还太年轻，不懂如何去爱她……","t":[24184,28276]}]}]},{"id":"ch09","title_ar":"الفصل التاسع","title_en":"Chapter IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":"ch09p00.mp3","sents":[{"ar":"يخامرني شعور بأنه من أجل هروبه، استغل هجرة الطيور","zh":"他可能是趁着那群野鸟迁徙之际逃离的。","t":[103,4892]},{"ar":"البرية. في صباح يوم رحيله رتب كوكبه بشكل تام؛ كنس","zh":"他离开那天早晨，把他的星球整理得井井有条。","t":[4892,11039]},{"ar":"براكينه النَشِطة بعناية. كان يملك","zh":"他仔细清理了他的活火山。","t":[11039,15000]},{"ar":"بركانين نشطين، ملائمين تمامًا لتسخين فطوره في الصباح.","zh":"他拥有两座活火山，早晨煮早餐极为方便。","t":[15000,21145]},{"ar":"وكان يملك أيضًا بركانًا خامدًا.","zh":"他还拥有一座熄灭的火山。","t":[21145,24776]},{"ar":"أشار قائلًا: « لا يمكنك أن تعرف! »، ونظف البركان الخامد أيضًا، فالبراكين","zh":"然而，正如他所说：“世事难料！”于是，他也清理了那座死火山。","t":[24776,32039]},{"ar":"إذا ما نُظفت جيدًا، فإنها تتوقد بلطف وانتظام، من دون أي انفجارات.","zh":"火山清理得当，火焰便缓缓而稳定地燃烧，不会喷发。","t":[32039,39553]},{"ar":"إن الانفجارات البركانية هي مثل","zh":"火山喷发犹如烟囱中的火焰。","t":[39553,42290]}]},{"id":"ch09p01","audio":"ch09p01.mp3","sents":[{"ar":"نيران المدفأة. ونحن على الأرض صغار جدًّا بالطبع، فلا نكنس براكيننا،","zh":"在我们地球上，我们显然太小了，无法清理我们的火山。","t":[103,7566]},{"ar":"لذلك تتسبب لنا في كثير من المتاعب. اقتلع الأمير","zh":"这便是它们给我们带来无尽烦恼的原因。","t":[7566,13210]}]},{"id":"ch09p02","audio":"ch09p02.mp3","sents":[{"ar":"الصغير، من دون شعور بالأسف، آخر براعم الباوباب؛ كان يعتقد","zh":"小王子带着一丝沮丧，拔除了最后几株猴面包树苗。","t":[103,5958]},{"ar":"بأنه لن تتوجب عليه العودة، وهذه","zh":"他坚信自己不会再想回来。","t":[5958,9234]},{"ar":"النشاطات المألوفة بدت له ثمينة جدًّا في ذلك الصباح الأخير، وعندما روى الزهرة لآخر","zh":"然而，在这最后的早晨，所有这些熟悉的任务在他看来都变得异常珍贵。","t":[9234,16118]},{"ar":"مرة وتأهب لوضعها تحت قبتها الزجاجية، أحس برغبة في البكاء. قال للزهرة: - وداعًا. لكنها لم تجب،","zh":"最后一次为花儿浇水，准备给她罩上玻璃罩，他意识到自己几乎要泪流满面了。","t":[16118,27605]}]},{"id":"ch09p03","audio":"ch09p03.mp3","sents":[{"ar":"فقال ثانية: - وداعًا.","zh":"再见，他对花儿说。","t":[103,2261]}]},{"id":"ch09p04","audio":"ch09p04.mp3","sents":[{"ar":"فأخذت الزهرة","zh":"她默然不语。","t":[103,1471]}]},{"id":"ch09p05","audio":"ch09p05.mp3","sents":[{"ar":"بالسعال، لكن ليس لأنها","zh":"再见，他又说。","t":[103,2919]}]},{"id":"ch09p06","audio":"ch09p06.mp3","sents":[{"ar":"مصابة بالبرد.","zh":"花儿轻咳。","t":[103,2447]},{"ar":"همست أخيرًا: - لقد كنت","zh":"但并非因为她感冒了。","t":[2447,4776]}]},{"id":"ch09p07","audio":"ch09p07.mp3","sents":[{"ar":"سخيفة. أرجوك سامحني. حاول أن تكون سعيدًا.","zh":"她终于对他说：“我真是愚蠢。”","t":[103,6921]},{"ar":"أصابته","zh":"请原谅我。","t":[6921,7579]},{"ar":"الدهشة من انعدام التأنيب.","zh":"试着快乐吧……","t":[7579,9619]}]},{"id":"ch09p08","audio":"ch09p08.mp3","sents":[{"ar":"وقف هناك مرتبكًا، والقبة","zh":"她对他的离去毫无责怪。","t":[103,2932]},{"ar":"محتفظة بتوازنها وسط الهواء. لم يفهم هذه العذوبة الهادئة.","zh":"他愣愣地站在那里，手中的玻璃罩悬停在半空。","t":[2932,10039]},{"ar":"نظَّف مداخن براكينه النشطة.","zh":"他不懂这宁静的甜美。","t":[10039,12566]}]},{"id":"ch09p09","audio":"ch09p09.mp3","sents":[{"ar":"قالت له الزهرة:","zh":"当然，我爱你。","t":[103,1563]},{"ar":"- طبعًا، أنا أحبك. إذا لم تكن تدرك ذلك فذلك","zh":"你一直未曾察觉到，这全是我的过错。","t":[1563,6829]},{"ar":"خطئي. إن هذا","zh":"那无关紧要。","t":[6829,9145]},{"ar":"ليس مهمًّا. لقد كنت أحمق مثلي.","zh":"但你——你也和我一样傻。","t":[9145,14000]},{"ar":"حاول أن تكون سعيدًا،","zh":"试着快乐吧……","t":[14000,16053]},{"ar":"اترك تلك القبة وشأنها،","zh":"让玻璃罩见鬼去吧。","t":[16053,18487]},{"ar":"فأنا لم أعد أريدها.","zh":"我不再需要它了。","t":[18487,20263]}]},{"id":"ch09p10","audio":"ch09p10.mp3","sents":[{"ar":"- لكن الريح...","zh":"但风……","t":[103,1248]}]},{"id":"ch09p11","audio":"ch09p11.mp3","sents":[{"ar":"- إن البرد الذي أصابني ليس","zh":"我的感冒并没有那么严重……","t":[103,2116]},{"ar":"سيئًا جدًّا... سيفيدني هواء الليل","zh":"清新的夜风对我大有裨益。","t":[2116,5789]},{"ar":"المنعش، فأنا زهرة.","zh":"我是一朵花。","t":[5789,7803]}]},{"id":"ch09p12","audio":"ch09p12.mp3","sents":[{"ar":"- لكن ماذا بشأن","zh":"但那些动物——","t":[103,1603]}]},{"id":"ch09p13","audio":"ch09p13.mp3","sents":[{"ar":"الحيوانات؟ - علي أن أتحمل قلة من اليرقانات إذا ما أردت","zh":"我若想结识蝴蝶，就得忍受两三条毛虫的陪伴。","t":[103,5868]},{"ar":"مشاهدة الفراشات، أفهم","zh":"它们似乎非常美丽。","t":[5868,8197]},{"ar":"أنها جميلة جدًّا. وإلا من سيقوم بزيارتي؟","zh":"蝴蝶不来，毛虫又何来拜访我呢？","t":[8197,14145]},{"ar":"أنت ستكون","zh":"你将远行……","t":[14145,15118]},{"ar":"بعيدًا، أما الحيوانات الضخمة، فأنا لا أخشاها؛","zh":"至于大动物——我一点也不怕它们。","t":[15118,19526]},{"ar":"لدي مخالبي. وبسذاجة","zh":"我有我的爪子。","t":[19526,22895]}]},{"id":"ch09p14","audio":"ch09p14.mp3","sents":[{"ar":"تامة، كشفت عن أشواكها الأربعة.","zh":"她天真地伸出她的四根刺。","t":[103,4092]},{"ar":"ثم أضافت قائلة:","zh":"她接着说：","t":[4092,5697]}]},{"id":"ch09p15","audio":"ch09p15.mp3","sents":[{"ar":"- لا تتردد","zh":"别这样拖延。","t":[103,1063]},{"ar":"هكذا، إن هذا مزعج.","zh":"你已决定离去。","t":[1063,4250]},{"ar":"لقد عزمت على","zh":"那就走吧。","t":[4250,5632]}]},{"id":"ch09p16","audio":"ch09p16.mp3","sents":[{"ar":"الرحيل، فارحل. لم تشأ أن يراها","zh":"她不愿让他看到自己哭泣。","t":[103,4079]},{"ar":"تبكي؛ كانت زهرة متعجرفة كثيرًا...","zh":"她是一朵多么骄傲的花儿……","t":[4079,7566]}]}]},{"id":"ch10","title_ar":"الفصل العاشر","title_en":"Chapter X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":"ch10p00.mp3","sents":[{"ar":"وجد نفسه في جوار الكويكبات ٣٢٦، ٣٢٧، ۳۲۸، ۳۲۹، ۳۳۰. فبدأ","zh":"他发现自己来到了小行星325号、326号、327号、328号、329号和330号所在的地区。","t":[103,11158]},{"ar":"يزورها ليبحث عن عمل وليضيف","zh":"于是他开始逐一拜访，以增长见识。","t":[11158,11658]}]},{"id":"ch10p01","audio":"ch10p01.mp3","sents":[{"ar":"إلى معرفته.","zh":"那颗星球上住着一位国王。","t":[103,2211]},{"ar":"كان الكويكب الأول يقطنه ملك، جلس على عرش بسيط وفخم، وقد ارتدى فرو القاقم وثوبًا","zh":"身着皇家紫袍与貂皮，他端坐在既简单又威严的宝座上。","t":[2211,10514]}]},{"id":"ch10p02","audio":"ch10p02.mp3","sents":[{"ar":"أر","zh":"啊！","t":[103,445]},{"ar":"جوانيًّا. هتف الملك عندما رأى الأمير الصغير: - آه، لقد أتى أحد الرعايا.","zh":"“来了一位臣民，”国王看见小王子走来，大声说道。","t":[445,7711]}]},{"id":"ch10p03","audio":"ch10p03.mp3","sents":[{"ar":"وتساءل الأمير الصغير:","zh":"小王子自问：","t":[103,2011]}]},{"id":"ch10p04","audio":"ch10p04.mp3","sents":[{"ar":"- كيف عرفني مع أنه لم يرني من قبل؟! لم يكن","zh":"他从未见过我，怎能认出我呢？","t":[103,4789]}]},{"id":"ch10p05","audio":"ch10p05.mp3","sents":[{"ar":"يعرف أن العالم بالنسبة إلى الملوك مبسَّط","zh":"国王们眼中，世界变得简单了。","t":[103,3418]},{"ar":"للغاية، فجميع الناس رعايا لهم. قال الملك","zh":"在他们眼中，世人皆为臣民。","t":[3418,8447]}]},{"id":"ch10p06","audio":"ch10p06.mp3","sents":[{"ar":"وقد شعر بفخر جامح لأن لديه أخيرًا من يستطيع أن يكون ملكًا عليه: - اقترب قليلًا كي أتمكن من رؤيتك على نحو أفضل.","zh":"“走近些，让我好好端详你，”国王说，他因终于统治了某个臣民而感到无比自豪。","t":[103,10023]}]},{"id":"ch10p07","audio":"ch10p07.mp3","sents":[{"ar":"نظر الأمير الصغير حوله كي يجد مكانًا للجلوس، إلا أن الكوكب بأسره كان مغطى بالثوب المصنوع من فرو القاقم.","zh":"小王子环顾四周，寻找可坐之处；但整个星球已被国王那华丽的貂皮袍子塞满，无处下脚。","t":[103,10289]},{"ar":"وهكذا لبث واقفًا، وبما أنه كان تَعِبًا، أخذ يتثاءب.","zh":"他挺直了身子站立，由于疲惫，他打了个哈欠。","t":[10289,15815]}]},{"id":"ch10p08","audio":"ch10p08.mp3","sents":[{"ar":"قال الملك: - إنه من غير اللائق","zh":"在国王面前打哈欠，有失礼节。","t":[103,2576]},{"ar":"أن تتثاءب بحضور ملك.","zh":"我禁止你这么做。","t":[2576,4774]}]},{"id":"ch10p09","audio":"ch10p09.mp3","sents":[{"ar":"أنا أحظره.","zh":"我忍不住了。","t":[103,2079]},{"ar":"رد الأمير الصغير بارتباك: - لا أستطيع المقاومة؛","zh":"我忍不住了，小王子回答说，满脸尴尬。","t":[2079,6329]},{"ar":"لقد قمت برحلة طويلة ولم أنم","zh":"我长途跋涉，未曾合眼……","t":[6329,9355]}]},{"id":"ch10p10","audio":"ch10p10.mp3","sents":[{"ar":"قط... قال الملك: - في","zh":"啊，那么，国王说。","t":[103,2921]},{"ar":"هذه الحال آمرك بالتثاؤب.","zh":"我命令你打哈欠。","t":[2921,6184]},{"ar":"لم أجد أحدًا يتثاءب منذ","zh":"多年来未见有人打哈欠了。","t":[6184,8447]},{"ar":"سنوات. التثاؤب أمر غريب بالنسبة","zh":"打哈欠在我眼里是件稀奇事。","t":[8447,12671]},{"ar":"لي. هيا،","zh":"快点儿！","t":[12671,14605]},{"ar":"تثاءب مرة أخرى.","zh":"再打一个哈欠！","t":[14605,17197]},{"ar":"إنه أمر. قال","zh":"这是命令。","t":[17197,19644]}]},{"id":"ch10p11","audio":"ch10p11.mp3","sents":[{"ar":"الأمير الصغير وقد","zh":"这让我害怕……","t":[103,1655]},{"ar":"احمر وجهه: - أنت تخيفني... لم أعد","zh":"我无法再……小王子羞愧地低语。","t":[1655,5974]}]},{"id":"ch10p12","audio":"ch10p12.mp3","sents":[{"ar":"أستطيع","zh":"哼！","t":[103,668]},{"ar":"التثاؤب... أجاب","zh":"哼！国王答道。","t":[668,2842]},{"ar":"الملك: - هم هم، إذًا آمرك أن تتثاءب أحيانًا، وأحيانًا أن...","zh":"那么，我——我命令你有时打哈欠，有时不打——","t":[2842,8552]}]},{"id":"ch10p13","audio":"ch10p13.mp3","sents":[{"ar":"همهم قليلًا وبدا مغتاظًا. أعطى","zh":"他咕哝了几句，似乎有些恼火。","t":[103,3987]}]},{"id":"ch10p14","audio":"ch10p14.mp3","sents":[{"ar":"الملك أهمية كبرى لاحترام سلطته. لم يحتمل أي عصيان.","zh":"国王根本坚持的是他的权威必须得到尊重。","t":[103,6816]},{"ar":"إنه ملك ذو سلطة","zh":"他不容许任何违抗。","t":[6816,8421]},{"ar":"مطلقة، لكن بما أنه طيب جدًّا،","zh":"他是一位绝对的君主。","t":[8421,11763]},{"ar":"فقد أعطى أوامر معقولة. كان بوسعه أن يقول: « إذا أمرت قائدًا أن يحول","zh":"然而，由于他是个非常善良的人，他发布的命令总是合情合理。","t":[11763,18908]}]},{"id":"ch10p15","audio":"ch10p15.mp3","sents":[{"ar":"نفسه إلى طائر بحري، وإذا لم يطع القائد الأمر، فإن ذلك ليس خطأ القائد، بل خطئي لأنني أمرته بالقيام بشيء مستحيل ».","zh":"“假如我命令一位将军，”他举例说，“假如我命令他变成一只海鸟，而将军不服从，那责任不在将军。”","t":[103,12013]},{"ar":"قال الأمير الصغير","zh":"那责任在我。","t":[12013,13539]}]},{"id":"ch10p16","audio":"ch10p16.mp3","sents":[{"ar":"بحياء: - هل يمكنني أن أجلس؟ - آمرك بالجلوس.","zh":"小王子怯生生地问道：“我可以坐下吗？”","t":[103,5211]}]},{"id":"ch10p17","audio":"ch10p17.mp3","sents":[{"ar":"(أجاب الملك وهو يجمع حوله بترفع ثنايا ثوبه المصنوع من فرو القاقم).","zh":"陛下如此命令，国王答道，威严地卷起他的貂皮披风。","t":[103,5984]}]},{"id":"ch10p18","audio":"ch10p18.mp3","sents":[{"ar":"وقع الأمير الصغير في","zh":"小王子心中暗自思忖……","t":[103,1589]},{"ar":"الحيرة؛ الكوكب صغير، فمن","zh":"这颗星球小得可怜。","t":[1589,4392]},{"ar":"يحكم هذا الملكُ حقًّا؟! بدأ يقول:","zh":"这位国王究竟能统治什么？","t":[4392,8276]}]},{"id":"ch10p19","audio":"ch10p19.mp3","sents":[{"ar":"- سيدي، أرجو أن تسمح لي بأن أطرح عليك سؤالًا. أسرع الملك","zh":"陛下，他向他说道，请您原谅我向您提一个问题——","t":[103,6527]}]},{"id":"ch10p20","audio":"ch10p20.mp3","sents":[{"ar":"مجيبًا: - آمرك بطرح سؤالك علي. - سيدي، من تحكم؟ أجاب","zh":"陛下急忙保证道：“我命令你向我提一个问题。”","t":[103,8013]}]},{"id":"ch10p21","audio":"ch10p21.mp3","sents":[{"ar":"الملك ببساطة شديدة: - أحكم كل","zh":"陛下——您统治着什么？","t":[103,3405]}]},{"id":"ch10p22","audio":"ch10p22.mp3","sents":[{"ar":"شيء. - كل شيء؟ أشار الملك بيده إشارة شاملة","zh":"统治一切，国王以非凡的简洁说道。","t":[103,6185]}]},{"id":"ch10p23","audio":"ch10p23.mp3","sents":[{"ar":"جمعت كوكبه","zh":"统治一切？","t":[103,1326]}]},{"id":"ch10p24","audio":"ch10p24.mp3","sents":[{"ar":"والكواكب الأخرى والنجوم. قال الأمير الصغير: - كل هذا؟ أجاب الملك:","zh":"国王一挥手，涵盖了他的星球、其他星球以及所有星星。","t":[103,7552]}]},{"id":"ch10p25","audio":"ch10p25.mp3","sents":[{"ar":"- كل هذا. لم يكن حاكمًا مطلقًا","zh":"统治这一切？小王子问道。","t":[103,3829]}]},{"id":"ch10p26","audio":"ch10p26.mp3","sents":[{"ar":"فحسب، بل كان حاكمًا كونيًّا.","zh":"统治这一切？国王回答道。","t":[103,2906]}]},{"id":"ch10p27","audio":"ch10p27.mp3","sents":[{"ar":"- وهل تمتثل النجوم؟ قال الملك: - طبعًا، إنها","zh":"他的统治不仅是绝对的，而且是普遍的。","t":[103,5474]}]},{"id":"ch10p28","audio":"ch10p28.mp3","sents":[{"ar":"تمتثل فورًا، فأنا لا أحتمل","zh":"星星都听命于您吗？","t":[103,2932]}]},{"id":"ch10p29","audio":"ch10p29.mp3","sents":[{"ar":"العصيان. دُهش الأمير","zh":"当然啦，国王说。","t":[103,2895]},{"ar":"الصغير من هذه","zh":"它们立刻服从。","t":[2895,4000]},{"ar":"السلطة. فلو أنه","zh":"我禁止违抗。","t":[4000,6553]}]},{"id":"ch10p30","audio":"ch10p30.mp3","sents":[{"ar":"امتلكها لاستطاع أن يراقب أربعة","zh":"这股力量令小王子惊叹不已。","t":[103,2866]},{"ar":"وأربعين، بل اثنين وسبعين أو حتى مئة أو مئتي غروب في اليوم نفسه، من دون أن يحرك كرسيه! وبما أنه أحس بشيء من الحزن عندما تذكر","zh":"若他拥有如此至高无上的权力，便能每日观赏七十二次，甚至一百次，甚至两百次日落，而无需挪动座椅。","t":[2866,15408]},{"ar":"كوكبه الصغير المهجور، استجمع شجاعته ليطلب معروفًا من الملك. - أود أن","zh":"因为想起被他遗弃的小行星，他鼓起勇气向国王提出一个请求：","t":[15408,22869]}]},{"id":"ch10p31","audio":"ch10p31.mp3","sents":[{"ar":"أشاهد غروبًا، أرجوك،","zh":"我想看看日落……","t":[103,2537]},{"ar":"حقق لي ذلك، أعطِ","zh":"请行此善举……","t":[2537,4247]},{"ar":"الشمس أمرًا كي تغيب...","zh":"命令太阳落山……","t":[4247,6090]}]},{"id":"ch10p32","audio":"ch10p32.mp3","sents":[{"ar":"- لو أمرت قائدًا أن يطير من زهرة إلى أخرى كفراشة، أو يكتب مأساة، أو أن يحول نفسه إلى طائر بحري، ولم ينفذ القائد الأمر، فمن منا يكون على خطأ؟ قال الأمير الصغير بحزم: - أنت","zh":"陛下质问道：“若我命令一位将军像蝴蝶般在花间飞舞，或撰写一部悲剧，或变成海鸟，而将军不遵从命令，那么，错的是我们中的哪一个？”","t":[103,16895]},{"ar":"ستكون على خطأ. - تمامًا.","zh":"将军，还是我自己？","t":[16895,20092]}]},{"id":"ch10p33","audio":"ch10p33.mp3","sents":[{"ar":"على المرء أن يطلب من كل شخص","zh":"“你，”小王子坚定地说。","t":[103,2405]}]},{"id":"ch10p34","audio":"ch10p34.mp3","sents":[{"ar":"ما يستطيعه،","zh":"正是如此。","t":[103,1326]},{"ar":"فالسلطة ترتكز أولًا وأخيرًا على العقل. إذا أمرت شعبك بأن يلقوا","zh":"国王继续说道：“每个人都必须尽其所能履行职责。”","t":[1326,7658]},{"ar":"بأنفسهم إلى البحر، فإنك ستشعل ثورة.","zh":"权威首先建立在理性之上。","t":[7658,12224]},{"ar":"أنا لي الحق في طلب الطاعة لأن أوامري معقولة. - وماذا","zh":"若你命令你的子民跳海，他们便会起义反抗。","t":[12224,17395]},{"ar":"عن طلبي لغروب الشمس؟ ذكَّره الأمير الصغير بهذا الأمر،","zh":"我有权要求服从，因为我的命令合乎情理。","t":[17395,22671]}]},{"id":"ch10p35","audio":"ch10p35.mp3","sents":[{"ar":"لأنه لم يكن ينسى أبدًا سؤالًا طرحه ذات مرة. - ستحصل على طلبك لغروب الشمس، سآمر به. لكن","zh":"“那么，我的日落呢？”小王子提醒他，因为他一旦提出问题就绝不会忘记。","t":[103,10421]}]},{"id":"ch10p36","audio":"ch10p36.mp3","sents":[{"ar":"طبقًا لمنطق الحكومة العلمية","zh":"你将看到你的日落。","t":[103,2326]},{"ar":"سأتريث إلى","zh":"我命令它。","t":[2326,3392]},{"ar":"أن تكون الظروف مؤاتية. سأل الأمير الصغير: - ومتى","zh":"但根据我的治国之策，我将等待时机成熟。","t":[3392,8697]}]},{"id":"ch10p37","audio":"ch10p37.mp3","sents":[{"ar":"يكون ذلك؟ - هم! هم! (أجاب الملك مستشيرا","zh":"小王子问道：“那会是什么时候？”","t":[103,6803]}]},{"id":"ch10p38","audio":"ch10p38.mp3","sents":[{"ar":"روزنامته)","zh":"哼！","t":[103,1326]},{"ar":"سيكون ذلك حوالي... حوالي... سيكون ذلك هذا المساء","zh":"哼！国王答道，随即查阅了一本厚重的星历。","t":[1326,7539]},{"ar":"حوالي","zh":"哼！","t":[7539,8039]},{"ar":"الثامنة","zh":"哼！","t":[8039,8697]},{"ar":"إلا ثلث. ولسوف ترى كم تُطاع أوامري. تثاءب الأمير","zh":"大约——大约——今晚八点差二十分左右。","t":[8697,15039]},{"ar":"الصغير، أسِف على أن يفوته غروب الشمس، وبدأ يشعر","zh":"你将见识到我的命令被遵从得多么得体。","t":[15039,20013]}]},{"id":"ch10p39","audio":"ch10p39.mp3","sents":[{"ar":"بالسأم. قال للملك: - ليس","zh":"小王子打了个哈欠。","t":[103,3553]},{"ar":"لدي ما أفعله هنا، سأمضي في","zh":"他惋惜那失去的日落。","t":[3553,6118]},{"ar":"طريقي. قال الملك الذي شعر بالفخر","zh":"他渐渐开始感到有些无聊了。","t":[6118,10039]}]},{"id":"ch10p40","audio":"ch10p40.mp3","sents":[{"ar":"لحصوله على تابع: - لا ترحل، سأجعل منك وزيرًا. -","zh":"“我在这里已无事可做，”他对国王说。","t":[103,5921]},{"ar":"وزيرًا لأي وزارة؟ - وزيرًا...","zh":"我将再次踏上旅程。","t":[5921,9368]}]},{"id":"ch10p41","audio":"ch10p41.mp3","sents":[{"ar":"وزيرًا للعدل. - لكن ما من أحد هنا لأحكم عليه! قال الملك: -","zh":"“别走，”国王说，他对拥有一个臣民感到非常自豪。","t":[103,7197]},{"ar":"نحن لا","zh":"别走。","t":[7197,7816]},{"ar":"نعرف ذلك، فأنا لم أقم","zh":"我封你为部长！","t":[7816,10329]}]},{"id":"ch10p42","audio":"ch10p42.mp3","sents":[{"ar":"بعد بجولة","zh":"司法部长？","t":[103,1353]}]},{"id":"ch10p43","audio":"ch10p43.mp3","sents":[{"ar":"كاملة على مملكتي.","zh":"司法部长！","t":[103,1971]}]},{"id":"ch10p44","audio":"ch10p44.mp3","sents":[{"ar":"أنا متقدم في السن","zh":"但这里无人可审。","t":[103,1919]}]},{"id":"ch10p45","audio":"ch10p45.mp3","sents":[{"ar":"والمشي يتعبني، ولا مجال هنا من استخدام","zh":"“我们并不知道，”国王对他说。","t":[103,3682]},{"ar":"عربة. قال الأمير الصغير وهو ينحني","zh":"我尚未巡游完我的王国。","t":[3682,7342]},{"ar":"ليلقي نظرة","zh":"我年事已高。","t":[7342,8447]},{"ar":"أخرى متفحصة على الجانب","zh":"这里容不下马车。","t":[8447,10526]},{"ar":"الآخر من الكوكب: - أوه!","zh":"行走令我疲惫不堪。","t":[10526,12711]}]},{"id":"ch10p46","audio":"ch10p46.mp3","sents":[{"ar":"لقد نظرت الآن. أجاب الملك: - إن هذا لهو أصعب شيء على الإطلاق. إن من الصعب جدًّا","zh":"哦，但我已经看过了！小王子转身，又朝星球的另一端瞥了一眼。","t":[103,8816]},{"ar":"أن تحكم نفسك، بل وأصعب من أن تحكم الآخرين. إن حكمت","zh":"在那一边，就像这边一样，根本无人居住。","t":[8816,14816]}]},{"id":"ch10p47","audio":"ch10p47.mp3","sents":[{"ar":"على نفسك بعدل، تكون حكيمًا","zh":"那么，你将自我审判。","t":[103,2787]},{"ar":"جدًّا بالفعل.","zh":"这是最难的事。","t":[2787,4776]},{"ar":"قال الأمير الصغير: - فيما يختص بي،","zh":"评判自己远比评判他人困难。","t":[4776,8066]},{"ar":"أستطيع أن أحكم على نفسي حيثما كان. ليس علي أن أقيم","zh":"若能正确审判自己，你便真正成为智者。","t":[8066,13922]}]},{"id":"ch10p48","audio":"ch10p48.mp3","sents":[{"ar":"هنا. قال الملك: - هم! هم! أعتقد بأنه يوجد جرذ عجوز في مكان ما","zh":"是的，小王子说，“但我在任何地方都能审判自己。”","t":[103,9079]},{"ar":"على كوكبي، يمكنني أن أسمعه في الليل.","zh":"我不必居住在这颗星球上。","t":[9079,12618]}]},{"id":"ch10p49","audio":"ch10p49.mp3","sents":[{"ar":"يمكنك","zh":"哼！","t":[103,787]},{"ar":"أن تحكم هذا","zh":"哼！国王说道。","t":[787,1747]},{"ar":"الجرذ العجوز. ولسوف تحكم عليه بالموت من وقت إلى آخر. وهكذا","zh":"在这颗星球上，我确信某个角落住着一只老耗子。","t":[1747,9237]},{"ar":"تعتمد حياته على عدلك.","zh":"我在夜里听到他。","t":[9237,12382]},{"ar":"لكن ستصفح عنه في كل مناسبة لكي","zh":"你可以审判这只老耗子。","t":[12382,15421]},{"ar":"تبقيه على قيد الحياة؛","zh":"时而将他判处死刑。","t":[15421,17579]},{"ar":"إنه الوحيد لدينا. أجاب الأمير الصغير:","zh":"他的生命将取决于你的公正。","t":[17579,21961]},{"ar":"- لا أحب أن أحكم على أي شيء بالموت، وأعتقد بأن عليَّ","zh":"但每次你都得赦免他；因为他必须被节省使用。","t":[21961,26632]},{"ar":"المضي في طريقي. قال الملك:","zh":"他是我们唯一拥有的。","t":[26632,29974]}]},{"id":"ch10p50","audio":"ch10p50.mp3","sents":[{"ar":"- لا. وبعد أن أتم الأمير الصغير","zh":"我不愿将任何人判处死刑。","t":[103,3395]},{"ar":"استعداداته، لم يشأ أن يؤذي مشاعر","zh":"现在我想继续我的旅程了。","t":[3395,6619]}]},{"id":"ch10p51","audio":"ch10p51.mp3","sents":[{"ar":"الملك العجوز، فقال:","zh":"“不，”国王说。","t":[103,2431]}]},{"id":"ch10p52","audio":"ch10p52.mp3","sents":[{"ar":"- إذا رغبت يا صاحب الجلالة في أن تُطاع فورًا، فعليك أن تعطيني","zh":"但小王子完成离行准备后，不愿让老国王感到悲伤。","t":[103,5405]}]},{"id":"ch10p53","audio":"ch10p53.mp3","sents":[{"ar":"أمرًا معقولًا. تستطيع مثلًا أن تأمرني بالرحيل في أقل","zh":"陛下若欲令行禁止，便应能下达合理的命令。","t":[103,5447]},{"ar":"من دقيقة. يبدو لي أن الظروف ملائمة. وعندما لم يقل","zh":"他可以命令我，比如说，在一分钟内离开。","t":[5447,11474]},{"ar":"الملك شيئًا، تردد الأمير لحظة، ثم غادر","zh":"在我看来，条件似乎很适宜……","t":[11474,15500]}]},{"id":"ch10p54","audio":"ch10p54.mp3","sents":[{"ar":"متنهدًا. صاح الملك بسرعة: - سأجعلك سفيرًا","zh":"国王沉默不语，小王子犹豫了片刻。","t":[103,5171]},{"ar":"لي. وكان لديه فراغ كبير في السلطة.","zh":"带着一声叹息，他告辞离去。","t":[5171,9381]}]},{"id":"ch10p55","audio":"ch10p55.mp3","sents":[{"ar":"قال الأمير الصغير","zh":"我封你为大使。","t":[103,1629]}]},{"id":"ch10p56","audio":"ch10p56.mp3","sents":[{"ar":"وهو يتابع رحلته:","zh":"他威严非凡。","t":[103,1853]}]},{"id":"ch10p57","audio":"ch10p57.mp3","sents":[{"ar":"- إن الكبار غريبو الأطوار!","zh":"大人们真是奇怪，小王子边走边自言自语。","t":[103,2182]}]}]},{"id":"ch11","title_ar":"الفصل الحادي عشر","title_en":"Chapter XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":"ch11p00.mp3","sents":[{"ar":"كان الكوكب الثاني يقطنه شخص مغرور، صاح","zh":"第二颗星球住着一个自负的人。","t":[103,4050]}]},{"id":"ch11p01","audio":"ch11p01.mp3","sents":[{"ar":"عن","zh":"啊！","t":[103,379]},{"ar":"بعد","zh":"啊！","t":[379,787]},{"ar":"عندما وقع نظره على الأمير الصغير: - لقد أتى شخص معجب بنفسه! فالرجال المغرورون يرون","zh":"他远远望见小王子走来，便大声喊道：“我正要接待一位崇拜者！”","t":[787,9224]}]},{"id":"ch11p02","audio":"ch11p02.mp3","sents":[{"ar":"سائر الرجال معجبين بأنفسهم. قال الأمير الصغير:","zh":"对自负的人来说，所有人都是崇拜者。","t":[103,5184]}]},{"id":"ch11p03","audio":"ch11p03.mp3","sents":[{"ar":"- صباح الخير، أنت تلبس","zh":"早上好，小王子说。","t":[103,2274]},{"ar":"قبعة مضحكة. أجاب الرجل","zh":"这顶帽子戴得真古怪。","t":[2274,5697]}]},{"id":"ch11p04","audio":"ch11p04.mp3","sents":[{"ar":"المغرور: - إنها قبعة للترحيب،","zh":"这顶帽子是敬礼用的。","t":[103,3182]},{"ar":"أرفعها عندما يهلل لي الناس. لسوء الحظ، ما","zh":"这顶帽子是人们欢呼时用来敬礼的。","t":[3182,8197]},{"ar":"من أحد يمر في هذه الطريق. - حقًّا؟","zh":"可惜，从来没有人经过这里。","t":[8197,12144]}]},{"id":"ch11p05","audio":"ch11p05.mp3","sents":[{"ar":"(قال الأمير الصغير الذي لم يفهم ما الذي يتحدث عنه الرجل المغرور). وقال","zh":"小王子问道：“什么？”他不懂这位自负的人究竟在说什么。","t":[103,6869]}]},{"id":"ch11p06","audio":"ch11p06.mp3","sents":[{"ar":"الرجل المغرور ناصحًا: - صفق بيديك. صفق الأمير الصغير بيديه. رفع الرجل","zh":"请用手掌相击，一只手对另一只手，自负的人现在这样指示他。","t":[103,8566]}]},{"id":"ch11p07","audio":"ch11p07.mp3","sents":[{"ar":"المغرور قبعته في تحية","zh":"小王子拍起了手。","t":[103,2339]},{"ar":"متواضعة. خاطب الأمير الصغير نفسه:","zh":"自负的人谦恭地举帽致意。","t":[2339,6302]}]},{"id":"ch11p08","audio":"ch11p08.mp3","sents":[{"ar":"« إن هذا مسلٍّ أكثر من زيارتي إلى الملك »، وحاول أن","zh":"这比拜访国王有趣多了，小王子自言自语道。","t":[103,4300]},{"ar":"يصفق بيديه ثانية. ومرة أخرى رفع الرجل","zh":"他再次开始拍手，一只手对另一只手。","t":[4300,9118]},{"ar":"المغرور قبعته في تحية. وبعد خمس","zh":"自负的人举起帽子行礼。","t":[9118,13434]}]},{"id":"ch11p09","audio":"ch11p09.mp3","sents":[{"ar":"دقائق من هذا التمرين سئم الأمير الصغير من رتابة","zh":"五分钟后，小王子对这场单调的游戏感到厌倦。","t":[103,4208]}]},{"id":"ch11p10","audio":"ch11p10.mp3","sents":[{"ar":"اللعبة. سأله: - ولكي تخفض قبعتك، ماذا ينبغي للمرء أن","zh":"他问道：“那怎样才能让这顶帽子放下呢？”","t":[103,6777]}]},{"id":"ch11p11","audio":"ch11p11.mp3","sents":[{"ar":"يفعل؟ لكن الرجل المغرور لم","zh":"但自负的人没有听见他。","t":[103,3408]},{"ar":"يسمعه، فالمغرورون يسمعون المديح","zh":"自负的人只听见赞美之词。","t":[3408,6592]}]},{"id":"ch11p12","audio":"ch11p12.mp3","sents":[{"ar":"فقط. - هل أنت معجب بي كثيرًا؟ سأل الأمير الصغير:","zh":"你真的非常崇拜我吗？他向小王子质问道。","t":[103,6053]}]},{"id":"ch11p13","audio":"ch11p13.mp3","sents":[{"ar":"- وماذا تعني كلمة ( يُعجب)؟","zh":"那“崇拜”究竟是什么意思？","t":[103,2510]}]},{"id":"ch11p14","audio":"ch11p14.mp3","sents":[{"ar":"- (يُعجب بـ) تعني أن تعدني الشخص الأكثر وسامة، الأكثر أناقة، الأغنى والأذكى في هذا الكوكب.","zh":"您认为我是这星球上最英俊、最讲究衣着、最富有、最聪明的人。","t":[103,8129]}]},{"id":"ch11p15","audio":"ch11p15.mp3","sents":[{"ar":"- لكنك وحيد على كوكبك! - قدِّم لي هذه الخدمة.","zh":"但你是你那星球上唯一的人！","t":[103,4935]}]},{"id":"ch11p16","audio":"ch11p16.mp3","sents":[{"ar":"عبِّر عن إعجابك","zh":"请行此善举。","t":[103,1418]},{"ar":"بي! قال الأمير الصغير","zh":"依旧崇拜我吧。","t":[1418,4276]}]},{"id":"ch11p17","audio":"ch11p17.mp3","sents":[{"ar":"وهو يهز كتفيه بلا مبالاة: - إنني معجب بك، لكن لماذا ينبغي أن يعني ذلك الكثير لك؟ ورحل الأمير الصغير، وقال في","zh":"“我崇拜你，”小王子轻轻耸了耸肩，“但这又有什么能让你如此高兴呢？”","t":[103,11763]}]},{"id":"ch11p18","audio":"ch11p18.mp3","sents":[{"ar":"نفسه وهو يتابع رحلته:","zh":"小王子离去了。","t":[103,2392]}]},{"id":"ch11p19","audio":"ch11p19.mp3","sents":[{"ar":"« إن الكبار غريبو الأطوار حقًّا ».","zh":"大人们确实古怪得可以，他边走边自言自语。","t":[103,2563]}]}]},{"id":"ch12","title_ar":"الفصل الثاني عشر","title_en":"Chapter XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":"ch12p00.mp3","sents":[{"ar":"كان الكوكب التالي","zh":"下一颗星球住着一个酒徒。","t":[103,1405]},{"ar":"يقطنه سكير، فكانت هذه","zh":"这次拜访虽短，却让小王子陷入深深的忧郁。","t":[1405,3971]}]},{"id":"ch12p01","audio":"ch12p01.mp3","sents":[{"ar":"الزيارة قصيرة جدًّا، لكنها أصابت الأمير الصغير","zh":"“你在此做什么？”他对那个酒徒说，只见他静静地坐在面前的一大堆空瓶子和满瓶之间。","t":[103,4787]}]},{"id":"ch12p02","audio":"ch12p02.mp3","sents":[{"ar":"بحزن عميق. قال للسكير","zh":"“我正喝着呢，”酒徒带着哀伤的神情答道。","t":[103,3474]}]},{"id":"ch12p03","audio":"ch12p03.mp3","sents":[{"ar":"الذي وجده جالسًا","zh":"“你为何饮酒？”小王子质问道。","t":[103,1905]}]},{"id":"ch12p04","audio":"ch12p04.mp3","sents":[{"ar":"صامتًا أمام","zh":"为了忘记，酒徒答道。","t":[103,1379]}]},{"id":"ch12p05","audio":"ch12p05.mp3","sents":[{"ar":"مجموعة من الزجاجات البعض منها","zh":"“为了什么？”小王子问，心中已对他生出了怜悯。","t":[103,2827]}]},{"id":"ch12p06","audio":"ch12p06.mp3","sents":[{"ar":"فارغ والبعض ملآن: - ماذا","zh":"“忘了我说我羞愧吧，”酒徒低垂着头，老实承认。","t":[103,2866]}]},{"id":"ch12p07","audio":"ch12p07.mp3","sents":[{"ar":"تفعل هنا؟ أجاب السكير بكآبة:","zh":"“羞愧什么？”小王子坚持问道，他想要帮助他。","t":[103,3882]}]},{"id":"ch12p08","audio":"ch12p08.mp3","sents":[{"ar":"- أنا... أشرب. سأل الأمير الصغير:","zh":"羞愧于饮酒！酒徒话音戛然而止，将自己封闭在坚不可摧的沉默之中。","t":[103,4605]}]},{"id":"ch12p09","audio":"ch12p09.mp3","sents":[{"ar":"- لماذا تشرب؟","zh":"小王子困惑地走了。","t":[103,1260]}]},{"id":"ch12p10","audio":"ch12p10.mp3","sents":[{"ar":"أجاب السكير: - كي أنسى.","zh":"大人们确实非常、非常古怪，他边走边自言自语。","t":[103,2208]}]}]},{"id":"ch13","title_ar":"الفصل الثالث عشر","title_en":"Chapter XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":"ch13p00.mp3","sents":[{"ar":"كان الكوكب الرابع يخص رجل أعمال،","zh":"第四颗星球属于一个商人。","t":[103,3287]},{"ar":"وكان منهمكًا جدًّا، حتى إنه لم يرفع نظره عندما وصل الأمير الصغير إليه. قال له","zh":"这位商人如此忙碌，以至于在小王子到来时，连头都没抬一下。","t":[3287,11395]}]},{"id":"ch13p01","audio":"ch13p01.mp3","sents":[{"ar":"الأمير الصغير: - صباح الخير.","zh":"早上好，小王子对他说。","t":[103,3618]},{"ar":"لقد انطفأت سيجارتك! -","zh":"您的香烟熄灭了。","t":[3618,7250]}]},{"id":"ch13p02","audio":"ch13p02.mp3","sents":[{"ar":"ثلاثة زائد اثنين يساوي","zh":"三加二等于五。","t":[103,2011]},{"ar":"خمسة. خمسة زائد سبعة","zh":"五加七等于十二。","t":[2011,4737]},{"ar":"يساوي اثني عشر. اثنا عشر زائد","zh":"十二加三等于十五。","t":[4737,8329]},{"ar":"ثلاثة يساوي","zh":"早上好。","t":[8329,9368]},{"ar":"خمسة عشر. صباح الخير. خمسة","zh":"十五加七等于二十二。","t":[9368,13776]},{"ar":"عشر زائد سبعة يساوي اثنين وعشرين.","zh":"二十二加六等于二十八。","t":[13776,17803]},{"ar":"اثنان وعشرون زائد","zh":"没空再点一根。","t":[17803,19447]},{"ar":"ستة يساوي ثمانية وعشرين. لا وقت","zh":"二十六加五等于三十一。","t":[19447,23408]},{"ar":"لدي كي","zh":"哎呀！","t":[23408,24066]},{"ar":"أشعلها ثانية. ستة وعشرون زائد خمسة يساوي واحدًا","zh":"五亿零一百六十二万二千七百三十一。","t":[24066,29908]}]},{"id":"ch13p03","audio":"ch13p03.mp3","sents":[{"ar":"وثلاثين. أف! إن ذلك يساوي مليونًا وخمسمئة، اثنان وعشرون","zh":"五亿零一百……这是什么？小王子问道。","t":[103,7776]}]},{"id":"ch13p04","audio":"ch13p04.mp3","sents":[{"ar":"ألفًا","zh":"哎呀？","t":[103,550]},{"ar":"وستمئة، سبعمئة","zh":"您还在吗？","t":[550,2155]},{"ar":"وواحد وثلاثون. - خمسمئة مليون من ماذا؟ - أوه!","zh":"五亿零一百万——我无法停下...","t":[2155,8921]},{"ar":"هل ما زلت هناك؟","zh":"我事务繁多。","t":[8921,11263]},{"ar":"مليون وخمسمئة من... لا أتذكر!","zh":"我关注的是重要之事。","t":[11263,16184]},{"ar":"- لدي الكثير من العمل! إنني رجل جدي، ولا أسلي","zh":"我从不浪费时间在无聊的事情上。","t":[16184,21487]},{"ar":"نفسي بالهراء! اثنان","zh":"二加五等于七……","t":[21487,24460]}]},{"id":"ch13p05","audio":"ch13p05.mp3","sents":[{"ar":"زائد خمسة يساوي سبعة... - مليون وخمسمئة من ماذا؟ كرر الأمير الصغير الذي لم يتخل في حياته عن سؤال","zh":"五亿零一百万个什么？小王子反复问道，他一生中一旦提问就绝不会放弃。","t":[103,9947]}]},{"id":"ch13p06","audio":"ch13p06.mp3","sents":[{"ar":"طرحه ذات مرة. رفع رجل","zh":"商人抬起了头。","t":[103,3658]}]},{"id":"ch13p07","audio":"ch13p07.mp3","sents":[{"ar":"الأعمال رأسه. - لم أقاطَع إلا ثلاث مرات خلال الأربع وخمسين سنة من","zh":"在这颗星球上居住的五十四年里，我只被打扰过三次。","t":[103,6684]},{"ar":"عمري على هذا الكوكب. كانت المرة الأولى منذ اثنتين وعشرين سنة بواسطة دودة بيضاء","zh":"第一次是二十二年前，不知从何而来的疯子一头栽了下来。","t":[6684,14579]},{"ar":"هبطت الله يعلم من أين. لقد أصدرت أكثر ضجة إزعاجًا، فاقترفتُ","zh":"他发出震耳欲聋的巨响，我的加法出了四个错。","t":[14579,21092]},{"ar":"أربعة أخطاء أثناء الجمع. وكانت المرة الثانية منذ إحدى عشرة","zh":"第二次，十一年前，我被关节炎的发作打扰。","t":[21092,27053]},{"ar":"سنة بواسطة نوبة","zh":"我缺乏锻炼。","t":[27053,28816]},{"ar":"روماتزم، فأنا لا","zh":"我无暇闲逛。","t":[28816,30461]},{"ar":"أقوم بتمارين كافية. لا وقت لدي للتراخي،","zh":"第三次——嗯，就是这一次！","t":[30461,35461]},{"ar":"فأنا رجل جدي. المرة الثالثة... حسنًا، هذه هي","zh":"那么，我接着说，五亿零一百万——","t":[35461,42000]}]},{"id":"ch13p08","audio":"ch13p08.mp3","sents":[{"ar":"المرة الثالثة! ومثلما كنت","zh":"五亿零一百万个什么？","t":[103,3698]}]},{"id":"ch13p09","audio":"ch13p09.mp3","sents":[{"ar":"أقول، مليون وخمسمئة... - مليون من ماذا؟ أدرك رجل الأعمال فجأة أنه لا أمل في تركه","zh":"商人突然意识到，除非回答这个问题，否则他永远无法安宁。","t":[103,8855]}]},{"id":"ch13p10","audio":"ch13p10.mp3","sents":[{"ar":"بسلام. - من تلك الأجسام الصغيرة التي يراها المرء أحيانًا","zh":"那些小小的东西，有时在天空里可以看到。","t":[103,5578]}]},{"id":"ch13p11","audio":"ch13p11.mp3","sents":[{"ar":"في السماء.","zh":"苍蝇吗？","t":[103,892]}]},{"id":"ch13p12","audio":"ch13p12.mp3","sents":[{"ar":"- ذباب؟ -","zh":"哦，不。","t":[103,2316]},{"ar":"أوه، لا. أجسام صغيرة","zh":"小小的闪烁之物。","t":[2316,5053]}]},{"id":"ch13p13","audio":"ch13p13.mp3","sents":[{"ar":"لامعة. - نحل؟","zh":"蜜蜂吗？","t":[103,2395]}]},{"id":"ch13p14","audio":"ch13p14.mp3","sents":[{"ar":"- أوه، لا.","zh":"哦，不。","t":[103,2118]},{"ar":"أجسام صغيرة ذهبية تجعل الرجال الكسالى يحلمون أحلامًا لا جدوى منها.","zh":"那金色的小东西，让闲散的人沉醉于梦幻之中。","t":[2118,9039]},{"ar":"إنني رجل جدي! ولا وقت لدي للأحلام","zh":"至于我，我只关心重要的事。","t":[9039,13368]},{"ar":"الجوفاء. - آه! أنت تعني النجوم. -","zh":"生活中不容我闲散做梦。","t":[13368,19460]}]},{"id":"ch13p15","audio":"ch13p15.mp3","sents":[{"ar":"أجل، إنها","zh":"哎呀！","t":[103,1261]},{"ar":"النجوم. - وماذا تفعل","zh":"您是指星星吗？","t":[1261,4263]}]},{"id":"ch13p16","audio":"ch13p16.mp3","sents":[{"ar":"بخمسمئة مليون نجمة؟ -","zh":"是的，就是这样。","t":[103,3092]},{"ar":"خمسمئة","zh":"星星。","t":[3092,3934]}]},{"id":"ch13p17","audio":"ch13p17.mp3","sents":[{"ar":"ومليون، ستمئة واثنان وعشرون ألفًا،","zh":"你用五亿颗星星做什么呢？","t":[103,3892]}]},{"id":"ch13p18","audio":"ch13p18.mp3","sents":[{"ar":"سبعمئة وواحد وثلاثون. أنا رجل جدي. أنا دقيق. - وماذا","zh":"五亿零一百六十二万二千七百三十一","t":[103,8105]},{"ar":"تفعل بخمسمئة مليون نجمة؟ - خمسمئة ومليون،","zh":"我专注于重要之事：我追求精确。","t":[8105,13171]}]},{"id":"ch13p19","audio":"ch13p19.mp3","sents":[{"ar":"ستمئة واثنان وعشرون ألفًا، سبعمئة","zh":"您用这些星星做什么呢？","t":[103,3510]}]},{"id":"ch13p20","audio":"ch13p20.mp3","sents":[{"ar":"وواحد وثلاثون. - وماذا تفعل","zh":"我拿它们怎么办呢？","t":[103,4000]}]},{"id":"ch13p21","audio":"ch13p21.mp3","sents":[{"ar":"بها؟ -","zh":"是的。","t":[102,2263]}]},{"id":"ch13p22","audio":"ch13p22.mp3","sents":[{"ar":"ماذا أفعل بها؟","zh":"没什么。","t":[103,2513]},{"ar":"لا شيء. أمتلكها.","zh":"我拥有它们。","t":[2513,5237]}]},{"id":"ch13p23","audio":"ch13p23.mp3","sents":[{"ar":"- أنت تمتلك النجوم؟!","zh":"您拥有星星吗？","t":[103,1721]}]},{"id":"ch13p24","audio":"ch13p24.mp3","sents":[{"ar":"- أجل.","zh":"是的。","t":[103,748]}]},{"id":"ch13p25","audio":"ch13p25.mp3","sents":[{"ar":"- لكن سبق لي أن شاهدت ملكًا... - لا يمتلك","zh":"但我已见过一个国王，他——","t":[103,3787]}]},{"id":"ch13p26","audio":"ch13p26.mp3","sents":[{"ar":"الملوك شيئًا، إنهم يحكمون، وهذا مختلف تمامًا. - وما الفائدة","zh":"国王并非“拥有”，而是“统治”。","t":[103,7039]},{"ar":"من أن تمتلك النجوم؟","zh":"这大不相同。","t":[7039,8644]}]},{"id":"ch13p27","audio":"ch13p27.mp3","sents":[{"ar":"- إن ذلك يجعلني ثريًّا. - وما الفائدة","zh":"拥有星星对你有何益处？","t":[103,4368]}]},{"id":"ch13p28","audio":"ch13p28.mp3","sents":[{"ar":"من كون المرء ثريًّا؟ -","zh":"这使我变得富有。","t":[103,3460]}]},{"id":"ch13p29","audio":"ch13p29.mp3","sents":[{"ar":"إن ذلك يجعله قادرًا على شراء المزيد","zh":"这财富对你有何益处？","t":[103,3379]}]},{"id":"ch13p30","audio":"ch13p30.mp3","sents":[{"ar":"من النجوم، لو عثر أحد على أي منها. قال الأمير الصغير في نفسه:","zh":"若有人发现新的星星，我便可以买下更多。","t":[103,6631]}]},{"id":"ch13p31","audio":"ch13p31.mp3","sents":[{"ar":"« إن هذا الرجل يحلل الأمور مثل السكير تقريبا ». ومع ذلك طرح المزيد من الأسئلة.","zh":"这位小王子心想：“这个人啊，他的推理方法有点像我那可怜的酒鬼。”","t":[103,7685]}]},{"id":"ch13p32","audio":"ch13p32.mp3","sents":[{"ar":"- كيف يمكن للمرء أن يمتلك","zh":"然而，他仍有许多疑问。","t":[103,2484]}]},{"id":"ch13p33","audio":"ch13p33.mp3","sents":[{"ar":"النجوم؟ فسأل رجل الأعمال","zh":"一个人怎能拥有星星呢？","t":[103,3763]}]},{"id":"ch13p34","audio":"ch13p34.mp3","sents":[{"ar":"بعناد: - لمن هي؟ - لست أدري، إنها لا تخص","zh":"商人愤愤地反问：“它们属于谁？”","t":[103,5447]}]},{"id":"ch13p35","audio":"ch13p35.mp3","sents":[{"ar":"أحدًا. - في","zh":"我不知道。","t":[103,2026]},{"ar":"هذه الحال إنها لي،","zh":"对任何人都不属于。","t":[2026,3684]}]},{"id":"ch13p36","audio":"ch13p36.mp3","sents":[{"ar":"لأنني أول شخص يفكر في أمرها. - وهل هذا سبب كاف؟ - طبعًا هو كذلك.","zh":"那它们就属于我了，因为我是第一个想到这个主意的人。","t":[103,8118]}]},{"id":"ch13p37","audio":"ch13p37.mp3","sents":[{"ar":"عندما تعثر على","zh":"这还不够吗？","t":[103,1629]}]},{"id":"ch13p38","audio":"ch13p38.mp3","sents":[{"ar":"ماسة","zh":"当然。","t":[103,721]},{"ar":"لا تخص أحدًا، فهي لك. عندما تكتشف جزيرة لا","zh":"当你发现一颗无主之钻，它便属于你了。","t":[721,6013]},{"ar":"تخص أحدًا، فهي لك. عندما تكون أول من يأتي","zh":"当你发现一座无人的岛屿，它便属于你。","t":[6013,11171]},{"ar":"بفكرة، تنال بها براءة اختراع؛ إنها ملكك. وأنا أمتلك النجوم لأن ما من","zh":"当你第一个想到一个主意，你就申请专利：那主意就是你的了。","t":[11171,18513]},{"ar":"أحد سواي فكر في امتلاكها. قال الأمير الصغير: - إن ذلك منطقي. وماذا تفعل بها؟","zh":"如此，于我而言：我拥有星星，因为在我之前，无人曾想过拥有它们。","t":[18513,27723]}]},{"id":"ch13p39","audio":"ch13p39.mp3","sents":[{"ar":"قال رجل الأعمال: - أدبِّرها وأحصيها،","zh":"是的，这倒是真的，小王子说。","t":[103,3603]},{"ar":"فأنا رجل يهتم بأمور","zh":"您拿它们怎么办呢？","t":[3603,5892]}]},{"id":"ch13p40","audio":"ch13p40.mp3","sents":[{"ar":"ذات جدوى! ظل","zh":"我管理着它们。","t":[103,2382]},{"ar":"الأمير الصغير غير","zh":"我数了又数。","t":[2382,3789]},{"ar":"مقتنع. - إذا","zh":"这很困难。","t":[3789,5697]},{"ar":"كان لدي شال حريري فإنني أستطيع أن","zh":"然而，我天生对重要之事感兴趣。","t":[5697,8750]}]},{"id":"ch13p41","audio":"ch13p41.mp3","sents":[{"ar":"أضعه حول عنقي وآخذه معي.","zh":"小王子依旧不满足。","t":[103,2958]}]},{"id":"ch13p42","audio":"ch13p42.mp3","sents":[{"ar":"إذا كان لدي زهرة، فإنني أستطيع أن أقطفها وآخذها","zh":"如果我拥有一条丝巾，我就能围在脖子上带走。","t":[103,4747]},{"ar":"معي. لكن ليس بإمكانك أن تلتقط النجوم. - لا، لكني","zh":"若我拥有这朵花，便可摘下它，随身带走。","t":[4747,11368]},{"ar":"أستطيع أن أضعها في المصرف.","zh":"你不能从天空中摘下星星...","t":[11368,13605]}]},{"id":"ch13p43","audio":"ch13p43.mp3","sents":[{"ar":"- وماذا","zh":"不。","t":[103,642]},{"ar":"يعني ذلك؟ - يعني أنني أكتب عدد","zh":"但我可以把它们存进银行。","t":[642,4447]}]},{"id":"ch13p44","audio":"ch13p44.mp3","sents":[{"ar":"نجومي على قطعة من الورق،","zh":"这究竟是什么意思呢？","t":[103,2418]}]},{"id":"ch13p45","audio":"ch13p45.mp3","sents":[{"ar":"ثم أضعها في جارور وأقفل عليها بالمفتاح. - وهل هذا","zh":"这意味着我在一张小纸条上写下我的星星数目。","t":[103,5382]},{"ar":"كل شيء؟ - هذا كاف. وفكر الأمير الصغير: « إنه أمر","zh":"然后我把这张纸条放进抽屉，并用钥匙锁上。","t":[5382,11947]}]},{"id":"ch13p46","audio":"ch13p46.mp3","sents":[{"ar":"مسلٍّ حقًّا، وشاعري","zh":"这便是全部了吗？","t":[103,2339]}]},{"id":"ch13p47","audio":"ch13p47.mp3","sents":[{"ar":"نوعًا ما، لكنه إجراء لا","zh":"那便足够了，商人说。","t":[103,2734]}]},{"id":"ch13p48","audio":"ch13p48.mp3","sents":[{"ar":"أهمية حقيقية له ». إن أفكار","zh":"这倒有趣，小王子心想。","t":[103,3566]},{"ar":"الأمير الصغير","zh":"这倒颇有诗意。","t":[3566,4579]},{"ar":"حول ما هو مهم مختلفة","zh":"但这并无大碍。","t":[4579,6763]}]},{"id":"ch13p49","audio":"ch13p49.mp3","sents":[{"ar":"جدًّا عن أفكار الكبار. خاطب رجل الأعمال: - أنا نفسي","zh":"小王子在事关重大之事上，所持见解与成人迥异。","t":[103,5553]}]},{"id":"ch13p50","audio":"ch13p50.mp3","sents":[{"ar":"أمتلك زهرة أسقيها كل يوم، كما أمتلك ثلاثة براكين أنظفها كل أسبوع، وأُشمل","zh":"“我自己养着一朵花，”他继续与商人交谈，“每天都要给它浇水。”","t":[103,7405]},{"ar":"البركان الخامد بعنايتي دائمًا، ما من أحد يعلم ذلك. إن هذا أمر مفيد لبراكيني ومفيد","zh":"我拥有三座火山，每周都要清理一番（包括那座死火山；毕竟，世事难料）。","t":[7405,16224]},{"ar":"للزهرة التي أمتلكها. لكنك لست بذي فائدة للنجوم... فتح","zh":"它使我的火山有了意义，也使我的玫瑰有了价值。","t":[16224,23316]},{"ar":"رجل الأعمال فمه، لكنه لم يجد ما","zh":"但对星星来说，你毫无用处……","t":[23316,26448]}]},{"id":"ch13p51","audio":"ch13p51.mp3","sents":[{"ar":"يقوله، فتابع الأمير الصغير طريقه،","zh":"商人张口结舌，无言以对。","t":[103,3366]},{"ar":"وقال في نفسه","zh":"小王子离去了。","t":[3366,4589]}]},{"id":"ch13p52","audio":"ch13p52.mp3","sents":[{"ar":"وهو يتابع رحلته: « إن الكبار هم غريبو الأطوار حقًّا ».","zh":"大人们真是奇怪得不可思议，他边走边自言自语。","t":[103,4905]}]}]},{"id":"ch14","title_ar":"الفصل الرابع عشر","title_en":"Chapter XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":"ch14p00.mp3","sents":[{"ar":"كان الكوكب الخامس شديد الغرابة،","zh":"第五颗星球颇为奇异。","t":[103,2905]},{"ar":"كان الأصغر حجمًا. كان هناك مكان","zh":"那是所有星球中最小的一颗。","t":[2905,6737]},{"ar":"كاف لعمود مصباح ومشعل مصابيح، وقد تساءل الأمير الصغير","zh":"这颗星球仅能容纳一盏路灯和一个点灯人。","t":[6737,11724]},{"ar":"عن فائدة عمود المصباح ومشعل المصابيح في مكان ما في السماء، على كوكب من دون بيوت أو ناس. ومع ذلك قال في نفسه: « لربما كان مُشعل المصابيح","zh":"小王子无法解释清楚，在某个星球上，天空中，为何会有路灯和点灯人的存在，而这个星球既无人居住，也无房屋。","t":[11724,24382]},{"ar":"سخيفًا ، إلا أنه ليس سخيفًا","zh":"然而，他自言自语道：","t":[24382,27250]}]},{"id":"ch14p01","audio":"ch14p01.mp3","sents":[{"ar":"كالملك، أو الرجل المغرور، أو رجل","zh":"这盏灯的人或许有些荒唐。","t":[103,3221]},{"ar":"الأعمال أو السكير، فعلى الأقل إن لعمله معنى؛ عندما يضيء مصباح","zh":"但他并不像国王、自负的人、商人、酒鬼那样荒谬。","t":[3221,9063]},{"ar":"الشارع، فكأنه أتى بنجم إضافي","zh":"至少他的工作尚有意义。","t":[9063,12195]},{"ar":"إلى الحياة، وعندما يطفئ مصباحه، فإنه يدفع الزهرة أو النجمة إلى","zh":"他点亮街灯，仿佛又唤醒了一颗星星，或一朵花儿。","t":[12195,18211]},{"ar":"النوم. إنه لعمل جميل! وبما أنه جميل، فهو حقًّا","zh":"他熄灭灯火，便让花儿或星星进入梦乡。","t":[18211,24763]},{"ar":"مفيد ». عندما وصل إلى الكوكب","zh":"这是一份美好的职业。","t":[24763,28053]},{"ar":"ألقى التحية على مُشعِل المصابيح","zh":"既然美好，便真正有益。","t":[28053,30645]}]},{"id":"ch14p02","audio":"ch14p02.mp3","sents":[{"ar":"باحترام. - صباح الخير يا سيدي. لماذا أطفأت مصباحك؟","zh":"他抵达星球时，向点灯人毕恭毕敬地行礼。","t":[103,6724]}]},{"id":"ch14p03","audio":"ch14p03.mp3","sents":[{"ar":"أجاب مُشعل","zh":"早上好。","t":[103,1063]},{"ar":"المصابيح: - تلك هي الأوامر.","zh":"你为何刚刚熄了灯？","t":[1063,3418]}]},{"id":"ch14p04","audio":"ch14p04.mp3","sents":[{"ar":"صباح الخير.","zh":"这是规定。","t":[103,2224]},{"ar":"- ما هي","zh":"早上好。","t":[2224,3039]}]},{"id":"ch14p05","audio":"ch14p05.mp3","sents":[{"ar":"الأوامر؟ -","zh":"这是命令。","t":[103,2605]}]},{"id":"ch14p06","audio":"ch14p06.mp3","sents":[{"ar":"الأوامر هي أن أطفئ مصباحي.","zh":"这是熄灯的命令。","t":[103,3553]},{"ar":"مساء","zh":"晚安。","t":[3553,4369]}]},{"id":"ch14p07","audio":"ch14p07.mp3","sents":[{"ar":"الخير. وأضاء مصباحه","zh":"他又点亮了灯火。","t":[103,3342]}]},{"id":"ch14p08","audio":"ch14p08.mp3","sents":[{"ar":"ثانية. - لكن لماذا أضأته ثانية؟","zh":"你为何又把灯点亮了？","t":[103,3987]}]},{"id":"ch14p09","audio":"ch14p09.mp3","sents":[{"ar":"أجاب مشعل","zh":"这是命令。","t":[103,1327]}]},{"id":"ch14p10","audio":"ch14p10.mp3","sents":[{"ar":"المصابيح: - تلك هي الأوامر.","zh":"我不明白，小王子说。","t":[103,2602]}]},{"id":"ch14p11","audio":"ch14p11.mp3","sents":[{"ar":"قال الأمير الصغير: - لا أفهم! قال مشعل المصابيح:","zh":"“这没什么好理解的，”点灯人说。","t":[103,5316]},{"ar":"- الأوامر هي","zh":"命令就是命令。","t":[5316,6316]},{"ar":"الأوامر.","zh":"早上好。","t":[6316,7092]}]},{"id":"ch14p12","audio":"ch14p12.mp3","sents":[{"ar":"صباح الخير. (وأطفأ","zh":"他熄灭了灯火。","t":[103,3079]}]},{"id":"ch14p13","audio":"ch14p13.mp3","sents":[{"ar":"مصباحه ثم مسح جبينه بمنديل مزخرف بمربعات حمراء)","zh":"他用手帕上的红格子方巾擦拭额头。","t":[103,5143]}]},{"id":"ch14p14","audio":"ch14p14.mp3","sents":[{"ar":"إن مهنتي رهيبة. كانت معقولة في","zh":"我从事着一份糟糕的职业。","t":[103,3842]},{"ar":"الأيام الماضية، أطفئ المصباح","zh":"往昔的规定尚合情理。","t":[3842,6263]},{"ar":"في الصباح وأضيئه ثانية في المساء. أسترخي","zh":"晨曦中熄灭灯火，暮色中复燃光亮。","t":[6263,10539]},{"ar":"في بقية النهار وأنام في بقية الليل... - وهل تغيرت","zh":"我拥有了整个白天的闲暇与夜晚的安眠。","t":[10539,14816]}]},{"id":"ch14p15","audio":"ch14p15.mp3","sents":[{"ar":"الأوامر منذ ذلك الوقت؟ قال مشعل","zh":"自那以后，规定已经改了？","t":[103,4105]}]},{"id":"ch14p16","audio":"ch14p16.mp3","sents":[{"ar":"المصابيح: - لم تتغير الأوامر، وتلك","zh":"规定并未更改，点灯人说道。","t":[103,3721]},{"ar":"هي المأساة!","zh":"这是悲剧！","t":[3721,5645]},{"ar":"فمن سنة إلى سنة ازدادت سرعة دوران الكوكب إلى حد بعيد ولم تتغير","zh":"年复一年，星球转得越来越快，而命令却未曾更改。","t":[5645,11816]}]},{"id":"ch14p17","audio":"ch14p17.mp3","sents":[{"ar":"الأوامر. سأل الأمير الصغير:","zh":"小王子问道：“那么呢？”","t":[103,3553]}]},{"id":"ch14p18","audio":"ch14p18.mp3","sents":[{"ar":"- وبالتالي؟ - حسنًا، بما أن السرعة قد وصلت إلى دورة واحدة في الدقيقة، لا أملك","zh":"这颗星球现在每分钟转一圈，我连一秒钟的休息时间都没有。","t":[103,7987]},{"ar":"ثانية واحدة من الراحة. علي أن أشعل مصباحي","zh":"每分钟我都要点亮又熄灭我的灯。","t":[7987,13053]}]},{"id":"ch14p19","audio":"ch14p19.mp3","sents":[{"ar":"وأطفئه مرة كل","zh":"这真有趣！","t":[103,1905]},{"ar":"دقيقة. - إن ذلك مضحك للغاية! إن","zh":"在这里，一天仅有一分钟。","t":[1905,7145]}]},{"id":"ch14p20","audio":"ch14p20.mp3","sents":[{"ar":"النهار يدوم دقيقة واحدة حيث تعيش!","zh":"这根本不有趣！点灯人说道。","t":[103,4474]},{"ar":"قال مشعل المصابيح: - ليس ذلك مضحكًا على الإطلاق،","zh":"我们交谈之际，一个月已悄然流逝。","t":[4474,8658]}]},{"id":"ch14p21","audio":"ch14p21.mp3","sents":[{"ar":"لقد","zh":"一个月？","t":[103,669]}]},{"id":"ch14p22","audio":"ch14p22.mp3","sents":[{"ar":"تحادثنا الآن مدة شهر","zh":"是的，一个月。","t":[103,2011]},{"ar":"كامل. - « إنني","zh":"三十分钟。","t":[2011,3987]},{"ar":"أمارس مهنة","zh":"三十天。","t":[3987,5171]},{"ar":"مريعة ».","zh":"晚安。","t":[5171,5855]}]},{"id":"ch14p23","audio":"ch14p23.mp3","sents":[{"ar":"- شهر؟! - أجل. ثلاثون","zh":"他又点亮了灯火。","t":[103,4079]}]},{"id":"ch14p24","audio":"ch14p24.mp3","sents":[{"ar":"دقيقة. ثلاثون يومًا! مساء الخير. وفيما كان الأمير الصغير يراقبه،","zh":"他看着点灯人，心中涌起对这位忠于职责的灯夫的喜爱。","t":[103,9105]},{"ar":"شعر بأنه بدأ يحب مشعل المصابيح، المطيع للأوامر. تذكر غروب الشمس الذي اعتاد هو نفسه البحث عنه","zh":"他记得，往昔自己只是搬动椅子，就能观赏到日落；他想要帮助他的朋友。","t":[9105,18842]}]},{"id":"ch14p25","audio":"ch14p25.mp3","sents":[{"ar":"بمجرد تحريك كرسيه، فأراد أن يساعد صديقه. - أتعلم... أعتقد أن هنالك طريقة تسمح لك بالراحة حينما","zh":"“你知道，”他道，“我可以告诉你一个方法，你想要休息的时候就能休息……”","t":[103,11355]}]},{"id":"ch14p26","audio":"ch14p26.mp3","sents":[{"ar":"تشاء. قال مُشعل المصابيح: - أنا أريد ذلك","zh":"“我总是想休息，”点灯人说道。","t":[103,4881]}]},{"id":"ch14p27","audio":"ch14p27.mp3","sents":[{"ar":"دائمًا، فالمرء يمكن أن يكون","zh":"人可以同时忠诚又懒惰。","t":[103,2787]},{"ar":"مخلصًا وكسولًا. تابع الأمير","zh":"小王子继续解释道：","t":[2787,6263]}]},{"id":"ch14p28","audio":"ch14p28.mp3","sents":[{"ar":"الصغير: - إن كوكبك صغير جدًّا، بحيث يمكنك أن تتجول فوقه","zh":"你的星球如此之小，只需迈三步就能绕它一周。","t":[103,5853]},{"ar":"بثلاث خطوات، عليك فقط أن تسير ببطء كاف لتبقى دائمًا","zh":"只需缓缓前行，便能始终沐浴在阳光下。","t":[5853,10945]},{"ar":"في نور الشمس. عندما تريد أن تستريح، تمشي... ويدوم النهار حسبما","zh":"当你想休息时，就前行——日子便会如你所愿地延长。","t":[10945,18474]}]},{"id":"ch14p29","audio":"ch14p29.mp3","sents":[{"ar":"تحب. قال مُشعل المصابيح: - لن يساعدني","zh":"这对我帮助不大，点灯人说道。","t":[103,4461]},{"ar":"ذلك كثيرًا، فالشيء الوحيد","zh":"生命中所爱唯有沉睡。","t":[4461,7144]}]},{"id":"ch14p30","audio":"ch14p30.mp3","sents":[{"ar":"الذي أحب في الحياة هو","zh":"那你真是不幸啊。","t":[103,2063]}]},{"id":"ch14p31","audio":"ch14p31.mp3","sents":[{"ar":"النوم. قال الأمير","zh":"我真是倒霉。","t":[103,2487]},{"ar":"الصغير: - هذا من سوء الحظ.","zh":"早上好。他熄灭了灯火。","t":[2487,4895]}]},{"id":"ch14p32","audio":"ch14p32.mp3","sents":[{"ar":"قال مشعل المصابيح: - هذا من سوء الحظ حقًّا، صباح الخير. (ثم أطفأ مصباحه). قال الأمير الصغير في نفسه وهو يتابع رحلته: « هذا","zh":"那个人，”小王子在继续前行时自言自语，“那个人会被所有人嘲笑：国王、自负的人、酒鬼、商人。","t":[103,12947]},{"ar":"الرجل سيستخف به الآخرون: الملك والرجل المغرور والسكير ورجل الأعمال. لكنه","zh":"然而，他是他们所有人中唯一一个在我看来并不荒谬的人。","t":[12947,21000]},{"ar":"الوحيد الذي لا يبدو لي سخيفًا، ربما لأنه ليس مهتمًّ ا","zh":"或许是因为他在想别的事情，而非只顾自己。","t":[21000,26118]}]},{"id":"ch14p33","audio":"ch14p33.mp3","sents":[{"ar":"بنفسه ». وبشعور مفعم بالأسف قال في","zh":"他叹了口气，又自言自语道：","t":[103,4540]}]},{"id":"ch14p34","audio":"ch14p34.mp3","sents":[{"ar":"نفسه ثانية: « إن هذا الرجل هو الوحيد الذي كان بوسعي اتخاذه","zh":"那他是他们所有人中唯一一个我可以成为朋友的人。","t":[103,5313]},{"ar":"صديقًا لي، لكن كوكبه صغير جدًّا حقًّا،","zh":"然而，他的星球实在太小了。","t":[5313,9484]},{"ar":"فما من مكان كاف لشخصين ». وما لم","zh":"这颗星球容不下两个人...","t":[9484,13618]}]},{"id":"ch14p35","audio":"ch14p35.mp3","sents":[{"ar":"يعترف الأمير الصغير به لنفسه هو أنه حزين لمغادرة هذا الكوكب الذي يسبغ عليه ألف وأربعمئة وأربعون غروبًا كل يوم.","zh":"他不敢承认的是，他最遗憾的是即将离开这个星球，因为它每天都能目睹1440次日落。","t":[103,10773]}]}]},{"id":"ch15","title_ar":"الفصل الخامس عشر","title_en":"Chapter XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":"ch15p00.mp3","sents":[{"ar":"كان الكوكب السادس أكبر حجمًا بعشرة","zh":"第六颗行星比上一颗大十倍。","t":[103,3103]},{"ar":"أضعاف. وكان يسكنه سيد عجوز يكتب كتبًا","zh":"这位老先生撰写着厚重的书籍。","t":[3103,8500]}]},{"id":"ch15p01","audio":"ch15p01.mp3","sents":[{"ar":"ضخمة. صاح","zh":"哦，看哪！","t":[103,2224]},{"ar":"عندما رأى الأمير الصغير: - أوه، انظر!","zh":"哦，看哪！来了一位探险家！","t":[2224,5684]}]},{"id":"ch15p02","audio":"ch15p02.mp3","sents":[{"ar":"ها قد أتى مستكشف! جلس الأمير الصغير","zh":"小王子坐在桌子上，喘着气。","t":[103,4013]},{"ar":"إلى الطاولة وهو يلتقط أنفاسه.","zh":"他已跋涉千里，路途遥远！","t":[4013,6658]}]},{"id":"ch15p03","audio":"ch15p03.mp3","sents":[{"ar":"بدا أنه قد سافر","zh":"您从何方来？","t":[103,1735]}]},{"id":"ch15p04","audio":"ch15p04.mp3","sents":[{"ar":"مسافة طويلة جدًّا! سأله السيد العجوز: -","zh":"那本厚重的书是何物？小王子问道。","t":[103,4908]},{"ar":"من أين أتيت؟ قال","zh":"您在做什么？","t":[4908,7736]}]},{"id":"ch15p05","audio":"ch15p05.mp3","sents":[{"ar":"الأمير الصغير متجاهلًا السؤال: - ما هذا","zh":"“我是地理学家，”老先生对他说。","t":[103,3735]}]},{"id":"ch15p06","audio":"ch15p06.mp3","sents":[{"ar":"الكتاب السميك؟ ماذا تفعل هنا؟ قال السيد العجوز:","zh":"小王子问：“地理学家是做什么的？”","t":[103,6329]}]},{"id":"ch15p07","audio":"ch15p07.mp3","sents":[{"ar":"- أنا جغرافي. - وما هو الجغرافي؟ - الجغرافي عالم يعرف مواقع البحار","zh":"地理学家是知晓大海、江河、城镇、山脉和沙漠位置的学者。","t":[103,7881]}]},{"id":"ch15p08","audio":"ch15p08.mp3","sents":[{"ar":"والأنهار والمدن والجبال والصحاري.","zh":"这倒很有趣，小王子说。","t":[103,3961]},{"ar":"قال الأمير الصغير: - هذا أمر مثير للغاية، ها هنا أخيرًا مهنة حقيقية! ثم ألقى نظرة سريعة","zh":"终于，他遇见了一位真正有职业的人！他环顾四周，打量着地理学家的星球。","t":[3961,13237]},{"ar":"حوله إلى كوكب العالم بالجغرافيا، إذ لم يسبق له أن شاهد","zh":"这颗星球是他所见过的最为雄伟庄严的星球。","t":[13237,18315]}]},{"id":"ch15p09","audio":"ch15p09.mp3","sents":[{"ar":"مثل هذا الكوكب","zh":"您的星球真美。","t":[103,1274]},{"ar":"الرائع. - إن كوكبك جميل","zh":"这颗星球有海洋吗？","t":[1274,4382]}]},{"id":"ch15p10","audio":"ch15p10.mp3","sents":[{"ar":"جدًّا. هل توجد أي محيطات؟ قال الجغرافي:","zh":"“这我无法告知，”地理学家说。","t":[103,5618]}]},{"id":"ch15p11","audio":"ch15p11.mp3","sents":[{"ar":"- لا سبيل لي لأعرف ذلك.","zh":"啊！小王子有些失望。","t":[103,3132]},{"ar":"أصاب الأمير الصغير بالخيبة:","zh":"这颗星球有山脉吗？","t":[3132,5382]}]},{"id":"ch15p12","audio":"ch15p12.mp3","sents":[{"ar":"- أوه! وأي جبال؟ قال الجغرافي: - لا","zh":"“这我无法告知，”地理学家说。","t":[103,5355]}]},{"id":"ch15p13","audio":"ch15p13.mp3","sents":[{"ar":"أستطيع في الواقع أن أخبرك","zh":"城镇、河流、沙漠？","t":[103,2300]}]},{"id":"ch15p14","audio":"ch15p14.mp3","sents":[{"ar":"عن ذلك أيضًا. - ومدن","zh":"这我也无法回答。","t":[103,3158]}]},{"id":"ch15p15","audio":"ch15p15.mp3","sents":[{"ar":"وأنهار وصحاري؟ قال","zh":"但您是地理学家！","t":[103,3210]}]},{"id":"ch15p16","audio":"ch15p16.mp3","sents":[{"ar":"الجغرافي: - لا سبيل لي لأعرف ذلك أيضًا.","zh":"“正是如此，”地理学家答道。","t":[103,4763]},{"ar":"- لكنك عالم بالجغرافيا!","zh":"但我不是探险家。","t":[4763,7855]},{"ar":"قال الجغرافي: - تمامًا، لكنني","zh":"我的星球上没有一位探险家。","t":[7855,10882]},{"ar":"لست مستكشفًا، وليس لدي مستكشفون على كوكبي. ليست مهمة الجغرافي إحصاء المدن","zh":"地理学家并非外出计数城镇、河流、山脉、海洋、大洋和沙漠。","t":[10882,18829]},{"ar":"والأنهار والجبال والمحيطات والصحاري.","zh":"地理学家太过重要，不容闲逛。","t":[18829,22895]},{"ar":"فالجغرافي أكثر أهمية بكثير من","zh":"他从未离开过他的办公桌。","t":[22895,25895]},{"ar":"تضييع وقته بالتسكع، إنه لا","zh":"他在书房接待探险家。","t":[25895,28605]},{"ar":"يغادر مكتبه، لكنه يستقبل المستكشفين، وهو يطرح","zh":"他询问他们，记录下他们旅途中的回忆。","t":[28605,33566]},{"ar":"الأسئلة عليهم ويسجل ما يتذكرونه عن أسفارهم، وإذا ما بدت ذكريات أحدهم مثيرة له، فإن الجغرافي يأمر بإجراء استجواب","zh":"若其中某位探险家的回忆引起了他的兴趣，地理学家便会下令调查那位探险者的道德品质。","t":[33566,44579]}]},{"id":"ch15p17","audio":"ch15p17.mp3","sents":[{"ar":"عن سلوك المستكشف","zh":"那是什么原因呢？","t":[103,1721]}]},{"id":"ch15p18","audio":"ch15p18.mp3","sents":[{"ar":"الأخلاقي. - لكن لماذا؟ - لأن المستكشف الذي ينطق بالكذب يشوه سمعة","zh":"因为一个说谎的探险家会给地理学家的书籍带来灾难。","t":[103,7803]},{"ar":"كتب الجغرافي، مثلما يفعل المستكشف","zh":"一个酗酒的探险家也不行。","t":[7803,11210]}]},{"id":"ch15p19","audio":"ch15p19.mp3","sents":[{"ar":"الذي شرب كثيرًا. سأل الأمير الصغير:","zh":"“这又是为什么？”小王子问道。","t":[103,4263]}]},{"id":"ch15p20","audio":"ch15p20.mp3","sents":[{"ar":"- لكن لماذا؟ - لأن السكارى","zh":"酗酒者所见皆为双重。","t":[103,3066]},{"ar":"يرون الأشياء مضاعفة، وبالنتيجة يسجل الجغرافي وجود جبلين،","zh":"于是地理学家会在只有一座山的地方记下两座山。","t":[3066,8605]}]},{"id":"ch15p21","audio":"ch15p21.mp3","sents":[{"ar":"بينما في الواقع يوجد جبل واحد. قال الأمير الصغير:","zh":"我认识一个人，他会成为糟糕的探险家。","t":[103,5289]}]},{"id":"ch15p22","audio":"ch15p22.mp3","sents":[{"ar":"- أعرف شخصًا","zh":"这是可能的。","t":[103,1076]},{"ar":"يمكن أن يكون مستكشفًا. - هذا ممكن. وحتى عندما يبدو سلوك المستكشف الخلقي","zh":"于是，当探险者的道德品质得到证实，便下令调查他的发现。","t":[1076,9408]}]},{"id":"ch15p23","audio":"ch15p23.mp3","sents":[{"ar":"مقبولًا، فالأوامر","zh":"您去看过它吗？","t":[103,2077]}]},{"id":"ch15p24","audio":"ch15p24.mp3","sents":[{"ar":"تصدر","zh":"不。","t":[103,629]},{"ar":"للتحقيق في اكتشافه.","zh":"这太过复杂了。","t":[629,3263]},{"ar":"- أيذهب أحد للتأكد من ذلك؟","zh":"但需探险家提供证据。","t":[3263,5132]},{"ar":"- لا. ذلك سيكون معقدًا جدًّا، لكن يُطلب من المستكشف أن يتوج اكتشافه بدليل، فإذا،","zh":"例如，如果探险的成果是发现了一座大山，便需从那里带回大石头。","t":[5132,15434]}]},{"id":"ch15p25","audio":"ch15p25.mp3","sents":[{"ar":"على سبيل المثال، كان الاكتشاف","zh":"地理学家突然激动起来。","t":[103,2958]}]},{"id":"ch15p26","audio":"ch15p26.mp3","sents":[{"ar":"جبلًا، فإنه يطالَب بأن","zh":"但你——你从远方来！","t":[103,2524]},{"ar":"يأتي بحجارة كبيرة منه.","zh":"你是一位探险家！","t":[2524,5816]},{"ar":"(وفجأة بدا الجغرافي شديد","zh":"请向我描述你的星球。","t":[5816,8289]}]},{"id":"ch15p27","audio":"ch15p27.mp3","sents":[{"ar":"الإثارة) أما أنت، فقد أتيت من مكان بعيد؟ أنت مستكشف؟ ينبغي","zh":"地理学家翻开他那厚重的登记册，削尖了他的铅笔。","t":[103,8118]},{"ar":"أن تصف كوكبك لي! فتح الجغرافي سجله","zh":"探险家的口述先以铅笔记录。","t":[8118,12434]},{"ar":"وبرى القلم الرصاص. إن المرء يبدأ بتسجيل قصة","zh":"待探险家提供证据后，方以墨水记录之。","t":[12434,17316]}]},{"id":"ch15p28","audio":"ch15p28.mp3","sents":[{"ar":"المستكشف بقلم رصاص، وعندما يقدم المستكشف","zh":"“嗯？”地理学家期待地问道。","t":[103,4444]}]},{"id":"ch15p29","audio":"ch15p29.mp3","sents":[{"ar":"الدليل المطلوب، تملأ المعلومات بالحبر. سأل","zh":"哦，我那地方可没意思了，小王子说。","t":[103,4750]},{"ar":"الجغرافي بترقب: - حسنًا؟","zh":"这一切都如此渺小。","t":[4750,8250]},{"ar":"قال الأمير الصغير:","zh":"我有三座火山。","t":[8250,9868]},{"ar":"- أوه، إن موطني ليس مثيرًا لأنه صغير","zh":"两座火山活跃，另一座已熄灭。","t":[9868,13434]},{"ar":"جدًّا. لدي ثلاثة براكين،","zh":"然而，无人能预知。","t":[13434,16815]}]},{"id":"ch15p30","audio":"ch15p30.mp3","sents":[{"ar":"اثنان ناشطان والثالث خامد. لكن","zh":"无人能预知，地理学家说。","t":[103,4408]}]},{"id":"ch15p31","audio":"ch15p31.mp3","sents":[{"ar":"ما من أحد يعلم.","zh":"我还有一朵花。","t":[103,1655]}]},{"id":"ch15p32","audio":"ch15p32.mp3","sents":[{"ar":"قال الجغرافي: - ما من أحد يعلم. - لدي","zh":"我们不记录花朵，地理学家说。","t":[103,4697]}]},{"id":"ch15p33","audio":"ch15p33.mp3","sents":[{"ar":"زهرة أيضًا. قال الجغرافي:","zh":"那又是为何呢？","t":[103,3711]},{"ar":"- لا نسجل الأزهار. - ولم لا؟!","zh":"这朵花是我星球上最美的东西。","t":[3711,7145]}]},{"id":"ch15p34","audio":"ch15p34.mp3","sents":[{"ar":"إنها أجمل شيء على كوكبي! - لأن الأزهار سريعة الزوال. - وماذا تعني كلمة سريعة","zh":"“我们不记录它们，”地理学家说，“因为它们是转瞬即逝的。”","t":[103,8894]}]},{"id":"ch15p35","audio":"ch15p35.mp3","sents":[{"ar":"الزوال؟ قال الجغرافي: - إن الأبحاث","zh":"那“转瞬即逝”又是什么意思？","t":[103,4315]}]},{"id":"ch15p36","audio":"ch15p36.mp3","sents":[{"ar":"الجغرافية هي أثمن الكتب على الإطلاق، فهي لا تصبح قديمة الطراز. من النادر أن","zh":"地理学，地理学家说，“是所有书籍中最关注重大事务的书籍。","t":[103,7776]},{"ar":"يغيِّر جبل مكانه، ومن","zh":"它们永远不会过时。","t":[7776,10053]},{"ar":"النادر جدًّا أن يفرغ المحيط","zh":"山移位，极为罕见。","t":[10053,12197]},{"ar":"نفسه من المياه. إننا نكتب أشياء","zh":"海洋干涸之事，极为罕见。","t":[12197,15789]},{"ar":"أبدية. قاطع الأمير","zh":"我们记载永恒之物。","t":[15789,18631]}]},{"id":"ch15p37","audio":"ch15p37.mp3","sents":[{"ar":"الصغير قائلًا: - لكن البراكين الخامدة يمكن أن تثور، فما","zh":"但死火山也可能复苏，小王子打断了他的话。","t":[103,5155]},{"ar":"الذي تعنيه كلمة سريعة الزوال؟ قال","zh":"那“转瞬即逝”又是什么意思？","t":[5155,9447]}]},{"id":"ch15p38","audio":"ch15p38.mp3","sents":[{"ar":"الجغرافي: - إذا كانت البراكين خامدة أو نشطة، فالأمر سيان","zh":"火山是否熄灭或活跃，对我们来说并无区别。","t":[103,5576]},{"ar":"بالنسبة لنا. إن ما يهمنا هو الجبل؛","zh":"山，对我们来说，才是重要的。","t":[5576,9724]},{"ar":"إنه لا يتغير.","zh":"它不会改变。","t":[9724,11289]}]},{"id":"ch15p39","audio":"ch15p39.mp3","sents":[{"ar":"قال الأمير الصغير مرة أخرى: - لكن ماذا تعني كلمة سريع الزوال؟ (فهو لم يتخل في حياته عن سؤال طرحه ذات مرة).","zh":"“‘转瞬即逝’是什么意思？”小王子继续追问，他一生中一旦提问，就绝不会轻易放手。","t":[103,10710]}]},{"id":"ch15p40","audio":"ch15p40.mp3","sents":[{"ar":"- إنها تعني عرضة لخطر الزوال المبكر. -","zh":"意味着“面临迅速消失的危险”。","t":[103,4947]}]},{"id":"ch15p41","audio":"ch15p41.mp3","sents":[{"ar":"هل زهرتي عرضة لخطر الزوال المبكر؟ - إنها","zh":"我的花儿面临迅速消失的危险吗？","t":[103,5000]}]},{"id":"ch15p42","audio":"ch15p42.mp3","sents":[{"ar":"كذلك، طبعًا.","zh":"当然如此。","t":[103,1695]}]},{"id":"ch15p43","audio":"ch15p43.mp3","sents":[{"ar":"قال الأمير الصغير في نفسه: - إن زهرتي هي سريعة الزوال، ولديها أربع أشواك فقط لتحمي نفسها من العالم!","zh":"我的花儿是转瞬即逝的，小王子自言自语道，而她只有四根刺来保护自己抵御这个世界。","t":[103,10026]},{"ar":"وقد تركتها وحيدة على كوكبي! كانت تلك اللحظة","zh":"我让她孤零零地留在了我的星球上。","t":[10026,14908]}]},{"id":"ch15p44","audio":"ch15p44.mp3","sents":[{"ar":"الأولى التي شعر فيها بالندم،","zh":"那是他第一次感到悔恨。","t":[103,2695]},{"ar":"لكنه تشجع ثانية. سأل:","zh":"他再次鼓起勇气。","t":[2695,6184]}]},{"id":"ch15p45","audio":"ch15p45.mp3","sents":[{"ar":"- أي مكان تنصحني بزيارته الآن؟","zh":"您现在建议我去哪个地方呢？","t":[103,2931]}]},{"id":"ch15p46","audio":"ch15p46.mp3","sents":[{"ar":"أجاب الجغرافي: - كوكب الأرض،","zh":"地球，地理学家答道。","t":[103,2708]},{"ar":"إنه ذو سمعة حسنة.","zh":"它享有盛名。","t":[2708,4577]}]},{"id":"ch15p47","audio":"ch15p47.mp3","sents":[{"ar":"ورحل الأمير الصغير وهو يفكر في زهرته.","zh":"小王子离去，心中想着他的花儿。","t":[103,3563]}]}]},{"id":"ch16","title_ar":"الفصل السادس عشر","title_en":"Chapter XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":"ch16p00.mp3","sents":[{"ar":"وهكذا كان الكوكب السابع هو الأرض. ليست","zh":"于是，第七颗行星便是地球。","t":[103,4329]}]},{"id":"ch16p01","audio":"ch16p01.mp3","sents":[{"ar":"الأرض مجرد كوكب عادي!","zh":"地球非同小可！","t":[103,3368]},{"ar":"فهنالك مئة وأحد عشر ملكًا (من دون ذكر ملوك الزنوج، طبعًا)، وسبعة آلاف جغرافي، وتسعمئة ألف رجل أعمال، وسبعة ملايين ونصف مليون سكير، وثلاثمئة وأحد عشر مليون مغرور - وبكلمات أخرى، ألفا مليون راشد تقريبًا. ولإعطاء فكرة عن حجم","zh":"可数的是，这里有111位国王（当然，别忘了，其中也有黑人国王），7000位地理学家，900万商人，7500万酒鬼，3.11亿自命不凡的人——也就是说，大约有2亿个大人。","t":[3368,27987]}]},{"id":"ch16p02","audio":"ch16p02.mp3","sents":[{"ar":"الأرض، سأوضح أنه قبل اختراع الكهرباء، وعبر القارات الستة، كان ينبغي الاحتفاظ بجيش حقيقي من اثنين وأربعمئة ألف وخمسمئة وأحد عشر شخصًا يحافظون على مصابيح الشوارع. وعند النظر","zh":"为了让你对地球的大小有个具体概念，我得告诉你，在电发明之前，整个六大洲需要维持一支由四十六万二千五百一十一个点灯人组成的真正大军。","t":[103,17093]}]},{"id":"ch16p03","audio":"ch16p03.mp3","sents":[{"ar":"من مسافة قصيرة، كانت النتيجة رائعة. ولقد ضبطت","zh":"从远处望去，那将是一场壮观的景象。","t":[103,5645]},{"ar":"حركات هذا الجيش بصورة مماثلة لحركات فرقة من فرق الباليه،","zh":"这支部队的动作将如同歌剧芭蕾舞般井然有序。","t":[5645,10882]},{"ar":"فأولًا جاء دور مشعلي مصابيح نيوزيلندا وأستراليا،","zh":"新西兰和澳大利亚的提灯人将率先登场。","t":[10882,15263]},{"ar":"فأشعلوا مصابيحهم، وذهبوا للنوم.","zh":"点亮了灯，他们便去安睡了。","t":[15263,19355]},{"ar":"ثم انضم مشعلو مصابيح الصين وسيبيريا إلى الرقصة، وتلاشوا عن الأنظار في الأجنحة. وأتى دور","zh":"接着，中国和西伯利亚的提灯人加入舞步，随后他们也渐渐退入幕后。","t":[19355,27737]},{"ar":"مشعلي مصابيح روسيا والهند وإفريقيا وأوروبا وأمريكا الجنوبية وأمريكا الشمالية، فلم يخطئوا قط في ترتيب دخولهم إلى المسرح. إن هذا","zh":"接着，轮到俄罗斯和印度群岛的提灯人，然后是非洲和欧洲的，接着是南美洲的，最后是北美洲的。","t":[27737,39421]},{"ar":"غير قابل للتصديق. فقط الرجل المسؤول","zh":"他们的进场顺序从未出错。","t":[39421,43553]},{"ar":"عن المصباح","zh":"壮观至极。","t":[43553,44566]}]},{"id":"ch16p04","audio":"ch16p04.mp3","sents":[{"ar":"الوحيد في القطب الشمالي وزميله المسؤول عن المصباح الوحيد في القطب الجنوبي كان بوسعهما التمتع بحياة سعيدة ملأها الكسل، فقد عملا مرتين في السنة.","zh":"北极那盏灯的守护者，以及南极那盏灯的同事——唯有他们二人得以远离劳碌与烦恼：他们只需每年忙碌两次。","t":[103,12642]}]}]},{"id":"ch17","title_ar":"الفصل السابع عشر","title_en":"Chapter XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":"ch17p00.mp3","sents":[{"ar":"عندما يريد المرء أن يكون مضحكًا، يمكنه الكذب قليلًا من","zh":"当人想卖弄聪明时，有时会稍稍偏离真相。","t":[103,4813]},{"ar":"وقت إلى آخر. وأنا لم أكن صادقًا تمامًا عندما تحدثت","zh":"我讲述点灯人的事时，并未全然坦诚。","t":[4813,10237]},{"ar":"إليكم عن مُشعلي المصابيح، وقد جازفت بإعطاء فكرة خاطئة عن كوكبنا لأولئك الذين لا يعرفونه،","zh":"我意识到，我可能给那些不了解我们星球的人留下了错误的印象。","t":[10237,18329]},{"ar":"فالإنسان يشغل مساحة صغيرة جدًّا على كوكب","zh":"人在地球上占据的只是极小的一隅。","t":[18329,22132]},{"ar":"الأرض. وإذا وقف البليونا ساكن في هذا الكوكب واحتشدوا، كما في اجتماع، فباستطاعتهم بسهولة العيش في ساحة عامة طولها عشرون ميلًا وعرضها عشرون ميلًا. والجنس البشري بكامله يمكن","zh":"若这二十亿居民都站立起来，且稍微挤一挤，就像他们参加大型集会那样，便能轻松地安置在二十英里长、二十英里宽的广场上。","t":[22132,39053]},{"ar":"أن يتراكم على جزيرة صغيرة في المحيط الباسيفيكي.","zh":"人类可以堆在太平洋上的一座小岛上。","t":[39053,43026]}]},{"id":"ch17p01","audio":"ch17p01.mp3","sents":[{"ar":"لن يصدقني الكبار طبعًا، فهم يعتقدون بأنهم يحتلون فراغًا كبيرًا،","zh":"大人们，当然，当你告诉他们这些时，他们不会相信的。","t":[103,6392]},{"ar":"ويعدون أنفسهم مهمين كأشجار الباوباب.","zh":"他们自以为占据了极大的空间。","t":[6392,10763]},{"ar":"عليك أن تدعوهم ليقوموا بحساباتهم،","zh":"他们自以为与猴面包树一样重要。","t":[10763,14145]},{"ar":"فهم يعشقون الأرقام ويشعرون بالبهجة.","zh":"你们不妨建议他们自己算一算。","t":[14145,18408]},{"ar":"لكن لا تضيع وقتك بمثل هذا العمل،","zh":"他们偏爱数字，这会让他们高兴的。","t":[18408,21487]},{"ar":"فهو غير ضروري، وأنا أعرف أنك تثق","zh":"但别在这额外任务上浪费时间。","t":[21487,25026]},{"ar":"بي، وهكذا عندما","zh":"这并无必要。","t":[25026,26763]},{"ar":"وصل الأمير الصغير إلى كوكب الأرض،","zh":"你对我，我深知，满怀信心。","t":[26763,29408]}]},{"id":"ch17p02","audio":"ch17p02.mp3","sents":[{"ar":"أصيب بدهشة عارمة من عدم رؤية أحد من الناس.","zh":"小王子抵达地球时，惊讶地发现不见一人。","t":[103,5224]},{"ar":"بدأ يخشى من أن يكون قد أخطأ الطريق إلى الكوكب، عندما تحركت لفة ذهبية شاحبة كالقمر في الرمل. قال الأمير الصغير بتهذيب:","zh":"他开始害怕自己来到了错误的星球，就在这时，一道金色螺旋，月光般的光辉，在沙地上闪现。","t":[5224,16618]}]},{"id":"ch17p03","audio":"ch17p03.mp3","sents":[{"ar":"- مساء الخير. قال الثعبان: - مساء","zh":"“晚上好，”小王子有礼地说。","t":[103,4368]}]},{"id":"ch17p04","audio":"ch17p04.mp3","sents":[{"ar":"الخير. سأل الأمير الصغير:","zh":"“晚上好，”蛇说。","t":[103,3461]}]},{"id":"ch17p05","audio":"ch17p05.mp3","sents":[{"ar":"- على أي كوكب هبطت؟ أجاب الثعبان: - على كوكب الأرض،","zh":"这颗星球，我降落在了哪里？小王子问道。","t":[103,5500]}]},{"id":"ch17p06","audio":"ch17p06.mp3","sents":[{"ar":"في إفريقيا. - أوه... إذًا ما من بشر على","zh":"这是地球；这是非洲，蛇回答说。","t":[103,4895]}]},{"id":"ch17p07","audio":"ch17p07.mp3","sents":[{"ar":"الأرض؟","zh":"啊！","t":[103,1645]},{"ar":"قال الثعبان: -","zh":"地球上无人吗？","t":[1645,2776]}]},{"id":"ch17p08","audio":"ch17p08.mp3","sents":[{"ar":"هذه هي الصحراء،","zh":"这是沙漠。","t":[103,1655]},{"ar":"وما من بشر في الصحراء.","zh":"沙漠中无人迹。","t":[1655,4461]},{"ar":"إن الأرض كبيرة.","zh":"地球辽阔，蛇说。","t":[4461,5815]}]},{"id":"ch17p09","audio":"ch17p09.mp3","sents":[{"ar":"جلس الأمير الصغير على حجر ونظر إلى السماء.","zh":"小王子坐在一块石头上，仰望天空。","t":[103,3826]}]},{"id":"ch17p10","audio":"ch17p10.mp3","sents":[{"ar":"قال: - أتساءل عما إذا كانت النجوم مضاءة كي يعثر كل منا على نجمته ثانية. انظر إلى كوكبي، إنه فوقنا مباشرة... لكن كم هو بعيد!","zh":"他自言自语道：“我想知道，是不是星星在天空中被点亮，以便有一天我们都能找到属于自己的那颗。”","t":[103,14671]},{"ar":"قال الثعبان: - إنه","zh":"看我的星球。","t":[14671,16382]},{"ar":"جميل. لماذا جئت إلى هنا؟","zh":"它就在我们头顶上方。","t":[16382,20618]},{"ar":"أجاب الأمير الصغير:","zh":"它多么遥远啊！","t":[20618,22250]}]},{"id":"ch17p11","audio":"ch17p11.mp3","sents":[{"ar":"- لدي بعض","zh":"它真美。","t":[103,892]},{"ar":"المصاعب مع زهرة.","zh":"你为何至此？","t":[892,2484]}]},{"id":"ch17p12","audio":"ch17p12.mp3","sents":[{"ar":"قال الثعبان: - أوه! ثم لبثا صامتين. قال الأمير","zh":"“我那朵花让我挺烦恼的。”小王子说。","t":[103,6342]}]},{"id":"ch17p13","audio":"ch17p13.mp3","sents":[{"ar":"الصغير مستأنفًا","zh":"啊！蛇说。","t":[103,1761]}]},{"id":"ch17p14","audio":"ch17p14.mp3","sents":[{"ar":"الحديث أخيرًا: - أين","zh":"他们俩都沉默了。","t":[103,2142]}]},{"id":"ch17p15","audio":"ch17p15.mp3","sents":[{"ar":"البشر؟ إن المرء يشعر بالوحدة في الصحراء. قال الثعبان:","zh":"小王子终于又开口说话：“人们在哪里？”","t":[103,6605]}]},{"id":"ch17p16","audio":"ch17p16.mp3","sents":[{"ar":"- إنه بالضبط كالشعور","zh":"沙漠中，有点孤单。","t":[103,1944]}]},{"id":"ch17p17","audio":"ch17p17.mp3","sents":[{"ar":"بالوحدة بين الناس. حدق الأمير","zh":"人在人间，亦感孤寂。","t":[103,3921]}]},{"id":"ch17p18","audio":"ch17p18.mp3","sents":[{"ar":"الصغير إليه وقتًا طويلًا.","zh":"小王子凝视着他许久。","t":[103,2431]}]},{"id":"ch17p19","audio":"ch17p19.mp3","sents":[{"ar":"قال أخيرًا: - أنت حيوان غريب، أنت نحيل كالإصبع.","zh":"他终于说道：“你真是个有趣的动物。”","t":[103,5711]},{"ar":"قال الثعبان: - لكنني أقوى","zh":"你细得就像一根手指。","t":[5711,8302]}]},{"id":"ch17p20","audio":"ch17p20.mp3","sents":[{"ar":"من إصبع ملك. ابتسم الأمير الصغير","zh":"但我的力量胜过国王的手指。","t":[103,4092]}]},{"id":"ch17p21","audio":"ch17p21.mp3","sents":[{"ar":"وقال: - لا تبدو قويًّا","zh":"小王子微笑了。","t":[103,2484]}]},{"id":"ch17p22","audio":"ch17p22.mp3","sents":[{"ar":"جدًّا، لا مخالب لديك،","zh":"你并不怎么强大。","t":[103,2511]},{"ar":"بل لا تستطيع المشي.","zh":"你连脚都没有。","t":[2511,5105]},{"ar":"قال الثعبان: - يمكنني أن","zh":"你甚至无法远行...","t":[5105,7539]}]},{"id":"ch17p23","audio":"ch17p23.mp3","sents":[{"ar":"أحملك إلى أبعد ما يمكن لسفينة.","zh":"我能带你走得更远，蛇说。","t":[103,3089]}]},{"id":"ch17p24","audio":"ch17p24.mp3","sents":[{"ar":"ثم لف نفسه حول كاحل الأمير الصغير كسوار ذهبي، وأضاف","zh":"他如金镯般缠绕在小王子的脚踝上。","t":[103,5155]}]},{"id":"ch17p25","audio":"ch17p25.mp3","sents":[{"ar":"قائلًا: - أيما شخص ألمسه، أعيده إلى الأرض من حيث أتى،","zh":"无论我触及谁，都能将他送回他来的地方。","t":[103,5392]},{"ar":"لكنك طاهر وبريء وقد جئت من نجم. لم يقل الأمير","zh":"但你纯洁无瑕，来自星辰之巅。","t":[5392,11013]}]},{"id":"ch17p26","audio":"ch17p26.mp3","sents":[{"ar":"الصغير شيئًا، فأضاف","zh":"小王子默然不语。","t":[103,2287]}]},{"id":"ch17p27","audio":"ch17p27.mp3","sents":[{"ar":"الثعبان: - أشعر بالأسف تجاهك، فأنت ضعيف جدًّا على هذه الأرض المكونة من الجرانيت،","zh":"在这花岗岩构成的地球上，你如此羸弱，令我心生怜悯。","t":[103,7734]},{"ar":"لربما استطعت مساعدتك في يوم من الأيام، إذا ما شعرت بحنين شديد إلى كوكبك، وأستطيع...","zh":"若你日思夜想，渴望回到自己的星球，我终将助你一臂之力。","t":[7734,16763]},{"ar":"قال","zh":"我能——","t":[16763,17302]}]},{"id":"ch17p28","audio":"ch17p28.mp3","sents":[{"ar":"الأمير","zh":"哦！","t":[103,629]},{"ar":"الصغير: - أوه! أفهمك تمامًا، لكن لماذا","zh":"我深知你的心意，小王子说。","t":[629,5368]},{"ar":"تتحدث بالألغاز طيلة الوقت؟ قال","zh":"但你为何总是说谜语？","t":[5368,9276]}]},{"id":"ch17p29","audio":"ch17p29.mp3","sents":[{"ar":"الثعبان: - أنا أحلها كلها.","zh":"我解开所有的谜。","t":[103,2839]}]},{"id":"ch17p30","audio":"ch17p30.mp3","sents":[{"ar":"ثم لاذ الاثنان بالصمت.","zh":"他们俩都沉默了。","t":[103,1984]}]}]},{"id":"ch18","title_ar":"الفصل الثامن عشر","title_en":"Chapter XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":"ch18p00.mp3","sents":[{"ar":"عبر الأمير الصغير الصحراء والتقى بزهرة وحيدة، زهرة","zh":"小王子穿越沙漠，邂逅了那朵花。","t":[103,4774]},{"ar":"ذات بتلات قليلة، زهرة ليست بذات أهمية.","zh":"一朵三瓣的花，平凡无奇。","t":[4774,8892]}]},{"id":"ch18p01","audio":"ch18p01.mp3","sents":[{"ar":"قال الأمير الصغير: - صباح الخير.","zh":"早上好，小王子说。","t":[103,2892]}]},{"id":"ch18p02","audio":"ch18p02.mp3","sents":[{"ar":"قالت الزهرة: - صباح الخير.","zh":"早上好，花儿说。","t":[103,2445]}]},{"id":"ch18p03","audio":"ch18p03.mp3","sents":[{"ar":"سأل الأمير الصغير بتهذيب: - أين البشر؟ شاهدت","zh":"小王子彬彬有礼地问道：“人在哪里？”","t":[103,5197]}]},{"id":"ch18p04","audio":"ch18p04.mp3","sents":[{"ar":"الزهرة ذات مرة قافلة وهي تمر. - البشر؟","zh":"那朵花儿曾见过一队商队经过。","t":[103,4908]}]},{"id":"ch18p05","audio":"ch18p05.mp3","sents":[{"ar":"أعتقد أن هنالك ستة أو","zh":"人吗？她应声而问。","t":[103,2063]},{"ar":"سبعة منهم تقريبًا. لقد لمحتهم منذ","zh":"世间大概有六七个这样的人。","t":[2063,6211]},{"ar":"بضع سنوات، لكن ما من أحد","zh":"几年前我曾见过他们。","t":[6211,8829]},{"ar":"يعرف أين يعثر عليهم، فالريح تهب","zh":"但无人能知晓他们在何方。","t":[8829,12289]},{"ar":"وتدفعهم إلى الرحيل.","zh":"风将他们吹散了。","t":[12289,14987]},{"ar":"ليس لديهم جذور تجعل حياتهم شاقة نوعًا ما.","zh":"他们无根无基，生活因而颇为艰难。","t":[14987,18947]}]},{"id":"ch18p06","audio":"ch18p06.mp3","sents":[{"ar":"قال الأمير الصغير: - وداعًا.","zh":"再见，小王子说。","t":[103,2577]}]},{"id":"ch18p07","audio":"ch18p07.mp3","sents":[{"ar":"قالت الزهرة: - وداعًا.","zh":"再见，花儿说。","t":[103,2207]}]}]},{"id":"ch19","title_ar":"الفصل التاسع عشر","title_en":"Chapter XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":"ch19p00.mp3","sents":[{"ar":"تسلق الأمير الصغير جبلًا مرتفعًا.","zh":"此后，小王子攀登上一座高山。","t":[103,3974]},{"ar":"إن الجبال التي عرفها هي البراكين الثلاث، التي تصل إلى ركبتيه فقط.","zh":"他仅知的山只有那三座火山，它们的高度仅至他的膝盖。","t":[3974,10961]},{"ar":"وقد استخدم البركان الخامد كمسند للقدمين. قال في نفسه:","zh":"他用那座死火山当脚凳。","t":[10961,16855]},{"ar":"« من قمة جبل مرتفع كهذا، لا بد لي أن أرى بلمحة بصر واحدة الكوكب والناس جميعًا... »، لكن الأشياء التي","zh":"从这座高山之巅，他自语道：“我一眼便能将整个星球尽收眼底，以及所有人……”","t":[16855,26711]}]},{"id":"ch19p01","audio":"ch19p01.mp3","sents":[{"ar":"استطاع رؤيتها كانت قمم صخور حادة كالإبر.","zh":"只见岩石尖峰，如针般锋利。","t":[103,3971]}]},{"id":"ch19p02","audio":"ch19p02.mp3","sents":[{"ar":"قال بتهذيب: - صباح الخير.","zh":"早上好，他礼貌地说。","t":[103,2537]}]},{"id":"ch19p03","audio":"ch19p03.mp3","sents":[{"ar":"أجاب الصدى: - صباح الخير... صباح الخير... صباح الخير...","zh":"早上好——早上好——早上好，回声答道。","t":[103,6539]}]},{"id":"ch19p04","audio":"ch19p04.mp3","sents":[{"ar":"سأل الأمير الصغير: - من أنت؟","zh":"你是谁？小王子问道。","t":[103,2681]}]},{"id":"ch19p05","audio":"ch19p05.mp3","sents":[{"ar":"أجاب الصدى: - من أنت... من أنت... من أنت.","zh":"你是谁——你是谁——你是谁？回声应道。","t":[103,5342]}]},{"id":"ch19p06","audio":"ch19p06.mp3","sents":[{"ar":"قال: - كن صديقي،","zh":"做我的朋友吧。","t":[103,2011]},{"ar":"فأنا وحيد تمامًا.","zh":"我孤零零一人，他说。","t":[2011,3721]}]},{"id":"ch19p07","audio":"ch19p07.mp3","sents":[{"ar":"أجاب الصدى: - أنا وحيد تمامًا... أنا وحيد تمامًا... أنا وحيد تمامًا.","zh":"我孤零零一人——孤零零一人——孤零零一人，回声应道。","t":[103,7855]}]},{"id":"ch19p08","audio":"ch19p08.mp3","sents":[{"ar":"فكر في نفسه: « يا له من كوكب","zh":"多么奇特的星球啊，他想。","t":[103,2734]},{"ar":"غريب! إنه جاف تمامًا ومغطى بالقمم، مالح وغير","zh":"干涸而尖锐，严酷而拒人于千里之外。","t":[2734,8553]},{"ar":"مضياف. الناس يعوزهم","zh":"人们缺乏想象力。","t":[8553,11487]},{"ar":"الخيال وهم يرددون فقط ما يقوله المرء لهم...","zh":"他们重复着别人对他们的每一句话。","t":[11487,16224]},{"ar":"لدي زهرة على كوكبين وكانت تبدأ بالكلام أولًا ».","zh":"在我的星球上，我有一朵花，她总是抢先开口……","t":[16224,20605]}]}]},{"id":"ch20","title_ar":"الفصل العشرون","title_en":"Chapter XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":"ch20p00.mp3","sents":[{"ar":"مع ذلك، وبعد أن مشي الأمير الصغير مدة طويلة عبر الصحراء والصخور والثلج وصل","zh":"走过漫漫长路，穿过沙丘、岩石和雪地，小王子终于找到了一条道路。","t":[103,7142]}]},{"id":"ch20p01","audio":"ch20p01.mp3","sents":[{"ar":"أخيرًا إلى طريق. وكل الطرق تؤدي","zh":"所有道路都通向人类的居所。","t":[103,4065]}]},{"id":"ch20p02","audio":"ch20p02.mp3","sents":[{"ar":"إلى البشر. قال عندما","zh":"早上好，他道。","t":[103,2987]}]},{"id":"ch20p03","audio":"ch20p03.mp3","sents":[{"ar":"وصل إلى حديقة حافلة بالورود: -","zh":"他站在一片盛开的玫瑰花丛前。","t":[103,2998]}]},{"id":"ch20p04","audio":"ch20p04.mp3","sents":[{"ar":"صباح الخير. قالت الورود: -","zh":"玫瑰们道：“早上好。”","t":[103,3355]}]},{"id":"ch20p05","audio":"ch20p05.mp3","sents":[{"ar":"صباح الخير. حدق الأمير","zh":"小王子凝望着她们。","t":[103,3118]},{"ar":"الصغير إليها، إنها تشبه","zh":"她们都像他的那朵花。","t":[3118,5526]}]},{"id":"ch20p06","audio":"ch20p06.mp3","sents":[{"ar":"زهرته. سأل بدهشة: - من أنتن؟ قالت","zh":"他惊愕地问道：“你们是谁？”","t":[103,5671]}]},{"id":"ch20p07","audio":"ch20p07.mp3","sents":[{"ar":"الورود: - نحن ورود. هتف الأمير","zh":"“我们是玫瑰，”玫瑰们说。","t":[103,4237]}]},{"id":"ch20p08","audio":"ch20p08.mp3","sents":[{"ar":"الصغير: - آه. وفجأة","zh":"他不禁悲伤不已。","t":[103,3434]},{"ar":"غمره الحزن؛ لقد بهرته بأنهار الوحيدة من نوعها في الكون،","zh":"他的玫瑰曾告诉他，她是宇宙间独一无二的存在。","t":[3434,8697]},{"ar":"وهنا خمسة آلاف منها، وكلها متشابهة، في حديقة","zh":"在这片花园里，五千朵玫瑰，无一例外。","t":[8697,13961]}]},{"id":"ch20p09","audio":"ch20p09.mp3","sents":[{"ar":"واحدة! فكر في نفسه: « ستشعر بالامتعاض","zh":"她若看到这些，一定会非常生气。","t":[103,4789]},{"ar":"إذا ما رأت ذلك، ستسعل وتسعل وتتظاهر بأنها تموت كي تتجنب","zh":"她将痛苦地咳嗽，装作自己快要死去，以免被人嘲笑。","t":[4789,10553]},{"ar":"التفكير في أنها سخيفة، وسأتظاهر بأنني أعتني بها، وإلا فإنها ستترك نفسها تموت فعلًا، لكي تذلني ».","zh":"我只好装作在悉心照料她，让她恢复生机——否则，为了自谦，她真的会让自己死去……","t":[10553,20486]}]},{"id":"ch20p10","audio":"ch20p10.mp3","sents":[{"ar":"« يا له من كوكب جاف ومدبب ومالح! ». وقال في نفسه مرة ثانية:","zh":"我以为自己富足，却原来只拥有了一朵普普通通的玫瑰。","t":[103,6789]},{"ar":"« اعتقدت بأنني غني، مع زهرة فريدة من نوعها في العالم، فيما أنا في الواقع أملك زهرة عادية، تلك الزهرة، وبراكيني الثلاث التي تصل","zh":"一朵平凡的玫瑰，三座仅及膝高的火山——其中一座或许永远熄灭。","t":[6789,18539]},{"ar":"إلى ركبتي، ومنها بركان خامد على الأرجح إلى الأبد لا يجعلونني أميرً ا","zh":"这并不能使我成为一位伟大的王子……","t":[18539,24934]}]},{"id":"ch20p11","audio":"ch20p11.mp3","sents":[{"ar":"عظيمًا جدًّا ». وبعدما ارتمى على العشب أخذ في البكاء.","zh":"他躺在草地上，失声痛哭。","t":[103,5198]}]}]},{"id":"ch21","title_ar":"الفصل الحادي والعشرون","title_en":"Chapter XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":"ch21p00.mp3","sents":[{"ar":"ثم ظهر الثعلب. قال الثعلب:","zh":"那时，狐狸出现了。","t":[103,3473]}]},{"id":"ch21p01","audio":"ch21p01.mp3","sents":[{"ar":"- صباح الخير. أجاب","zh":"早上好，狐狸说。","t":[103,2973]}]},{"id":"ch21p02","audio":"ch21p02.mp3","sents":[{"ar":"الأمير الصغير بتهذيب: - صباح الخير. مع أنه عندما التفت لم ير شيئًا. قال الصوت:","zh":"早上好，小王子有礼地回应，尽管他转身四顾，却什么也没看见。","t":[103,8790]}]},{"id":"ch21p03","audio":"ch21p03.mp3","sents":[{"ar":"- أنا هنا، تحت شجرة التفاح.","zh":"“我就在苹果树下。”","t":[103,2695]}]},{"id":"ch21p04","audio":"ch21p04.mp3","sents":[{"ar":"قال الأمير الصغير: - من أنت؟ أنت ظريف جدًّا.","zh":"小王子问：“你是谁？你看起来真美。”","t":[103,5040]}]},{"id":"ch21p05","audio":"ch21p05.mp3","sents":[{"ar":"قال الثعلب: - أنا ثعلب. قال","zh":"“我是狐狸，”狐狸说。","t":[103,3697]}]},{"id":"ch21p06","audio":"ch21p06.mp3","sents":[{"ar":"الأمير الصغير مقترحًا: - تعال والعب","zh":"来和我一起玩吧，小王子提议。","t":[103,3274]},{"ar":"معي، فأنا في منتهى","zh":"我如此不快乐。","t":[3274,5248]}]},{"id":"ch21p07","audio":"ch21p07.mp3","sents":[{"ar":"الحزن. قال الثعلب: - لا أستطيع","zh":"我不能与你玩耍，狐狸说。","t":[103,3789]},{"ar":"أن ألعب معك، فأنا","zh":"我尚未被驯服。","t":[3789,5881]}]},{"id":"ch21p08","audio":"ch21p08.mp3","sents":[{"ar":"لست","zh":"啊！","t":[103,497]},{"ar":"أليفًا. قال الأمير الصغير:","zh":"请见谅，小王子说。","t":[497,3645]}]},{"id":"ch21p09","audio":"ch21p09.mp3","sents":[{"ar":"- أوه، أنا آسف. لكن بعد شيء من التفكير سأل: - ماذا تعني كلمة أليف؟","zh":"但经过一番思考，他又问：“那‘驯服’究竟是什么意思？”","t":[103,7316]}]},{"id":"ch21p10","audio":"ch21p10.mp3","sents":[{"ar":"قال الثعلب: - أنت لا","zh":"你并不住在这里。","t":[103,1839]},{"ar":"تعيش هنا، عم تبحث؟","zh":"你在寻找什么？","t":[1839,3932]}]},{"id":"ch21p11","audio":"ch21p11.mp3","sents":[{"ar":"قال الأمير الصغير: - أبحث عن","zh":"我寻找人类，小王子说。","t":[103,2458]},{"ar":"بشر، ماذا تعني كلمة أليف؟ قال الثعلب:","zh":"那“驯服”究竟是什么意思？","t":[2458,7092]}]},{"id":"ch21p12","audio":"ch21p12.mp3","sents":[{"ar":"- يمتلك البشر","zh":"人们，狐狸说。","t":[103,1182]},{"ar":"البنادق ويصطادون، وهذا إزعاج","zh":"他们有枪，他们打猎。","t":[1182,4116]},{"ar":"حقيقي، ويقومون","zh":"令人心绪不宁。","t":[4116,5958]},{"ar":"بتربية الدواجن أيضًا،","zh":"人们也养鸡。","t":[5958,8076]},{"ar":"وتلك هي النشاطات الوحيدة التي","zh":"这些便是他们的唯一兴趣。","t":[8076,10458]},{"ar":"يهتمون بها. هل","zh":"你在找鸡吗？","t":[10458,13079]}]},{"id":"ch21p13","audio":"ch21p13.mp3","sents":[{"ar":"تبحث عن دواجن؟ قال الأمير","zh":"“不，”小王子说。","t":[103,3171]},{"ar":"الصغير: - كلا،","zh":"我在寻找朋友。","t":[3171,4895]},{"ar":"أنا أبحث عن أصدقاء. ماذا تعني كلمة","zh":"那“驯服”究竟是什么意思？","t":[4895,9224]}]},{"id":"ch21p14","audio":"ch21p14.mp3","sents":[{"ar":"أليف؟ قال الثعلب: - إنها شيء لطالما جرى","zh":"这是件常被忽视的行为，狐狸说。","t":[103,4711]},{"ar":"نسيانه، إنها","zh":"建立联系。","t":[4711,6381]}]},{"id":"ch21p15","audio":"ch21p15.mp3","sents":[{"ar":"تعني إقامة","zh":"建立联系？","t":[103,1247]}]},{"id":"ch21p16","audio":"ch21p16.mp3","sents":[{"ar":"روابط الصداقة. - إقامة روابط","zh":"“就如此，”狐狸说。","t":[103,3684]},{"ar":"الصداقة؟ قال الثعلب: - هذا صحيح، بالنسبة لي، أنت مجرد صبي","zh":"对你而言，我不过是一个和无数小男孩无异的男孩。","t":[3684,10645]},{"ar":"صغير مثل مئة ألف من","zh":"我并不需要你。","t":[10645,12526]},{"ar":"الصبية الصغار الآخرين، وأنا لست","zh":"你对我，也无需任何依赖。","t":[12526,15474]},{"ar":"بحاجة إليك، وأنت أيضًا لست بحاجة إلي، بالنسبة إليك، أنا مجرد ثعلب مثل","zh":"对你而言，我不过是一只和其他成千上万的狐狸一样的狐狸。","t":[15474,22882]},{"ar":"مئة ألف من الثعالب الأخرى، لكن إذا جعلتني","zh":"但若你驯服了我，我们便彼此需要。","t":[22882,26684]},{"ar":"أليفًا، فعندئذ يحتاج أحدنا إلى الآخر.","zh":"在你眼中，我是这世上独一无二的。","t":[26684,31342]},{"ar":"بالنسبة لي، ستكون فريدًا، كما سأكون فريدًا","zh":"在你们的世界里，我将独一无二。","t":[31342,35895]}]},{"id":"ch21p17","audio":"ch21p17.mp3","sents":[{"ar":"بالنسبة إليك. قال الأمير الصغير:","zh":"我开始明白了，小王子说。","t":[103,4039]},{"ar":"- بدأت أفهم، هنالك","zh":"那朵花儿……","t":[4039,6000]},{"ar":"زهرة... أظن أنها جعلتني أليفًا.","zh":"我想她已经驯服了我……","t":[6000,9829]}]},{"id":"ch21p18","audio":"ch21p18.mp3","sents":[{"ar":"قال الثعلب: - جائز. إن","zh":"“这可能，”狐狸说。","t":[103,3105]},{"ar":"المرء يرى أشياء شتى على","zh":"地球上可见万物。","t":[3105,5158]}]},{"id":"ch21p19","audio":"ch21p19.mp3","sents":[{"ar":"الأرض. قال الأمير الصغير: - أوه! لكنها ليست على الأرض.","zh":"哦，但这里可不是在地球上！小王子说。","t":[103,6460]}]},{"id":"ch21p20","audio":"ch21p20.mp3","sents":[{"ar":"بدا الثعلب مرتبكًا: - على كوكب","zh":"狐狸显得困惑，十分好奇。","t":[103,3076]}]},{"id":"ch21p21","audio":"ch21p21.mp3","sents":[{"ar":"آخر؟ - أجل. - هل يوجد","zh":"在另一个星球上？","t":[103,4144]}]},{"id":"ch21p22","audio":"ch21p22.mp3","sents":[{"ar":"صيادون","zh":"是的。","t":[102,1063]}]},{"id":"ch21p23","audio":"ch21p23.mp3","sents":[{"ar":"على ذلك الكوكب؟ - كلا. - هذا","zh":"这颗星球上有猎人吗？","t":[103,4421]}]},{"id":"ch21p24","audio":"ch21p24.mp3","sents":[{"ar":"مثير! قال","zh":"没有。","t":[103,2276]}]},{"id":"ch21p25","audio":"ch21p25.mp3","sents":[{"ar":"الثعلب متنهدًا: - ما","zh":"哦，这很有意思！","t":[103,2195]},{"ar":"من مكان كامل،","zh":"这里有鸡吗？","t":[2195,3564]}]},{"id":"ch21p26","audio":"ch21p26.mp3","sents":[{"ar":"(وسرعان","zh":"不。","t":[103,1077]}]},{"id":"ch21p27","audio":"ch21p27.mp3","sents":[{"ar":"ما عاد إلى روايته) إن حياتي رتيبة. أنا","zh":"世间无完美，狐狸叹了口气。","t":[103,5013]}]},{"id":"ch21p28","audio":"ch21p28.mp3","sents":[{"ar":"أصطاد الدواجن، والبشر يصطادونني.","zh":"但他又回到了自己的想法。","t":[103,3168]}]},{"id":"ch21p29","audio":"ch21p29.mp3","sents":[{"ar":"الدواجن كافة متشابهة والبشر جميعًا","zh":"我的生活极为单调，狐狸说。","t":[103,3511]},{"ar":"متشابهون، لذلك أنا أشعر بشيء","zh":"我捕猎鸡，人捕猎我。","t":[3511,6708]},{"ar":"من الضجر، لكن إذا جعلتني أليفًا، فإن حياتي تصبح مليئة","zh":"所有的鸡都长得一样，所有的人也都一样。","t":[6708,12168]},{"ar":"بنور الشمس. ولسوف أميز وقع","zh":"因此，我有些无聊。","t":[12168,15684]},{"ar":"قدم مختلف عن وقع الأقدام الأخرى. إن وقع الأقدام الأخرى","zh":"但若你驯服了我，就如同阳光照耀我的生命。","t":[15684,20934]},{"ar":"سيدفعني للإسراع إلى تحت الأرض، أما وقع","zh":"我将能辨识出与众不同的脚步声。","t":[20934,24408]},{"ar":"قدميك فسيناديني من جحري في الأرض صوت الموسيقى،","zh":"其他脚步声让我匆忙钻回地下。","t":[24408,28421]},{"ar":"انظر وراءك! هل ترى حقول الذرة؟ أنا لست بحاجة إلى تناول","zh":"你的脚步声，如同音乐，将把我从洞穴中唤醒。","t":[28421,35145]},{"ar":"الخبز، والقمح ليس بذي فائدة لي، حقول الذرة","zh":"然后瞧：你看到那边的麦田了吗？","t":[35145,39447]},{"ar":"تلك لا تذكرني","zh":"我不吃面包。","t":[39447,40763]},{"ar":"بأي شيء، وأنا أرى ذلك محزنًا","zh":"麦子对我毫无用处。","t":[40763,43737]},{"ar":"نوعًا ما! أنت تملك شعرًا","zh":"麦田对我默默无言。","t":[43737,46789]},{"ar":"بلون الذهب، لذلك","zh":"这实在可悲！","t":[46789,48605]},{"ar":"سيكون الأمر رائعًا حين","zh":"你的头发是金色的。","t":[48605,50513]},{"ar":"تجعلني أليفًا! فالقمح، ذو اللون الذهبي","zh":"想见你驯服我后的美好景象吧！","t":[50513,55066]},{"ar":"أيضًا، سيذكرني بك، وسأحب صوت الريح","zh":"麦子的金色会让我想起你。","t":[55066,59211]},{"ar":"وهي تهب بين سنابل القمح... لبث الثعلب","zh":"我愿倾听麦田中风的低语……","t":[59211,63684]}]},{"id":"ch21p30","audio":"ch21p30.mp3","sents":[{"ar":"صامتًا وهو يحدق وقتًا طويلًا إلى","zh":"狐狸久久地凝视着小王子。","t":[103,3194]}]},{"id":"ch21p31","audio":"ch21p31.mp3","sents":[{"ar":"الأمير الصغير. قال له:","zh":"请——驯服我吧！","t":[103,3000]}]},{"id":"ch21p32","audio":"ch21p32.mp3","sents":[{"ar":"- اجعلني أليفًا،","zh":"我非常愿意。","t":[103,1576]},{"ar":"أتوسل إليك! أجاب الأمير","zh":"但我没有太多时间。","t":[1576,4711]},{"ar":"الصغير: - بكل طيب خاطر، لكن ليس لدي الكثير","zh":"我有朋友要结识，有许多事要理解。","t":[4711,9368]}]},{"id":"ch21p33","audio":"ch21p33.mp3","sents":[{"ar":"من الوقت، ينبغي أن أكتشف الأصدقاء وأن أفهم","zh":"驯服了的东西，人才懂得它的价值。","t":[103,3905]},{"ar":"الكثير من الأشياء. قال الثعلب: - إن المرء يفهم","zh":"人们不再有时间去理解任何事物。","t":[3905,8697]},{"ar":"الأشياء التي يجعلها أليفة، ليس لدى","zh":"他们在商店里购买现成的东西。","t":[8697,11737]},{"ar":"البشر المزيد من الوقت كي يفهموا أي شيء، إنهم يشترون الأشياء","zh":"然而，世间并无店铺可售友谊，故人皆无友。","t":[11737,16816]},{"ar":"الجاهزة من الدكاكين. لكن بما أنه لا توجد","zh":"若你愿与我结伴，驯服我吧……","t":[16816,21605]}]},{"id":"ch21p34","audio":"ch21p34.mp3","sents":[{"ar":"دكاكين تستطيع أن تشتري منها الأصدقاء،","zh":"我该做些什么，才能驯服你？","t":[103,3340]}]},{"id":"ch21p35","audio":"ch21p35.mp3","sents":[{"ar":"لم يعد للبشر أي أصدقاء. إن أردت","zh":"你必须非常耐心，狐狸回答道。","t":[103,4013]},{"ar":"صديقًا، اجعلني أليفًا. سأل الأمير الصغير: - ماذا ينبغي أن أفعل؟ أجاب الثعلب: - ينبغي","zh":"首先，你将坐在离我一段距离的地方——就像这样——在草地上。","t":[4013,13566]},{"ar":"أن تكون صبورًا جدًّا. أولًا، تجلس على بعد","zh":"我斜眼瞥着你，你不必说一句话。","t":[13566,18395]},{"ar":"مسافة صغيرة مني هكذا، في","zh":"言语是误会的根源。","t":[18395,21079]},{"ar":"العشب، سأراقبك من زاوية عيني وأنت لن","zh":"但你每天都要离我近一点……","t":[21079,25000]}]},{"id":"ch21p36","audio":"ch21p36.mp3","sents":[{"ar":"تقول شيئًا، فالكلمات هي مصدر","zh":"次日，小王子又来了。","t":[103,3089]}]},{"id":"ch21p37","audio":"ch21p37.mp3","sents":[{"ar":"لسوء التفاهم، لكنك تستطيع أن تجلس على","zh":"最好是同一时间回来，狐狸说。","t":[103,3787]},{"ar":"مسافة أقرب لي في يوم. عاد الأمير الصغير في اليوم التالي. قال الثعلب: - كان عليك","zh":"若你下午四点钟来，那么从三点钟开始，我便开始感到幸福了。","t":[3787,12171]},{"ar":"أن تعود في الوقت عينه. إذا أتيت في الساعة الرابعة","zh":"随着时光流逝，我的快乐将愈发浓烈。","t":[12171,16711]},{"ar":"بعد الظهر، مثلًا، سأبدأ في الشعور بالسعادة في","zh":"四点钟，我已开始焦虑不安，坐立难安。","t":[16711,20776]},{"ar":"الساعة الثالثة. ولسوف أشعر بسعادة أكبر","zh":"我将向你展示我是多么快乐！","t":[20776,25303]},{"ar":"فأكبر كلما مر الوقت. وفي الساعة الرابعة سأصاب بالتوتر وأبدأ بالقلق، ولسوف أكتشف ثمن","zh":"但如果你随时来访，我就永远不知道何时我的心该准备好迎接你……","t":[25303,34000]},{"ar":"السعادة. لكن إذا أتيت في أي وقت،","zh":"必须遵守适当的仪式……","t":[34000,37974]}]},{"id":"ch21p38","audio":"ch21p38.mp3","sents":[{"ar":"فأنا لن أعرف متى أهيئ قلبي لإلقاء","zh":"小王子问：“什么是仪式？”","t":[103,3405]}]},{"id":"ch21p39","audio":"ch21p39.mp3","sents":[{"ar":"التحية عليك، إذ على المرء التقيد بطقوس محددة.","zh":"那些也是常被忽视的行为，狐狸说。","t":[103,5645]},{"ar":"سأل الأمير الصغير: - ما هو الطقس؟ قال الثعلب: - إنه لشيء طالما","zh":"它们使一日不同于他日，一小时不同于其他小时。","t":[5645,12039]},{"ar":"تم نسيانه، إنه ما يجعل هذا اليوم مختلفًا","zh":"例如，我的猎人中有一种仪式。","t":[12039,15908]},{"ar":"عن سائر الأيام، وهذه الساعة عن بقية الساعات.","zh":"每周四，他们与村里的姑娘们共舞。","t":[15908,21026]},{"ar":"فمثلًا، هنالك طقس مشترك بين الصيادين","zh":"星期四对我来说是个美好的日子！","t":[21026,24671]},{"ar":"الذين يطاردونني، فهم يذهبون كل","zh":"我可以一直走到葡萄园。","t":[24671,27763]},{"ar":"يوم خميس للرقص مع فتيات القرية. وهكذا فإن يوم الخميس هو يوم رائع بالنسبة لي، فأستطيع السير حتى أبلغ","zh":"但若猎人随时跳舞，那么每一天都将如同其他日子，我便永远没有假期可言。","t":[27763,38211]}]},{"id":"ch21p40","audio":"ch21p40.mp3","sents":[{"ar":"الكروم، لكن إذا ذهب","zh":"小王子驯服了狐狸。","t":[103,2247]},{"ar":"الصيادون للرقص في أي يوم، يصبح","zh":"当离别的时刻临近——","t":[2247,5537]}]},{"id":"ch21p41","audio":"ch21p41.mp3","sents":[{"ar":"كل يوم شبيهًا باليوم الآخر بالنسبة","zh":"啊，狐狸说，我要哭了。","t":[103,3195]}]},{"id":"ch21p42","audio":"ch21p42.mp3","sents":[{"ar":"لي، ولن أحظى بعطلة.","zh":"是你的错，小王子说。","t":[103,3158]},{"ar":"وبالتالي جعل الأمير الصغير الثعلب أليفًا، وعندما حان وقت رحيله، قال","zh":"我从未希望给你带来伤害；但你却想让我驯服你……","t":[3158,9276]}]},{"id":"ch21p43","audio":"ch21p43.mp3","sents":[{"ar":"الثعلب: - أوه... سأبكي. قال الأمير","zh":"是的，是这样的，狐狸说。","t":[103,5026]}]},{"id":"ch21p44","audio":"ch21p44.mp3","sents":[{"ar":"الصغير: - إنه خطؤك ، لم أرغب في أذيتك،","zh":"但你现在要哭了！小王子说。","t":[103,3984]}]},{"id":"ch21p45","audio":"ch21p45.mp3","sents":[{"ar":"لكنك أردت مني أن أجعلك أليفًا.","zh":"是的，是这样的，狐狸说。","t":[103,3077]}]},{"id":"ch21p46","audio":"ch21p46.mp3","sents":[{"ar":"قال الثعلب: - أجل","zh":"对你毫无益处。","t":[103,1827]}]},{"id":"ch21p47","audio":"ch21p47.mp3","sents":[{"ar":"حقًّا. قال الأمير الصغير: - لكنك توشك على البكاء! قال الثعلب: - إن الأمير كذلك. - إذًا لم","zh":"“它让我感到愉悦，”狐狸说，“因为麦田的颜色。”然后他又补充道：","t":[103,10671]}]},{"id":"ch21p48","audio":"ch21p48.mp3","sents":[{"ar":"يساعدك ذلك بأي طريقة! قال","zh":"再去看看那些玫瑰。","t":[103,3645]},{"ar":"الثعلب: - بل ساعدني بسبب لون حقول القمح.","zh":"你的玫瑰，在这世上独一无二。","t":[3645,8421]},{"ar":"(ثم أضاف) اذهب وألقِ نظرة على الورود، ولسوف تفهم أن وردتك هي","zh":"然后回来向我告别，我会送你一个秘密作为礼物。","t":[8421,14856]}]},{"id":"ch21p49","audio":"ch21p49.mp3","sents":[{"ar":"حقًّا فريدة من نوعها في العالم، ثم ستعود","zh":"小王子离去，再次凝视着玫瑰。","t":[103,4037]}]},{"id":"ch21p50","audio":"ch21p50.mp3","sents":[{"ar":"لتقول لي وداعًا، ولسوف أفضي إليك","zh":"你那朵玫瑰与我截然不同。","t":[103,3432]},{"ar":"بسر كهدية. ذهب","zh":"你尚无所有。","t":[3432,6026]},{"ar":"الأمير الصغير لينظر إلى الورود ثانية. وقال:","zh":"无人驯服于你，你亦未驯服他人。","t":[6026,10921]},{"ar":"- ما من واحدة منكن تشبه وردتي، فأنتن","zh":"你就像我最初遇见的那只狐狸。","t":[10921,14605]},{"ar":"تافهات، ما من أحد جعلكن أليفات وأنتن لم تجعلن أحدًا أليفًا.","zh":"他只是一只和其他成千上万的狐狸一样的狐狸。","t":[14605,21474]},{"ar":"أنتن مثل ثعلبي عندما التقيته أول مرة، لقد كان مثل مئة ألف من الثعالب","zh":"但他已成了我的朋友，现在他是这世上独一无二的。","t":[21474,28027]}]},{"id":"ch21p51","audio":"ch21p51.mp3","sents":[{"ar":"الأخرى، إلا أنني جعلته","zh":"玫瑰们感到非常尴尬。","t":[103,2484]}]},{"id":"ch21p52","audio":"ch21p52.mp3","sents":[{"ar":"صديقي، والآن هو فريد من نوعه","zh":"你美丽，却空洞无物。","t":[103,3208]},{"ar":"في العالم. شعرت الورود","zh":"人们不会为你而死。","t":[3208,6013]},{"ar":"بإحراج شديد. تابع يقول: - أنتن جميلات ولكن فارغات، لا يمكن للمرء أن يموت من أجلكن، لكن بالتأكيد إن","zh":"当然，一个普通的过路人会认为我的玫瑰和你的一样——那朵属于我的玫瑰。","t":[6013,16882]},{"ar":"أي عابر سبيل عادي سيعتقد بأن زهرتي تشبهكن تمامًا، لكنها أكثر أهمية منكن جميعًا لأنها الوردة التي رويتها، إنها الوردة التي وضعتها تحت القبة الزجاجية، وهي الوردة التي قمت بحمايتها وراء ستارة، ومن أجلها قتلت اليرقانات، باستثناء اثنتين أو ثلاث ليصبحن فراشات، إنها الوردة التي أصغيت إليها وهي تتذمر، تتباهى أو","zh":"然而，仅凭她自身，她比你们所有数百朵玫瑰都要重要：因为是我为她浇水；是我为她罩上玻璃罩；是我为她挡风遮雨；是我为她杀死了毛毛虫（除了我们留下变成蝴蝶的那两三只）；是我倾听她的抱怨，或她的自夸，有时甚至在她默默无言时。","t":[16882,47013]},{"ar":"تلبث صامتة أحيانًا.","zh":"因为她是我玫瑰。","t":[47013,49027]}]},{"id":"ch21p53","audio":"ch21p53.mp3","sents":[{"ar":"وذلك لأنها وردتي. ثم عاد","zh":"他回到狐狸那里。","t":[103,4000]}]},{"id":"ch21p54","audio":"ch21p54.mp3","sents":[{"ar":"إلى الثعلب وقال","zh":"再见，他说。","t":[103,1603]}]},{"id":"ch21p55","audio":"ch21p55.mp3","sents":[{"ar":"له: - وداعًا. قال","zh":"再见，狐狸说。","t":[103,2816]},{"ar":"الثعلب: - وداعًا. الآن هذا سري، إنه بسيط جدًّا، لا يستطيع المرء أن يرى بوضوح","zh":"用心去看，才能看得真切；本质的东西，肉眼是看不见的。","t":[2816,11263]}]},{"id":"ch21p56","audio":"ch21p56.mp3","sents":[{"ar":"إلا بقلبه، وما هو جوهري لا يمكن رؤيته بالعين. كرر الأمير الصغير كي يذكر:","zh":"本质的东西，肉眼难辨，小王子反复念诵，以便牢记于心。","t":[103,8119]}]},{"id":"ch21p57","audio":"ch21p57.mp3","sents":[{"ar":"- ما هو جوهري لا يمكن رؤيته بالعين؟ - إن الوقت الذي بددته على وردتك","zh":"你为你的玫瑰浪费的时间，使你的玫瑰变得如此重要。","t":[103,7053]}]},{"id":"ch21p58","audio":"ch21p58.mp3","sents":[{"ar":"هو ما يجعل وردتك مهمة جدًّا. قال الأمير الصغير كي يذكر: - إن الوقت الذي بددته على","zh":"“我为我的玫瑰浪费的时间——”小王子说，以便确保自己能记住。","t":[103,8263]}]},{"id":"ch21p59","audio":"ch21p59.mp3","sents":[{"ar":"وردتي... قال الثعلب: - لقد نسي البشر هذه","zh":"人们已遗忘这一真理，狐狸说。","t":[103,4605]},{"ar":"الحقيقة الأساسية،","zh":"但你切莫忘记。","t":[4605,6382]},{"ar":"لكن لا ينبغي أن تنساها. إن ما تجعله أليفًا تصبح","zh":"你一旦驯服了什么，便永远对其负责。","t":[6382,11500]},{"ar":"مسؤولًا عنه إلى الأبد، فأنت","zh":"你须对你的玫瑰负责……","t":[11500,14211]}]},{"id":"ch21p60","audio":"ch21p60.mp3","sents":[{"ar":"مسؤول عن وردتك... ردد الأمير الصغير كي يتذكر: - أنا مسؤول عن وردتي...","zh":"我为我的玫瑰负责，小王子反复说道，以便牢记于心。","t":[103,7145]}]}]},{"id":"ch22","title_ar":"الفصل الثاني والعشرون","title_en":"Chapter XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":"ch22p00.mp3","sents":[{"ar":"قال الأمير الصغير: - صباح الخير. قال","zh":"早上好，小王子说。","t":[103,4355]}]},{"id":"ch22p01","audio":"ch22p01.mp3","sents":[{"ar":"عامل الإشارة في سكة الحديد: - صباح الخير.","zh":"早上好，扳道工说。","t":[103,3827]}]},{"id":"ch22p02","audio":"ch22p02.mp3","sents":[{"ar":"سأل الأمير الصغير: - ماذا تفعل هنا؟ قال عامل الإشارة في سكة","zh":"小王子问道：“你在此做什么？”","t":[103,6290]}]},{"id":"ch22p03","audio":"ch22p03.mp3","sents":[{"ar":"الحديد: - أوزع المسافرين في مجموعات من ألف، أحـول القطر التي تقلهم، تارة إلى اليمين وتارة إلى اليسار.","zh":"“我负责把旅客分成一千人一组的批次，”扳道工说。","t":[103,10605]},{"ar":"هز قطار سريع، متوهج الضوء، مندفع وهادر كالرعد، صندوق","zh":"我调度着载着他们的火车，时而向右，时而向左。","t":[10605,16934]}]},{"id":"ch22p04","audio":"ch22p04.mp3","sents":[{"ar":"الإشارة. قال الأمير الصغير: - إنهم في غاية السرعة. ما الذي يبحثون عنه؟ قال","zh":"一列灯火通明的快车如雷霆般轰鸣而过，震得扳道工的小屋摇摇欲坠。","t":[103,9460]}]},{"id":"ch22p05","audio":"ch22p05.mp3","sents":[{"ar":"عامل الإشارة: - إن سائق القاطرة","zh":"他们匆匆忙忙，小王子说。","t":[103,2971]},{"ar":"لا يعرف حتى نفسه.","zh":"他们在寻找什么？","t":[2971,4497]}]},{"id":"ch22p06","audio":"ch22p06.mp3","sents":[{"ar":"وأخذ قطار سريع متوهج الضوء يهدر في الجهة المقابلة. سأل الأمير الصغير:","zh":"连火车头上的司机也弄不清楚，”扳道工说。","t":[103,7487]}]},{"id":"ch22p07","audio":"ch22p07.mp3","sents":[{"ar":"- هل هم الآن في طريق العودة؟ قال عامل الإشارة: - هؤلاء ليسوا","zh":"第二列灯火通明的快车在相反方向呼啸而过。","t":[103,5961]}]},{"id":"ch22p08","audio":"ch22p08.mp3","sents":[{"ar":"أولئك، إنها عملية تبادل. - إنهم غير مقتنعين بوضعهم؟","zh":"他们已经回来了吗？小王子问道。","t":[103,6592]}]},{"id":"ch22p09","audio":"ch22p09.mp3","sents":[{"ar":"قال عامل الإشارة: - لا أحد راضٍ بوضعه.","zh":"这不是同一批人，扳道工说。","t":[103,4434]},{"ar":"وسمعا هدير","zh":"这是对开的火车。","t":[4434,5684]}]},{"id":"ch22p10","audio":"ch22p10.mp3","sents":[{"ar":"قطار سريع ثالث متوهج النور.","zh":"他们对自己的居住地不满意吗？小王子问道。","t":[103,2787]}]},{"id":"ch22p11","audio":"ch22p11.mp3","sents":[{"ar":"سأل الأمير الصغير: - هل هم يتعقبون","zh":"他总觉得自己所在的地方不尽人意，扳道工说。","t":[103,3313]}]},{"id":"ch22p12","audio":"ch22p12.mp3","sents":[{"ar":"المسافرين الأوائل؟ قال عامل","zh":"又有一列灯火通明的快车如雷鸣般轰鸣而过。","t":[103,3750]}]},{"id":"ch22p13","audio":"ch22p13.mp3","sents":[{"ar":"الإشارة: - بل هم لا يتعقبون","zh":"他们是在追赶第一批旅客吗？小王子质问道。","t":[103,2893]}]},{"id":"ch22p14","audio":"ch22p14.mp3","sents":[{"ar":"شيئًا على الإطلاق.","zh":"他们根本无所追寻，扳道工说。","t":[103,2395]},{"ar":"إنهم ينامون هناك، أو يتثاءبون. الأطفال فقط يضغطون","zh":"他们在车厢里昏昏欲睡，或者若非沉睡，便在打哈欠。","t":[2395,8197]},{"ar":"بأنوفهم على زجاج النوافذ. قال الأمير","zh":"只有孩子们才把鼻子贴在窗玻璃上。","t":[8197,12408]}]},{"id":"ch22p15","audio":"ch22p15.mp3","sents":[{"ar":"الصغير: - الأطفال فقط يعرفون ما يبحثون عنه،","zh":"只有孩子知道他们在寻找什么，小王子说。","t":[103,4432]},{"ar":"إنهم يُشغَفون بدمية من قماش، فتصبح مهمة جدًّا بالنسبة إليهم، وهم يبكون إذا ما أخذت منهم... قال عامل","zh":"他们把时间浪费在布娃娃身上，那对它们来说变得极其重要；要是有人把它夺走，他们就会哭鼻子……","t":[4432,15171]}]},{"id":"ch22p16","audio":"ch22p16.mp3","sents":[{"ar":"الإشارة: - إنهم محظوظون.","zh":"他们是幸运的，扳道工说。","t":[103,2524]}]}]},{"id":"ch23","title_ar":"الفصل الثالث والعشرون","title_en":"Chapter XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":"ch23p00.mp3","sents":[{"ar":"قال الأمير الصغير: - صباح الخير.","zh":"早上好，小王子说。","t":[103,2892]}]},{"id":"ch23p01","audio":"ch23p01.mp3","sents":[{"ar":"قال التاجر: - صباح الخير.","zh":"早上好，商人说。","t":[103,3316]},{"ar":"إنه تاجر يبيع أقراصًا متطورة هدفها إرواء عطش","zh":"这是一位售卖解渴药丸的商人。","t":[3316,7803]},{"ar":"الإنسان. إذا ابتلع المرء حبة مرة في الأسبوع، فإن الحاجة إلى الشرب تتلاشى.","zh":"只需每周吞下一颗药丸，便无需再饮任何东西。","t":[7803,15052]}]},{"id":"ch23p02","audio":"ch23p02.mp3","sents":[{"ar":"سأل الأمير الصغير: - لماذا تبيع هذه الأقراص؟ قال التاجر:","zh":"“你为何卖这种药？”小王子问道。","t":[103,5935]}]},{"id":"ch23p03","audio":"ch23p03.mp3","sents":[{"ar":"- لأنها توفر الكثير من الوقت. لقد تحقق الخبراء من","zh":"“因为这样可以节省大量时间，”商人说。","t":[103,5158]},{"ar":"ذلك. إنك توفر ثلاثًا","zh":"专家们已做过计算。","t":[5158,8211]},{"ar":"وخمسين دقيقة في الأسبوع. - وماذا يفعل المرء بالثلاث","zh":"每周，这些药丸能为你节省五十三分钟。","t":[8211,13632]}]},{"id":"ch23p04","audio":"ch23p04.mp3","sents":[{"ar":"والخمسين دقيقة هذه؟ - ما يحلو له.","zh":"我该如何利用这五十三分钟？","t":[103,3960]}]},{"id":"ch23p05","audio":"ch23p05.mp3","sents":[{"ar":"قال الأمير الصغير:","zh":"你喜欢做什么……","t":[103,1563]}]},{"id":"ch23p06","audio":"ch23p06.mp3","sents":[{"ar":"- لو لدي ثلاث وخمسون دقيقة أقضيها حيثما شئت، لمشيت ببطء شديد في اتجاه نبع من المياه العذبة...","zh":"“至于我，”小王子自言自语道，“若我有五十三分钟可以随心所欲地度过，我便悠然地向一泓清泉走去。”","t":[103,8682]}]}]},{"id":"ch24","title_ar":"الفصل الرابع والعشرون","title_en":"Chapter XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":"ch24p00.mp3","sents":[{"ar":"مضت ثمانية أيام منذ أن تعطلت طائرتي في الصحراء واستمعت إلى قصة التاجر بينما كنت أشرب آخر نقطة من مخزون الماء. قلت للأمير الصغير: - آه! إن ذكرياتك مفرحة جدًّا، لكنني لم أنجح بعد في إصلاح طائرتي.","zh":"沙漠中我的飞机失事已第八天，我边听商人的故事边饮尽了我最后一滴水。","t":[103,19566]}]},{"id":"ch24p01","audio":"ch24p01.mp3","sents":[{"ar":"لم يعد لدي ماء للشرب وسأكون سعيدًا أيضًا لو استطعت المشي ببطء شديد في اتجاه نبع من المياه العذبة! - قال لي صديقي الثعلب... - يا عزيزي","zh":"“啊，”我对小王子说，“你的这些回忆真是迷人；不过，我的飞机还没修好，水也喝光了；若能悠闲地走向一汪清泉，我也会很快乐的！”","t":[103,12329]}]},{"id":"ch24p02","audio":"ch24p02.mp3","sents":[{"ar":"الفتى الصغير، إن هذا لا علاقة له","zh":"我的朋友狐狸——小王子对我说。","t":[103,3194]}]},{"id":"ch24p03","audio":"ch24p03.mp3","sents":[{"ar":"بالثعلب! - لماذا؟ - لأننا سنموت من","zh":"亲爱的孩子，这已与狐狸无关了！","t":[103,5171]}]},{"id":"ch24p04","audio":"ch24p04.mp3","sents":[{"ar":"العطش. لم","zh":"为何不可？","t":[103,2421]}]},{"id":"ch24p05","audio":"ch24p05.mp3","sents":[{"ar":"يتبع منطقي، فأجاب:","zh":"因为我即将渴死……","t":[103,2550]}]},{"id":"ch24p06","audio":"ch24p06.mp3","sents":[{"ar":"- إنه لمن المفيد أن تكسب صديقًا،","zh":"他并未理解我的话，却回答道：","t":[103,2879]}]},{"id":"ch24p07","audio":"ch24p07.mp3","sents":[{"ar":"حتى لو كان المرء على وشك الموت، فأنا سعيد جدًّا لأنني","zh":"有了一位朋友，即便是在命悬一线之际，也是一件好事。","t":[103,4800]},{"ar":"كسبت الثعلب صديقًا. - إنه غير مدرك","zh":"我很高兴能有一位狐狸作为朋友……","t":[4800,9237]}]},{"id":"ch24p08","audio":"ch24p08.mp3","sents":[{"ar":"للخطر. قلت في نفسي: «","zh":"他无法想象危险的严重。","t":[103,3368]},{"ar":"فهو لم يشعر قط بالجوع أو العطش،","zh":"他从未尝过饥饿或口渴的滋味。","t":[3368,6447]},{"ar":"كل ما يحتاج إليه هو القليل","zh":"他只需一点阳光便足矣……","t":[6447,8934]}]},{"id":"ch24p09","audio":"ch24p09.mp3","sents":[{"ar":"من نور الشمس... ». نظر إلي","zh":"他凝视着我，对我的想法回应道：","t":[103,3289]}]},{"id":"ch24p10","audio":"ch24p10.mp3","sents":[{"ar":"واستجاب لأفكاري.","zh":"我也渴了……","t":[103,2645]},{"ar":"- أنا عطشان جدًّا،","zh":"让我们去找一口井……","t":[2645,4184]}]},{"id":"ch24p11","audio":"ch24p11.mp3","sents":[{"ar":"لنذهب ونبحث عن بئر.","zh":"我打了个倦怠的手势。","t":[103,2974]},{"ar":"قمت بحركة تنم عن التعب، إذ من السخافة البحث عن بئر بصورة عشوائية","zh":"在沙漠的浩瀚中随意寻找一口井，实在荒谬至极。","t":[2974,9105]},{"ar":"في صحراء شاسعة، ومع ذلك بدأنا","zh":"然而，我们还是出发了。","t":[9105,12329]}]},{"id":"ch24p12","audio":"ch24p12.mp3","sents":[{"ar":"نمشي. مشينا أربع ساعات بصمت، خيم الظلام وبدأت النجوم في الظهور،","zh":"我们默默前行数小时，夜幕降临，星辰渐次闪烁。","t":[103,7342]},{"ar":"وبسبب العطش أصبحت محمومًا قليلًا، فرأيتها كما في حلم، وعادت","zh":"干渴让我微微发烧，我望着它们，仿佛置身梦境。","t":[7342,13434]},{"ar":"كلمات الأمير الصغير الأخيرة تتراقص عائدة إلى ذهني. سألته: -","zh":"小王子的最后几句话如潮水般涌回我的记忆：","t":[13434,19474]}]},{"id":"ch24p13","audio":"ch24p13.mp3","sents":[{"ar":"إذًا أنت عطشان أيضًا؟ لم يجب","zh":"你也渴了吗？我追问。","t":[103,3553]}]},{"id":"ch24p14","audio":"ch24p14.mp3","sents":[{"ar":"عن سؤالي، بل قال ببساطة: - يمكن","zh":"但他并未回答我的问题。","t":[103,3418]},{"ar":"للماء أن يفيد القلب.","zh":"他只是对我说：","t":[3418,5063]}]},{"id":"ch24p15","audio":"ch24p15.mp3","sents":[{"ar":"لم أفهم جوابه، لكنني","zh":"水对心灵亦有益……","t":[103,2511]}]},{"id":"ch24p16","audio":"ch24p16.mp3","sents":[{"ar":"لبثت صامتًا. أدركت جيدًا أن ما من","zh":"我不解其意，却缄口不言。","t":[103,4118]},{"ar":"جدوى لطرح الأسئلة عليه. شعر بالتعب","zh":"我深知无法对他进行质询。","t":[4118,8434]}]},{"id":"ch24p17","audio":"ch24p17.mp3","sents":[{"ar":"فجلس، جلست بجانبه،","zh":"他疲惫不堪。","t":[103,2550]},{"ar":"وبعد فترة قصيرة","zh":"他坐了下来。","t":[2550,4274]},{"ar":"من الصمت تحدث ثانية:","zh":"我坐在他身边。","t":[4274,6432]},{"ar":"- إن النجوم جميلة بسبب زهرة لا يمكن للمرء أن يراها. أجبت:","zh":"星星之所以美丽，是因为有一朵看不见的花。","t":[6432,12579]}]},{"id":"ch24p18","audio":"ch24p18.mp3","sents":[{"ar":"- طبعًا. ونظرت إلى الكثبان الرملية تحت ضوء القمر بصمت. قال مضيفًا: - إن الصحراء جميلة.","zh":"我答道：“没错，正是如此。”然后默默无言，凝视着月光下绵延的沙丘。","t":[103,9434]}]},{"id":"ch24p19","audio":"ch24p19.mp3","sents":[{"ar":"وكان ذلك صحيحًا، لقد أحببت الصحراء","zh":"沙漠真美，小王子补充道。","t":[103,3497]}]},{"id":"ch24p20","audio":"ch24p20.mp3","sents":[{"ar":"دائمًا، يجلس","zh":"这倒是真的。","t":[103,1550]},{"ar":"الإنسان على ربوة رملية، لا","zh":"沙漠，我始终钟爱。","t":[1550,4037]},{"ar":"يرى شيئًا ولا يسمع شيئًا، ومع ذلك يستطيع أن","zh":"坐在沙漠沙丘上，无所见，无所闻。","t":[4037,8182]},{"ar":"يشعر بإشعاع صامت. قال الأمير الصغير:","zh":"寂静中，有何物跳动，闪烁……","t":[8182,12539]}]},{"id":"ch24p21","audio":"ch24p21.mp3","sents":[{"ar":"- إن ما يجعل الصحراء جميلة هو أنها تخفي بئرًا، في مكان ما...","zh":"沙漠之所以美丽，是因为它某个角落隐藏着一口井。","t":[103,5208]}]},{"id":"ch24p22","audio":"ch24p22.mp3","sents":[{"ar":"شعرت بدهشة عندما أدركت فجأة إشعاع الرمل الغامض.","zh":"我猛然领悟到沙漠那神秘闪烁的奥秘。","t":[103,5158]},{"ar":"عندما كنت صبيًّا، سكنت في بيت قديم جدًّا، وقد علمنا من أسطورة أنه يوجد كنز","zh":"我年幼时曾住在一座古老的大屋中，传说那里埋藏着一笔宝藏。","t":[5158,12368]},{"ar":"مدفون هناك، وبالتأكيد لم يكتشفه أحد، ربما لن يبحث عنه أحد، ولكنه يضفي","zh":"确实，无人知晓如何找到它；或许无人曾试图寻找过。","t":[12368,19882]},{"ar":"سحرًا على المنزل. إن منزلي","zh":"但那座房子被施了魔法。","t":[19882,22961]},{"ar":"يخفي سرًّا في أعماقه. قلت للأمير الصغير: -","zh":"我的家在心底深处藏着一个秘密……","t":[22961,27368]}]},{"id":"ch24p23","audio":"ch24p23.mp3","sents":[{"ar":"أجل، سواء أكان منزلًا أو نجومًا أو","zh":"“是的，”我对小王子说。","t":[103,3589]},{"ar":"محراء، فمن غير الممكن رؤية مصدر الجمال فيهم. قال: - يسعدني أنك توافقني الرأي.","zh":"房子、星星、沙漠——赋予它们美丽的是肉眼无法看见的东西。","t":[3589,12224]}]},{"id":"ch24p24","audio":"ch24p24.mp3","sents":[{"ar":"عندما استسلم الأمير الصغير للنوم، أخذته بذراعي وبدأت","zh":"他笑着说：“很高兴，你赞同我的狐狸。”","t":[103,5195]}]},{"id":"ch24p25","audio":"ch24p25.mp3","sents":[{"ar":"أمشي ثانية. لقد تأثرت في العمق، بدا لي أنني أحمل كنزًا","zh":"小王子入睡，我把他抱在怀里，再次踏上了旅程。","t":[103,5961]},{"ar":"هشًّا جدًّا، بدا لي أنه لا يوجد على","zh":"内心深受触动，波澜起伏。","t":[5961,9026]},{"ar":"الأرض شيء أكثر هشاشة منه. وفي ضوء القمر","zh":"我仿佛抱着一件极其脆弱的珍宝。","t":[9026,13697]},{"ar":"حدقت إلى الجبين الشاحب، إلى العينين المغمضتين، إلى","zh":"在这片大地上，似乎再无比他更脆弱之物。","t":[13697,18211]},{"ar":"خصلات الشعر وهي ترتجف في النسيم، ثم قلت في نفسي: « ما أراه هنا ليس سوى محارة أو صدفة، وما هو أكثر أهمية غير واضح... ». وعندما انفتحت شفتاه قليلًا","zh":"在这月光下，我凝视着他苍白的额头、紧闭的双眼、随风轻颤的鬈发，心中自语道：“我所看到的，不过是一具躯壳。”","t":[18211,32592]},{"ar":"في نصف ابتسامة، قلت في نفسي مرة أخرى:","zh":"最重要的，是肉眼看不见的……","t":[32592,36263]}]},{"id":"ch24p26","audio":"ch24p26.mp3","sents":[{"ar":"« إن ما يثيرني في العمق بشأن هذا الأمير الصغير النائم هنا هو إخلاصه لزهرة، انطباعة ذهنية عن وردة تشع عبر كيانه كشعلة مصباح، حتى أثناء نومه... »، وشعرت بأنه أكثر هشاشة. إن المصابيح","zh":"在这半张的嘴唇上，带着一丝怀疑的微笑微微张开，我再次对自己说：“打动我的，正是这位在此沉睡的小王子对一朵花的忠诚——玫瑰的影像在他整个生命中如灯焰般闪耀，即便在他入睡时……”我愈发觉得他显得更加脆弱。","t":[103,18000]},{"ar":"ينبغي حمايتها بعناية أكبر؛ إن هبة ريح يمكن أن تطفئها.","zh":"我感到需要保护他，仿佛他自身就是一丝微风就能吹灭的火焰……","t":[18000,23447]}]},{"id":"ch24p27","audio":"ch24p27.mp3","sents":[{"ar":"وتابعت سيري، وعند الفجر اكتشفت البئر.","zh":"曙光初露，我找到了那口井。","t":[103,3642]}]}]},{"id":"ch25","title_ar":"الفصل الخامس والعشرون","title_en":"Chapter XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":"ch25p00.mp3","sents":[{"ar":"قال الأمير الصغير: - يزدحم البشر في القطر السريعة من دون أن","zh":"人们踏上旅程，乘坐快车，却不知他们在寻找什么。","t":[103,4800]},{"ar":"يعرفوا ما يبحثون عنه، وهكذا يصابون بالقلق ويندفعون في","zh":"他们忙乱地四处奔走，激动不已，团团打转……","t":[4800,10023]}]},{"id":"ch25p01","audio":"ch25p01.mp3","sents":[{"ar":"حلقات. (ثم أضاف بعد توقف) إن الأمر لا يستحق","zh":"他接着说：“这番忙碌实在不值得。”","t":[103,5539]}]},{"id":"ch25p02","audio":"ch25p02.mp3","sents":[{"ar":"المشقة. لم تكن البئر التي وصلنا إليها شبيهة","zh":"我们找到的井与撒哈拉沙漠的井大不相同。","t":[103,5211]},{"ar":"بآبار الصحاري المعتادة. إن آبار الصحاري","zh":"撒哈拉之井，不过是沙中浅洞。","t":[5211,9368]},{"ar":"هي حفر بسيطة محفورة في","zh":"这口井宛如村中的井。","t":[9368,11539]},{"ar":"الرمل، إلا أن تلك بدت كبئر قرية، لكن ما من قرية","zh":"然而此处并无村落，我疑心自己是在梦中。","t":[11539,16382]}]},{"id":"ch25p03","audio":"ch25p03.mp3","sents":[{"ar":"هناك، فظننت أنني أحلم. قلت للأمير","zh":"这真奇怪，我对小王子说。","t":[103,4474]},{"ar":"الصغير: - يا للغرابة! إن كل شيء جاهز؛","zh":"一切用具俱备：辘轳、水桶、绳子……","t":[4474,9026]}]},{"id":"ch25p04","audio":"ch25p04.mp3","sents":[{"ar":"الدلو والحبل... ضحك، ثم لمس الحبل وحرك","zh":"他笑着，轻触绳索，启动了辘轳。","t":[103,4776]},{"ar":"البكرة. بدأت البكرة تئن مثل ديك رياح قديم","zh":"辘轳哀鸣，宛如久被遗忘的老风信鸡。","t":[4776,9855]}]},{"id":"ch25p05","audio":"ch25p05.mp3","sents":[{"ar":"عندما تهدأ الريح فترة","zh":"你听，小王子说。","t":[103,2076]},{"ar":"طويلة. قال الأمير الصغير: - هل يمكنك أن","zh":"我们唤醒了这口井，它正在歌唱……","t":[2076,6487]}]},{"id":"ch25p06","audio":"ch25p06.mp3","sents":[{"ar":"تسمع؟ لقد أيقظنا البئر وهي","zh":"我不愿他因拉绳而劳累。","t":[103,3671]}]},{"id":"ch25p07","audio":"ch25p07.mp3","sents":[{"ar":"الآن تغني... لم","zh":"让我来吧。","t":[103,2461]},{"ar":"أشأ أن يقوم بأي جهد، فقلت له: -","zh":"这份工作对你来说太沉重了。","t":[2461,5474]}]},{"id":"ch25p08","audio":"ch25p08.mp3","sents":[{"ar":"اترك الأمر لي، فهو ثقيل جدًّا عليك. سحبت الدلو ببطء ووضعته بحزم على حافة البئر،","zh":"我缓缓将水桶提到井边，放置其间——尽管疲惫，但为我的成就而喜悦。","t":[103,8947]},{"ar":"استطعت أن أسمع غناء البكرة، التي ما زالت ترتجف، في أذني وفي الماء،","zh":"辘轳之歌仍在耳畔回响，我看见阳光在静止摇曳的水面闪烁。","t":[8947,15289]}]},{"id":"ch25p09","audio":"ch25p09.mp3","sents":[{"ar":"واستطعت أن أرى بريق الشمس. قال الأمير الصغير:","zh":"我渴望的就是这样的水，小王子说。","t":[103,4842]},{"ar":"- أتوق بشدة إلى هذه","zh":"让我喝上几口……","t":[4842,6816]}]},{"id":"ch25p10","audio":"ch25p10.mp3","sents":[{"ar":"المياه. أعطني شيئًا منها","zh":"我明白了他在寻找什么。","t":[103,3394]}]},{"id":"ch25p11","audio":"ch25p11.mp3","sents":[{"ar":"لأشرب. وفهمت ما كان","zh":"我举桶至他唇边。","t":[103,2961]},{"ar":"يبحث عنه! رفعت","zh":"他闭目啜饮。","t":[2961,5447]},{"ar":"الدلو إلى شفتيه، شرب وعيناه","zh":"宛如节日佳肴般甘甜。","t":[5447,8382]},{"ar":"مغمضتان. كانت عذبة كشراب العيد.","zh":"这水确是不同于寻常的滋养。","t":[8382,13539]},{"ar":"إن هذه المياه هي شيء مختلف تمامًا عن الغذاء العادي، إنها وليدة السير تحت النجوم وغناء البكرة وجهد","zh":"星光下的漫步、辘轳的歌声与我的臂力，孕育了这水的甘甜。","t":[13539,21921]},{"ar":"ذراعي، إنها مفيدة للقلب، مثل هدية. عندما","zh":"宛如礼物，温暖了心房。","t":[21921,27513]},{"ar":"كنت صبيًّا صغيرًا، كانت أضواء شجرة الميلاد، وموسيقى قداس منتصف الليل، وطيبة الوجوه الباسمة، تكون توهج هدية الميلاد التي أتلقاها. قال الأمير الصغير:","zh":"儿时，圣诞树上的灯光、子夜弥撒的乐音、微笑脸庞的温柔，构成了我所收到的礼物的光辉。","t":[27513,42013]}]},{"id":"ch25p12","audio":"ch25p12.mp3","sents":[{"ar":"- إن الناس حيث تعيش يزرعون خمسة آلاف وردة في الحديقة يبحثون عنه... نفسها... وهم لا يجدون ما...","zh":"“你们那里的男人，”小王子说，“在同一花园里培育了五千朵玫瑰——却在那里找不到他们所寻找的东西。”","t":[103,9894]}]},{"id":"ch25p13","audio":"ch25p13.mp3","sents":[{"ar":"قلت مجيبًا:","zh":"他们并未找到。","t":[103,1353]}]},{"id":"ch25p14","audio":"ch25p14.mp3","sents":[{"ar":"- لا يعثرون عليه، ومع ذلك يمكن أن يكون ما يبحثون عنه في وردة واحدة أو","zh":"在一朵玫瑰或一滴水中，他们所寻之物便可觅得。","t":[103,6576]}]},{"id":"ch25p15","audio":"ch25p15.mp3","sents":[{"ar":"في قليل من الماء. قلت مجيبًا:","zh":"是的，这确实如此。","t":[103,3868]}]},{"id":"ch25p16","audio":"ch25p16.mp3","sents":[{"ar":"- نعم، حقًّا. وأضاف الأمير","zh":"小王子又补充道：","t":[103,3868]}]},{"id":"ch25p17","audio":"ch25p17.mp3","sents":[{"ar":"الصغير: - إن الأعين","zh":"但眼睛是盲的。","t":[103,2024]},{"ar":"عمياء؛ على المرء أن ينظر من","zh":"必须用心去看……","t":[2024,4629]}]},{"id":"ch25p18","audio":"ch25p18.mp3","sents":[{"ar":"خلال القلب. شربت","zh":"我饮了这水。","t":[103,2618]},{"ar":"الماء، وكنت أتنفس","zh":"呼吸顺畅了。","t":[2618,4724]},{"ar":"بسهولة. إن الرمل عند شروق الشمس هو بلون","zh":"日出时分，沙地泛着蜜色。","t":[4724,9053]},{"ar":"العسل، وكنت أستمتع جدًّا بلون العسل.","zh":"这蜜色也让我心情愉悦。","t":[9053,13500]},{"ar":"لماذا إذن كنت أشعر بمثل هذا الحزن؟! قال","zh":"那又是什么，让我心生哀愁？","t":[13500,17986]}]},{"id":"ch25p19","audio":"ch25p19.mp3","sents":[{"ar":"الأمير الصغير برقة وهو يجلس بجانبي ثانية: - عليك الحفاظ على وعدك. - أي وعد؟","zh":"你务必遵守诺言，小王子轻声说，再次坐到我身边。","t":[103,7842]}]},{"id":"ch25p20","audio":"ch25p20.mp3","sents":[{"ar":"- أنت تعرف...","zh":"什么诺言？","t":[103,1142]}]},{"id":"ch25p21","audio":"ch25p21.mp3","sents":[{"ar":"كمامة من أجل خروفي، فأنا مسؤول عن هذه","zh":"你知道——给我的绵羊画一个口罩……","t":[103,3839]},{"ar":"الزهرة. أخذت رسومي","zh":"我负责这朵花……","t":[3839,6619]}]},{"id":"ch25p22","audio":"ch25p22.mp3","sents":[{"ar":"الأولية من جيبي، نظر الأمير","zh":"我从口袋里掏出草图。","t":[103,2839]},{"ar":"الصغير إليها وضحك وهو يقول:","zh":"小王子打量了一番，笑着说：","t":[2839,5497]}]},{"id":"ch25p23","audio":"ch25p23.mp3","sents":[{"ar":"- إن أشجار الباوباب التي رسمتها تشبه الملفوف قليلًا.","zh":"你的猴面包树——它们有点像卷心菜。","t":[103,4182]}]},{"id":"ch25p24","audio":"ch25p24.mp3","sents":[{"ar":"- أوه.","zh":"哦！","t":[103,419]}]},{"id":"ch25p25","audio":"ch25p25.mp3","sents":[{"ar":"(وقد كنت فخورًا جدًّا بأشجاري","zh":"我对自己画的猴面包树颇为自豪！","t":[103,2681]}]},{"id":"ch25p26","audio":"ch25p26.mp3","sents":[{"ar":"الباوباب)! - ثعلبك، أذناه... تشبهان القرون","zh":"你的狐狸——它的耳朵有点像角，而且太长了。","t":[103,6092]}]},{"id":"ch25p27","audio":"ch25p27.mp3","sents":[{"ar":"قليلًا، وهما","zh":"他又笑了。","t":[103,1774]}]},{"id":"ch25p28","audio":"ch25p28.mp3","sents":[{"ar":"طويلتان (ثم ضحك ثانية).","zh":"你这不公平，小王子，我说。","t":[103,3750]},{"ar":"- لست عادلًا أيها الأمير الصغير، تذكر أن بإمكاني فقط رسم الحيات العاصرة","zh":"我只懂得画外部的蟒蛇和内部的蟒蛇。","t":[3750,10158]}]},{"id":"ch25p29","audio":"ch25p29.mp3","sents":[{"ar":"من الخارج والحيات العاصرة من الداخل. قال لي: - أوه، هذا كاف، فالأطفال يفهمون.","zh":"哦，那没关系，他说，孩子们会理解的。","t":[103,8382]}]},{"id":"ch25p30","audio":"ch25p30.mp3","sents":[{"ar":"وهكذا رسمت كمامة بقلم رصاص، وقد اعتصر قلبي","zh":"于是，我画了一张绵羊口罩的铅笔草图。","t":[103,4905]},{"ar":"حين أعطيته إياها. - لديك خطط أجهلها.","zh":"我的心在交付给他时撕裂了。","t":[4905,9527]}]},{"id":"ch25p31","audio":"ch25p31.mp3","sents":[{"ar":"لكنه لم يجب، وبدلًا","zh":"你有所图，我却不晓。","t":[103,2589]}]},{"id":"ch25p32","audio":"ch25p32.mp3","sents":[{"ar":"من ذلك، قال لي: -","zh":"但他没有回答我。","t":[103,2063]},{"ar":"هل تعلم... إن","zh":"他转而对我说：","t":[2063,4342]}]},{"id":"ch25p33","audio":"ch25p33.mp3","sents":[{"ar":"هبوطي إلى الأرض ستكون ذكراه السنوية","zh":"你知道——我降临到地球……","t":[103,3247]},{"ar":"غدًا. (ثم أضاف بعد صمت قصير)","zh":"明天就是它的周年纪念日。","t":[3247,6961]}]},{"id":"ch25p34","audio":"ch25p34.mp3","sents":[{"ar":"لقد هبطت إلى مكان قريب جدًّا من","zh":"然后，沉默片刻，他又继续说道：","t":[103,3036]}]},{"id":"ch25p35","audio":"ch25p35.mp3","sents":[{"ar":"هنا. ثم تورد وجهه، ومرة","zh":"我降落得离这里很近。","t":[103,4000]}]},{"id":"ch25p36","audio":"ch25p36.mp3","sents":[{"ar":"أخرى، ومن دون أن أفهم","zh":"他的脸泛起了红晕。","t":[103,2379]}]},{"id":"ch25p37","audio":"ch25p37.mp3","sents":[{"ar":"السبب، ساورني شعور غريب بالأسى، ثم خطر سؤال في","zh":"又不知为何，我心中涌起一股莫名的哀愁。","t":[103,5063]},{"ar":"بالي: « إذًا لم يكن مجرد صدفة أن تتجول","zh":"然而，一个问题浮现在我的脑海中：","t":[5063,8958]}]},{"id":"ch25p38","audio":"ch25p38.mp3","sents":[{"ar":"بمفردك على بعد ألف ميل من أي سكن بشري عندما التقيتك في ذلك الصباح منذ ثمانية أيام؟ هل كنت عائد ًا إلى","zh":"那天早上，我们初次相遇——一周前——你独自一人，在这远离人烟的沙漠中漫步，这并非偶然？","t":[103,10500]},{"ar":"المكان حيث هبطت؟ ». تورد وجه","zh":"你正背对着你的降落点走去？","t":[10500,14026]}]},{"id":"ch25p39","audio":"ch25p39.mp3","sents":[{"ar":"الأمير الصغير ثانية، ثم","zh":"小王子再次涨红了脸。","t":[103,2734]}]},{"id":"ch25p40","audio":"ch25p40.mp3","sents":[{"ar":"تابعت قائلًا بشيء من التردد:","zh":"我带着几分犹豫，补充道：","t":[103,2603]}]},{"id":"ch25p41","audio":"ch25p41.mp3","sents":[{"ar":"- ربما بسبب الذكرى السنوية؟","zh":"或许是因为周年纪念吧？","t":[103,2274]}]},{"id":"ch25p42","audio":"ch25p42.mp3","sents":[{"ar":"تورد وجه الأمير الصغير","zh":"小王子脸颊再次泛红。","t":[103,1879]},{"ar":"مرة ثالثة. لم يجب عن أسئلتي قط، لكن عندما تتورد وجنتا المرء، فذلك يعني","zh":"他从不回答问题——但一个人脸红，难道不是就意味着“是”吗？","t":[1879,10250]}]},{"id":"ch25p43","audio":"ch25p43.mp3","sents":[{"ar":"نعم، أليس كذلك؟ قلت له: - يا إلهي! أشعر","zh":"“啊，”我对他说，“我有点害怕——”","t":[103,6552]}]},{"id":"ch25p44","audio":"ch25p44.mp3","sents":[{"ar":"بشيء من الخوف.","zh":"他打断了我。","t":[103,1550]}]},{"id":"ch25p45","audio":"ch25p45.mp3","sents":[{"ar":"أجاب مطمْئنًا: - الآن","zh":"现在你必须工作了。","t":[103,2208]},{"ar":"عليك أن تعمل، عليك أن تعود","zh":"你必须回到你的引擎旁。","t":[2208,4774]},{"ar":"إلى محركك.","zh":"我在这儿等你。","t":[4774,6921]},{"ar":"سأنتظرك هنا، عد مساء الغد.","zh":"明天晚上再来……","t":[6921,9750]}]},{"id":"ch25p46","audio":"ch25p46.mp3","sents":[{"ar":"لكنني لم أشعر بالاطمئنان.","zh":"但我并未感到安心。","t":[103,3329]},{"ar":"تذكرت الثعلب.","zh":"我记起了那只狐狸。","t":[3329,5592]},{"ar":"إن المرء يجازف بالبكاء قليلًا إذا ما سمح لنفسه أن يصبح أليفًا.","zh":"若有人让自己被驯服，难免会流下几滴泪……","t":[5592,11105]}]}]},{"id":"ch26","title_ar":"الفصل السادس والعشرون","title_en":"Chapter XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":"ch26p00.mp3","sents":[{"ar":"بجانب البئر، كانت هنالك بقايا جدار","zh":"井边，一堵古老的石墙残垣断壁。","t":[103,3313]},{"ar":"حجري قديم، عندما عدت من عملي في المساء التالي، رأيت عن","zh":"当晚我下班归来，远远望见小王子坐在断壁之上，双脚悬空。","t":[3313,8511]},{"ar":"بعد أميري الصغير","zh":"我听见他这么说：","t":[8511,10037]}]},{"id":"ch26p01","audio":"ch26p01.mp3","sents":[{"ar":"جالسًا فوقه وساقاه","zh":"那么，你不记得了。","t":[103,2024]},{"ar":"متدليتان. سمعته يقول:","zh":"这不是确切的地方。","t":[2024,5619]}]},{"id":"ch26p02","audio":"ch26p02.mp3","sents":[{"ar":"- ألا تتذكر؟ لم يكن موجودًا هنا! ومن دون شك رد","zh":"另一个声音定然回应了他，因为他对此反驳道：","t":[103,6513]}]},{"id":"ch26p03","audio":"ch26p03.mp3","sents":[{"ar":"عليه صوت آخر","zh":"没错！没错！","t":[103,1563]},{"ar":"لأنه أجاب: - أجل! أجل! إنه","zh":"正是这一天，但不是这个地方。","t":[1563,6421]}]},{"id":"ch26p04","audio":"ch26p04.mp3","sents":[{"ar":"اليوم المناسب لكنها","zh":"我继续朝墙走去。","t":[103,1853]},{"ar":"ليست البقعة المناسبة...","zh":"我从未见过或听到过任何人。","t":[1853,4645]},{"ar":"تابعت السير باتجاه الحائط،","zh":"小王子却再次反驳道：","t":[4645,6868]}]},{"id":"ch26p05","audio":"ch26p05.mp3","sents":[{"ar":"لكنني","zh":"没错。","t":[103,787]},{"ar":"لم أستطع أن أرى أو أن أسمع أحدًا، مع","zh":"你将看到我的足迹在沙地上起始之处。","t":[787,4024]},{"ar":"ذلك أجاب الأمير","zh":"你只需在那里等我。","t":[4024,5234]},{"ar":"الصغير مرة أخرى: - ...","zh":"今夜我会在那儿等你。","t":[5234,6866]}]},{"id":"ch26p06","audio":"ch26p06.mp3","sents":[{"ar":"نعم، طبعًا، ستشاهدين أين تبدأ آثار","zh":"我离墙仅有二十米，却仍一无所见。","t":[103,4247]}]},{"id":"ch26p07","audio":"ch26p07.mp3","sents":[{"ar":"قدمي في الرمال انتظريني هناك.","zh":"沉默片刻后，小王子又开口了。","t":[103,2484]}]},{"id":"ch26p08","audio":"ch26p08.mp3","sents":[{"ar":"سأكون هناك","zh":"你有毒药吗？","t":[103,1142]},{"ar":"الليلة. كنت على بعد مئتي متر فقط من","zh":"你能否肯定不会让我遭受太久痛苦？","t":[1142,5527]}]},{"id":"ch26p09","audio":"ch26p09.mp3","sents":[{"ar":"الحائط ومع ذلك لم أستطع أن أرى شيئًا، وبعد","zh":"我止步不前，心碎如裂；然而我依旧不解。","t":[103,4313]}]},{"id":"ch26p10","audio":"ch26p10.mp3","sents":[{"ar":"صمت قليل تحدث الأمير","zh":"现在你走吧，小王子说。","t":[103,2182]},{"ar":"الصغير ثانية: - هل السم","zh":"我想要从墙上下来。","t":[2182,4418]}]},{"id":"ch26p11","audio":"ch26p11.mp3","sents":[{"ar":"لديك جيد؟ هل أنت متأكدة من أنه","zh":"我低头看向墙脚——然后纵身跃起。","t":[103,4250]},{"ar":"لن يجعلني أعاني وقتًا طويلًا جدًّا؟ وقفت على دربي وقلبي يعتصر،","zh":"黄蛇昂首面对小王子，这种蛇只需三十秒就能夺走人的生命。","t":[4250,10987]},{"ar":"لكنني لم أكن لأفهم. قال:","zh":"我掏枪入袋，同时快步后退。","t":[10987,14632]},{"ar":"- الآن اذهبي... أريد أن أنزل! عندئذ خفضت نظري إلى أدنى الجدار، وما رأيت جعلني أقفز في الهواء! كانت هناك إحدى تلك الحيات الصفراوات، التي تستطيع أن تفتك بك في غضون ثوانٍ، رافعة رأسها باتجاه الأمير الصغير. « والآن انصرف، أريد أن أنزل عن هنا » بدأت بالركض وأنا أبحث في جيبي عن مسدسي، لكن بسبب الجلبة التي","zh":"但在我制造的噪音中，那条蛇像喷泉般垂死的喷泉一样，在沙地上轻松地流淌，不慌不忙地消失在石头之间，发出轻微的金属声响。","t":[14632,45579]}]},{"id":"ch26p12","audio":"ch26p12.mp3","sents":[{"ar":"أحدثتها، انزلقت الحية بسهولة عائدة إلى الرمل مثل نافورة مياه متلاشية، ومن دون أي عجلة ظاهرة، اختفت وسط الحجارة بصوت رنان. وصلت إلى الجدار في الوقت","zh":"我及时赶到，将他小小的身躯紧紧抱在怀中，他的脸庞白得如雪。","t":[103,15382]}]},{"id":"ch26p13","audio":"ch26p13.mp3","sents":[{"ar":"المناسب لألتقط أميري الصغير بذراعي، وقد استحال وجهه أبيض كالثلج. سألته:","zh":"我追问：“这是什么意思？”","t":[103,8026]},{"ar":"- ماذا يعني ذلك؟ لماذا تتحدث إلى الحية؟","zh":"你为何与蛇交谈？","t":[8026,12592]}]},{"id":"ch26p14","audio":"ch26p14.mp3","sents":[{"ar":"فككت اللفاع الذهبي الذي لا يفارق عنقه","zh":"我解开了他始终佩戴的金色围巾。","t":[103,3392]},{"ar":"أبدًا، ثم رطبت جبينه وقدمت له بعض الماء للشرب،","zh":"我湿润了他的太阳穴，并给他喝了一些水。","t":[3392,8366]},{"ar":"ثم لم أجرؤ على طرح المزيد من","zh":"我再也不敢问他更多问题了。","t":[8366,10761]},{"ar":"الأسئلة. نظر بجدية إلي ووضع ذراعيه حول عنقي.","zh":"他严肃地望着我，将双臂环抱住我的脖子。","t":[10761,17250]},{"ar":"استطعت أن أشعر بقلبه يخفق مثل قلب عصفور","zh":"他的心跳如中枪濒死的小鸟般急促。","t":[17250,21210]}]},{"id":"ch26p15","audio":"ch26p15.mp3","sents":[{"ar":"يحتضر بعد إصابته بطلقة نارية من بندقية شخص ما. قال لي: -","zh":"他高兴地说：“你找到了飞机的问题，我很欣慰。”","t":[103,6789]},{"ar":"إنني سعيد جدًّا لأنك اكتشفت","zh":"现在你可以回家了——","t":[6789,9474]}]},{"id":"ch26p16","audio":"ch26p16.mp3","sents":[{"ar":"العطل في محركك،","zh":"你怎会知道那事？","t":[103,1814]}]},{"id":"ch26p17","audio":"ch26p17.mp3","sents":[{"ar":"الآن تستطيع أن تذهب إلى وطنك. - كيف عرفت؟ في الواقع، كنت على وشك أن أخبره","zh":"我正要告诉他，我的工作已经成功，超出了我敢想象的任何程度。","t":[103,8750]}]},{"id":"ch26p18","audio":"ch26p18.mp3","sents":[{"ar":"أن مهمتي نجحت، على العكس من كل التوقعات. لم يجب عن سؤالي، لكنه","zh":"他未对我的问题作答，却补充道：“我也要回家去了……”","t":[103,7605]}]},{"id":"ch26p19","audio":"ch26p19.mp3","sents":[{"ar":"همس قائلًا: - أنا أيضًا سأعود اليوم إلى وطني. ثم","zh":"那时，他黯然神伤地说：“那还要远得多……”","t":[103,5724]},{"ar":"أضاف بشيء من الحزن:","zh":"这还更加艰难……","t":[5724,7514]}]},{"id":"ch26p20","audio":"ch26p20.mp3","sents":[{"ar":"- إنه أبعد بكثير... من الصعب","zh":"我明白，这绝非寻常之事。","t":[103,3434]},{"ar":"أكثر... استطعت أن أشعر بأن شيئًا غير عادي يوشك أن يحدث. كنت أضمه بقوة بذراعي كطفل، ومع ذلك بدا لي أنه","zh":"我紧紧地抱住他，如同抱住一个小孩；然而，我感觉他正一头冲向深渊，而我却无法阻止他……","t":[3434,15197]}]},{"id":"ch26p21","audio":"ch26p21.mp3","sents":[{"ar":"ينزلق إلى هاوية، لكنني لم أستطع فعل أي شيء للحؤول","zh":"他的目光非常严肃，仿佛迷失在遥远之地。","t":[103,5261]}]},{"id":"ch26p22","audio":"ch26p22.mp3","sents":[{"ar":"دون ذلك. كانت","zh":"我有你的绵羊。","t":[103,2434]},{"ar":"نظرته جدية وتائهة.","zh":"我有羊的箱子。","t":[2434,5605]},{"ar":"- لدي خروفك، ولدي الصندوق","zh":"我还有它的口罩……","t":[5605,8421]}]},{"id":"ch26p23","audio":"ch26p23.mp3","sents":[{"ar":"من أجل الخروف، كما","zh":"他凄然一笑。","t":[103,2129]}]},{"id":"ch26p24","audio":"ch26p24.mp3","sents":[{"ar":"لدي الكمامة أيضًا.","zh":"我等待了许久。","t":[103,2816]},{"ar":"ثم ابتسم بحزن. انتظرت","zh":"他渐渐恢复了生机。","t":[2816,6276]}]},{"id":"ch26p25","audio":"ch26p25.mp3","sents":[{"ar":"وقتًا طويلًا، استطعت أن أشعر بأنه بدأ يدفأ شيئًا فشيئًا.","zh":"亲爱的孩子，我说道，“你害怕了……”","t":[103,5458]}]},{"id":"ch26p26","audio":"ch26p26.mp3","sents":[{"ar":"- لقد كنت خائفًا يا رجلي","zh":"他害怕，这毫无疑问。","t":[103,1984]},{"ar":"الصغير العزيز. أصيب","zh":"他轻轻地笑了。","t":[1984,4802]}]},{"id":"ch26p27","audio":"ch26p27.mp3","sents":[{"ar":"بالرعب، طبعًا! لكنه ضحك بلطف.","zh":"今夜我会更加害怕……","t":[103,4408]}]},{"id":"ch26p28","audio":"ch26p28.mp3","sents":[{"ar":"- سأشعر بخوف أكبر هذا المساء. مرة ثانية أصابني","zh":"我又一次被那无法挽回的感觉冻结了。","t":[103,5566]},{"ar":"بالجمود، شعور بأن هناك أمرًا لا يمكن إصلاحه.","zh":"我无法忍受再想永远听不到那笑声。","t":[5566,10829]},{"ar":"أدركت أنني لن أتحمل فكرة","zh":"沙漠中的一股清泉。","t":[10829,13356]}]},{"id":"ch26p29","audio":"ch26p29.mp3","sents":[{"ar":"عدم سماع تلك الضحكة ثانية، كانت","zh":"小家伙，我想再听到你的笑声。","t":[103,3537]}]},{"id":"ch26p30","audio":"ch26p30.mp3","sents":[{"ar":"أشبه بينبوع ماء","zh":"他对我说：","t":[103,1721]}]},{"id":"ch26p31","audio":"ch26p31.mp3","sents":[{"ar":"عذب في صحراء نفسي. - أريد","zh":"今夜，它将是一周年……","t":[103,3316]},{"ar":"أن أسمعك تضحك ثانية يا أميري الصغير. لكنه قال لي: - الليلة، تنقضي","zh":"我的星星，现在就在我一年前降落到地球的那个地方上方……","t":[3316,11079]}]},{"id":"ch26p32","audio":"ch26p32.mp3","sents":[{"ar":"سنة... وستكون نجمتي تمامًا فوق البقعة حيث هبطت منذ... قلت له: - أيها الأمير","zh":"小家伙，告诉我，这关于蛇、约会和星星的事，只是一场噩梦……","t":[103,9066]}]},{"id":"ch26p33","audio":"ch26p33.mp3","sents":[{"ar":"الصغير، قل لي إن قصة الحية","zh":"但他并未回应我的哀求。","t":[103,2892]},{"ar":"واللقاء والنجمة","zh":"他转而对我说：","t":[2892,4379]}]},{"id":"ch26p34","audio":"ch26p34.mp3","sents":[{"ar":"ليست إلا حلمًا مزعجًا. لكنه لم يجب عن سؤالي،","zh":"那重要的东西，是肉眼无法看见的……","t":[103,5224]}]},{"id":"ch26p35","audio":"ch26p35.mp3","sents":[{"ar":"وبدلًا من ذلك قال","zh":"是的，我知道……","t":[103,1853]}]},{"id":"ch26p36","audio":"ch26p36.mp3","sents":[{"ar":"لي: - لا يمكن رؤية ما هو","zh":"它对花儿来说也是如此。","t":[103,2471]},{"ar":"مهم. - أجل، أعرف. - تمامًا كما هي الحال مع الزهرة، إذا أحببت زهرة حدث أنها على نجمة،","zh":"若你爱上了一朵生长在星星上的花，那么在夜晚仰望星空便显得格外甜蜜。","t":[2471,12487]},{"ar":"فسيكون من الممتع أن","zh":"繁星似锦，花开满空","t":[12487,14421]}]},{"id":"ch26p37","audio":"ch26p37.mp3","sents":[{"ar":"تحدق ليلًا إلى السماء.","zh":"是的，我知道……","t":[103,2023]}]},{"id":"ch26p38","audio":"ch26p38.mp3","sents":[{"ar":"إن النجوم","zh":"水亦如此。","t":[103,839]},{"ar":"هي أزهار غزيرة. - أجل، أعرف. - إن الأمر مماثل بالنسبة","zh":"因为那辘轳和绳子，你给我的水，如同音乐。","t":[839,7658]},{"ar":"إلى الماء، فالجرعة التي","zh":"你记得——那时多么美好。","t":[7658,9908]}]},{"id":"ch26p39","audio":"ch26p39.mp3","sents":[{"ar":"أعطيتني كانت كالموسيقى","zh":"是的，我知道……","t":[103,1958]}]},{"id":"ch26p40","audio":"ch26p40.mp3","sents":[{"ar":"تمامًا، بسبب البكرة والحبل...","zh":"在夜晚，你会仰望星空。","t":[103,3684]},{"ar":"أنت تتذكر، أليس كذلك؟ لقد كانت عذبة. - أجل، أعرف. ستحدق إلى","zh":"我住的地方一切都很小，无法向你指出我的星星所在之处。","t":[3684,13132]},{"ar":"النجوم ليلًا.","zh":"如此更佳。","t":[13132,15237]},{"ar":"إن كل شيء صغير جدًّا حيث أعيش لدرجة أنني لا","zh":"我的星星只是万千星辰之一，对你而言。","t":[15237,19145]},{"ar":"أستطيع أن أريك أين تقع نجمتي. إن الأمر هو أفضل على","zh":"因此，你将喜欢观看天空中所有的星星……","t":[19145,24776]},{"ar":"هذا النحو. ستكون نجمتي إحدى","zh":"它们都将成为你的朋友。","t":[24776,28105]},{"ar":"النجمات بالنسبة إليك، وهكذا ستتوق","zh":"此外，我还要送你一份礼物……","t":[28105,31868]}]},{"id":"ch26p41","audio":"ch26p41.mp3","sents":[{"ar":"إلى النظر","zh":"他又笑了。","t":[103,997]}]},{"id":"ch26p42","audio":"ch26p42.mp3","sents":[{"ar":"إليها كلها. ستكون كلها صديقات لك.","zh":"啊，小王子，我亲爱的王子！","t":[103,5539]},{"ar":"لدي هدية لك... ضحك ثانية.","zh":"我喜欢听你的笑声！","t":[5539,9250]}]},{"id":"ch26p43","audio":"ch26p43.mp3","sents":[{"ar":"- آه! أيها الأمير","zh":"这是我的礼物。","t":[103,2302]},{"ar":"الصغير،","zh":"仅此而已。","t":[2302,2502]},{"ar":"يا أميري الصغير العزيز، أحب أن أسمع","zh":"它将如同我们共饮那水时一般。","t":[2316,6565]}]},{"id":"ch26p44","audio":"ch26p44.mp3","sents":[{"ar":"هذه الضحكة! - تمامًا،","zh":"你究竟想表达什么？","t":[103,2908]}]},{"id":"ch26p45","audio":"ch26p45.mp3","sents":[{"ar":"تلك ستكون هديتي، كما كان الأمر مع الماء... - ماذا تقول؟ - إن النجوم تعني","zh":"每个人心中都有星星，但对不同的人来说，它们的意义各不相同。","t":[103,7250]},{"ar":"أمورًا مختلفة لمختلف الناس، فبالنسبة","zh":"对某些旅人来说，星星是向导。","t":[7250,10947]},{"ar":"إلى البعض هي ليست أكثر من أنوار متلألئة في السماء.","zh":"对其他人而言，它们不过是天空中微小的灯火。","t":[10947,15987]},{"ar":"وبالنسبة إلى المسافرين هي دليل.","zh":"对学者来说，它们是问题。","t":[15987,19671]},{"ar":"وبالنسبة إلى العلماء هي غذاء للفكر.","zh":"对那位商人来说，它们是财富。","t":[19671,23750]},{"ar":"وبالنسبة إلى رجال","zh":"但这些星星都沉默着。","t":[23750,25237]},{"ar":"أعمالنا هي ثروة. لكن النجوم بالنسبة إلى الجميع هي صامتة،","zh":"你——只有你——将拥有别人无法拥有的星星——","t":[25237,31171]}]},{"id":"ch26p46","audio":"ch26p46.mp3","sents":[{"ar":"وهذا الأمر لا ينطبق عليك","zh":"你究竟想表达什么？","t":[103,2471]}]},{"id":"ch26p47","audio":"ch26p47.mp3","sents":[{"ar":"من الآن فصاعدًا. - ماذا تعني؟ -","zh":"在某一颗星星上，我将居住。","t":[103,4605]},{"ar":"عندما تنظر إلى السماء في الليل،","zh":"在那颗星星上，我会笑着。","t":[4605,7184]},{"ar":"ونظرًا لأنني سأعيش على إحداها وأضحك، سيبدو لك أن النجوم","zh":"当你在夜晚仰望星空时，仿佛所有的星星都在欢笑。","t":[7184,12303]},{"ar":"كافة تضحك. أنت، وأنت فقط، ستكون لديك نجوم ضاحكة! (قال ذلك","zh":"你——只有你——将拥有会笑的星星！他再次笑了。","t":[12303,20895]}]},{"id":"ch26p48","audio":"ch26p48.mp3","sents":[{"ar":"وضحك). وعندما ترتاح -لأن الوقت يلطف الأحزان كلها- ستشعر بالفرح لأنك عرفتني،","zh":"当你的悲伤得到慰藉（时间抚平所有悲伤）时，你将满足于曾认识我。","t":[103,9395]},{"ar":"ستكون دائمًا صديقي،","zh":"你永远是我的朋友。","t":[9395,11447]},{"ar":"سترغب في الضحك معي،","zh":"你愿与我同笑。","t":[11447,13474]},{"ar":"ومن حين إلى آخر ستفتح نافذتك لمجرد الاستمتاع بذلك.","zh":"有时，你也会打开窗子，为了那份快乐……","t":[13474,19250]},{"ar":"وأصدقاؤك سيُدهشون عندما يشاهدونك تضحك بينما تحدق إلى","zh":"你的朋友们会惊讶地看到你仰望星空时竟在欢笑！","t":[19250,24197]},{"ar":"السماء. ولسوف تقول لهم: أجل، إن النجوم تدفعني إلى","zh":"是的，星星总是让我笑！他们会以为你疯了。","t":[24197,30184]},{"ar":"الضحك باستمرار. وسيظنون أنك مجنون، وسأكون قد قمت","zh":"这将是我在你身上玩的一个非常拙劣的把戏……","t":[30184,36237]}]},{"id":"ch26p49","audio":"ch26p49.mp3","sents":[{"ar":"بحيلة بارعة...","zh":"他又笑了。","t":[103,1536]}]},{"id":"ch26p50","audio":"ch26p50.mp3","sents":[{"ar":"(ضحك ثانية) سيبدو الأمر وكأنني قدمت لك عوضًا","zh":"仿佛我给了你无数会笑的小铃铛……","t":[103,4813]}]},{"id":"ch26p51","audio":"ch26p51.mp3","sents":[{"ar":"عن النجوم،","zh":"他又笑了。","t":[103,1326]},{"ar":"الكثير من الأجراس الصغيرة","zh":"他很快变得严肃起来：","t":[1326,3629]}]},{"id":"ch26p52","audio":"ch26p52.mp3","sents":[{"ar":"التي تستطيع أن تضحك...","zh":"今夜——你知道……","t":[103,2974]},{"ar":"(وضحك مرة أخرى، ثم أصبح جديًّا","zh":"“别来了，”小王子说。","t":[2974,6500]}]},{"id":"ch26p53","audio":"ch26p53.mp3","sents":[{"ar":"ثانية) الليلة...","zh":"我不会离开你。","t":[103,1944]}]},{"id":"ch26p54","audio":"ch26p54.mp3","sents":[{"ar":"أنت تعرف... لا تأت. - لن","zh":"我将显得像是在受苦。","t":[103,4013]},{"ar":"أتركك. - سأبدو أنني أتألم.","zh":"我将显得像是即将离世。","t":[4013,8513]},{"ar":"سأبدو وكأنني أحتضر.","zh":"它就是这样。","t":[8513,11434]},{"ar":"إن الأمر هكذا.","zh":"别来看那场戏。","t":[11434,13671]},{"ar":"لا تأت لترى ذلك؛ لا جدوى.","zh":"不值得费这个劲……","t":[13671,16316]}]},{"id":"ch26p55","audio":"ch26p55.mp3","sents":[{"ar":"- لن أتركك. كان","zh":"我不会离开你。","t":[103,2605]}]},{"id":"ch26p56","audio":"ch26p56.mp3","sents":[{"ar":"قلقًا. - أقول لك...","zh":"但他忧心忡忡。","t":[103,2737]}]},{"id":"ch26p57","audio":"ch26p57.mp3","sents":[{"ar":"جزئيًّا بسبب الحية، لا","zh":"这同样是因为那条蛇。","t":[103,2353]},{"ar":"ينبغي أن تعضك،","zh":"它不能咬你。","t":[2353,4011]},{"ar":"فالحيات مخلوقات شريرة. يمكنها","zh":"蛇——它们是恶毒的生物。","t":[4011,7855]},{"ar":"أن تعض لمجرد اللهو. - لن أتركك. طمأنته","zh":"这蛇说不定会故意咬你取乐呢……","t":[7855,13500]}]},{"id":"ch26p58","audio":"ch26p58.mp3","sents":[{"ar":"فكرة. - هل من الصحيح","zh":"我不会离开你。","t":[103,2881]}]},{"id":"ch26p59","audio":"ch26p59.mp3","sents":[{"ar":"أنها لا تمتلك المزيد من السم من","zh":"但一个念头让他得到了安慰：","t":[103,2826]}]},{"id":"ch26p60","audio":"ch26p60.mp3","sents":[{"ar":"أجل عضة ثانية؟ في تلك الليلة لم","zh":"蛇咬的第二口不再有毒液。","t":[103,4224]}]},{"id":"ch26p61","audio":"ch26p61.mp3","sents":[{"ar":"أشاهده يبدأ رحلة. غادر من دون أي","zh":"那晚，我没有看到他踏上归途。","t":[103,4263]},{"ar":"صوت، وعندما تمكنت من اللحاق به، كان","zh":"他悄无声息地从我身边溜走。","t":[4263,7829]},{"ar":"يسير بخطى سريعة ثابتة. قال لي فقط: - أوه! أنت هنا!","zh":"他追上他时，他正迈着迅速而坚定的步伐前行。","t":[7829,15368]},{"ar":"وأمسك بيدي، وكان ما زال يشعر بالقلق.","zh":"他只对我说了这么一句：","t":[15368,19118]}]},{"id":"ch26p62","audio":"ch26p62.mp3","sents":[{"ar":"-","zh":"啊！","t":[0,200]},{"ar":"لم يكن ينبغي لك","zh":"你就在那里……","t":[103,1694]}]},{"id":"ch26p63","audio":"ch26p63.mp3","sents":[{"ar":"المجيء، لن تكون سعيدًا،","zh":"他握住了我的手。","t":[103,2616]},{"ar":"سأبدو وكأنني أحتضر","zh":"他依旧忧心忡忡。","t":[2616,4642]}]},{"id":"ch26p64","audio":"ch26p64.mp3","sents":[{"ar":"ولن يكون ذلك","zh":"你来得不对。","t":[103,1366]},{"ar":"صحيحًا. لم أقل","zh":"你将受苦。","t":[1366,3737]},{"ar":"شيئًا. - عليك أن تفهم، إنه بعيد جدًّا. لا أستطيع","zh":"我将看起来像是死了；其实并非如此……","t":[3737,10460]}]},{"id":"ch26p65","audio":"ch26p65.mp3","sents":[{"ar":"أن أحمل هذا","zh":"我无言以对。","t":[103,1339]}]},{"id":"ch26p66","audio":"ch26p66.mp3","sents":[{"ar":"الجسد معي؛","zh":"你懂得……","t":[103,1511]},{"ar":"إنه ثقيل جدًّا. لم","zh":"路途太过遥远。","t":[1511,4355]},{"ar":"أقل شيئًا. - سيبدو مثل صدفة قديمة","zh":"我无法带着这具身体离去。","t":[4355,8513]},{"ar":"مهجورة، وليس","zh":"这太沉重了。","t":[8513,10185]}]},{"id":"ch26p67","audio":"ch26p67.mp3","sents":[{"ar":"شيئًا تحزن من أجله.","zh":"我无言以对。","t":[103,1721]}]},{"id":"ch26p68","audio":"ch26p68.mp3","sents":[{"ar":"لم أقل شيئًا. كان","zh":"却如同褪去的旧壳。","t":[103,2697]},{"ar":"مثبَط الهمة، لكنه بذل جهدًا","zh":"旧壳并无悲凉之处……","t":[2697,5750]}]},{"id":"ch26p69","audio":"ch26p69.mp3","sents":[{"ar":"أخيرًا. - أتعرف...","zh":"我无言以对。","t":[103,2724]}]},{"id":"ch26p70","audio":"ch26p70.mp3","sents":[{"ar":"سيكون كل شيء","zh":"他有些气馁。","t":[103,1471]},{"ar":"لطيفًا. أنا أيضًا","zh":"但他又试了一次：","t":[1471,4210]}]},{"id":"ch26p71","audio":"ch26p71.mp3","sents":[{"ar":"سأنظر إلى النجوم، وستكون كل","zh":"你懂得，这会非常美好。","t":[103,958]},{"ar":"النجوم آبارًا ذات بكرات","zh":"我也会仰望星空。","t":[958,4853]},{"ar":"صدئة، ستسكب كل النجوم لي","zh":"繁星如井，辘轳生锈。","t":[4853,7353]},{"ar":"شيئًا من الماء لأشرب. لم أقل","zh":"繁星将为我涌出清泉解渴。","t":[7353,10921]}]},{"id":"ch26p72","audio":"ch26p72.mp3","sents":[{"ar":"شيئًا. - سيكون","zh":"无言以对。","t":[103,2685]}]},{"id":"ch26p73","audio":"ch26p73.mp3","sents":[{"ar":"ذلك ممتعًا جدًّا!","zh":"那将非常有趣！","t":[103,2737]},{"ar":"سيكون لديك خمسمئة مليون جرس صغير، سيكون لدي خمسمئة مليون نبع","zh":"你将拥有五亿个小铃铛，而我将拥有五亿股清泉……","t":[2737,9474]}]},{"id":"ch26p74","audio":"ch26p74.mp3","sents":[{"ar":"من المياه العذبة... وهو أيضًا لم يقل","zh":"他默默无言，只因泪水盈眶。","t":[103,4026]}]},{"id":"ch26p75","audio":"ch26p75.mp3","sents":[{"ar":"المزيد لأنه كان","zh":"这里就是了。","t":[103,1603]},{"ar":"يبكي... - ها هي.","zh":"让我自己继续吧。","t":[1603,3129]}]},{"id":"ch26p76","audio":"ch26p76.mp3","sents":[{"ar":"دعني أذهب بمفردي. ثم جلس لأنه أحس","zh":"他坐下来，因为他害怕了。","t":[103,4697]},{"ar":"بالخوف. بعد","zh":"他又说道：","t":[4697,6947]}]},{"id":"ch26p77","audio":"ch26p77.mp3","sents":[{"ar":"ذلك قال: - هل تعلم... زهرتي...","zh":"你可知——我的花儿……","t":[103,4895]},{"ar":"أنا مسؤول عنها،","zh":"我为她负责。","t":[4895,6592]},{"ar":"وهي ضعيفة جدًّا","zh":"她如此脆弱！","t":[6592,8092]},{"ar":"وتثق بالآخرين","zh":"她如此天真！","t":[8092,9553]},{"ar":"كثيرًا. لديها أربع أشواك صغيرة لتحمي نفسها من العالم. جلست لأنني لم","zh":"她仅有四根刺，毫无用处，却用来抵御整个世界的侵害。","t":[9553,17986]}]},{"id":"ch26p78","audio":"ch26p78.mp3","sents":[{"ar":"أستطع أن أبقى واقفًا أكثر من ذلك. قال:","zh":"我也坐了下来，因为我已无法再站立。","t":[103,4460]}]},{"id":"ch26p79","audio":"ch26p79.mp3","sents":[{"ar":"- الآن... هذا كل شيء.","zh":"那便足够了……","t":[103,3118]}]},{"id":"ch26p80","audio":"ch26p80.mp3","sents":[{"ar":"تردد قليلًا، ثم وقف، تقدم خطوة إلى","zh":"他犹疑片刻，然后站起身来。","t":[103,4116]},{"ar":"الأمام. لم أستطع","zh":"他迈出一步。","t":[4116,6592]},{"ar":"أن أتحرك. لم يبق","zh":"我动弹不得。","t":[6592,9355]}]},{"id":"ch26p81","audio":"ch26p81.mp3","sents":[{"ar":"شيء أكثر من وميض أصفر قريب","zh":"踝边，一抹黄光掠过。","t":[103,2695]},{"ar":"من كاحله. وقف بلا","zh":"他瞬间僵立不动。","t":[2695,5355]},{"ar":"حراك لحظة، لم","zh":"他没有呼喊。","t":[5355,6961]},{"ar":"يصرخ، هوى بلطف مثلما تهوي","zh":"他如树般轻轻倒下。","t":[6961,9513]},{"ar":"شجرة، لم يكن هنالك حتى أخف صوت بسبب الرمل.","zh":"连沙沙声也没有，因为沙子的缘故。","t":[9513,14052]}]}]},{"id":"ch27","title_ar":"الفصل السابع والعشرون","title_en":"Chapter XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":"ch27p00.mp3","sents":[{"ar":"والآن، إن ست","zh":"六载光阴，已然逝去……","t":[103,1813]}]},{"id":"ch27p01","audio":"ch27p01.mp3","sents":[{"ar":"سنوات قد انقضت،","zh":"这故事，我从未对人提起。","t":[103,2129]},{"ar":"لم أسرد هذه القصة من قبل.","zh":"重逢的伙伴们见到我安然无恙，心中皆感欣慰。","t":[2129,5447]},{"ar":"فرح الرفاق الذين التقوا","zh":"我心情沉重，却对他们说：“我累得要命。”","t":[5447,7539]}]},{"id":"ch27p02","audio":"ch27p02.mp3","sents":[{"ar":"بي عندما عدت","zh":"我的哀愁得以稍慰。","t":[103,1195]},{"ar":"حين وجدوا أنني","zh":"这也就是说——并未完全。","t":[1195,2497]},{"ar":"ما زلت على قيد الحياة. كنت حزينًا،","zh":"但我深知他已返回自己的星球，因为天亮时我没有找到他的遗体。","t":[2497,6605]},{"ar":"لكنني أخبرتهم","zh":"他的遗体并不沉重……","t":[6605,8000]},{"ar":"بأنني مرهق. والآن","zh":"夜幕降临，我偏爱聆听星辰的低语。","t":[8000,10803]},{"ar":"لقد تغلبت على","zh":"它们宛如五亿个小铃铛……","t":[10803,12172]}]},{"id":"ch27p03","audio":"ch27p03.mp3","sents":[{"ar":"جزء من حزني، وبكلمات","zh":"然而，有一件不同寻常的事……","t":[103,2563]},{"ar":"أخرى؛ شُفيت لكن ليس","zh":"为小王子画了口罩，却忘了添上皮带。","t":[2563,4668]},{"ar":"تمامًا. أعرف أنه","zh":"他永远无法将它系在绵羊的脖子上。","t":[4668,7224]},{"ar":"رحل إلى كوكبه، لأنني لم","zh":"我始终在思索：他的星球上究竟发生了什么？","t":[7224,9526]},{"ar":"أعثر على جسده فجر","zh":"或许绵羊已经吃掉了那朵花……","t":[9526,11500]}]},{"id":"ch27p04","audio":"ch27p04.mp3","sents":[{"ar":"اليوم التالي.","zh":"当然，不会吧！","t":[103,2276]},{"ar":"قبل أي شيء، لم يكن الجسد ثقيل الوزن. أحب","zh":"小王子每晚都将他的花儿藏进玻璃球中，他精心照看着他的绵羊……于是，我便安心了。","t":[2276,7342]},{"ar":"الإصغاء إلى النجوم","zh":"星光笑意中，自有甜蜜。","t":[7342,8895]}]},{"id":"ch27p05","audio":"ch27p05.mp3","sents":[{"ar":"ليلًا. إنه أشبه بالإصغاء إلى","zh":"然而，有时我会对自己说：人难免会疏忽大意，这就足够了！","t":[103,3697]},{"ar":"خمسمئة مليون جرس صغير... هنالك شيء واحد يقلقني؛","zh":"那天晚上，他忘了玻璃球，或者绵羊悄无声息地溜出了，然后那些小铃铛就变成了泪水……","t":[3697,9473]}]},{"id":"ch27p06","audio":"ch27p06.mp3","sents":[{"ar":"عندما رسمت","zh":"这是一桩不解之谜。","t":[103,1024]},{"ar":"الكمامة للأمير الصغير، نسيت أن أضيف الشريط الجلدي إليها، وهو لن يتمكن أبدًا من تثبيتها على خروفه.","zh":"对于你们这些也喜爱小王子的人，还有我，若在宇宙的某个角落，有一只我们从未见过的绵羊——真的吗？——吃掉了一朵玫瑰，那么，宇宙间的一切都将不再相同……","t":[1024,9840]}]},{"id":"ch27p07","audio":"ch27p07.mp3","sents":[{"ar":"وهكذا","zh":"仰望星空。","t":[103,668]},{"ar":"أتساءل","zh":"请自问：是，还是否？","t":[668,1261]},{"ar":"دائمًا عما حدث","zh":"绵羊是否吞食了那朵花？","t":[1261,2576]},{"ar":"على كوكبه. لربما","zh":"你们便会察觉万物如何变幻。","t":[2576,5316]}]},{"id":"ch27p08","audio":"ch27p08.mp3","sents":[{"ar":"أكل الخروف الزهرة... من","zh":"大人永远无法明白，这个问题有多么重要！","t":[103,3013]}]},{"id":"ch27p09","audio":"ch27p09.mp3","sents":[{"ar":"حين إلى آخر أقول في نفسي:","zh":"这，于我而言，是世上最美丽又最悲伤的风光。","t":[103,2642]},{"ar":"« بالتأكيد لا! فالأمير الصغير","zh":"与前页相同，但我再次绘制它，是为了加深你们的印象。","t":[2642,5789]},{"ar":"يغطي زهرته بقبتها الزجاجية","zh":"小王子便是在此地降临地球，又在此地消失。","t":[5789,8684]}]},{"id":"ch27p10","audio":"ch27p10.mp3","sents":[{"ar":"كل ليلة ويراقب خروفه بانتباه...","zh":"仔细端详，以便有朝一日你在非洲沙漠旅行时能认出它。","t":[103,4145]},{"ar":"»، عندئذ أشعر","zh":"若你途经此地，请勿匆匆赶路。","t":[4145,5316]},{"ar":"بالفرح، وكل","zh":"在星光下稍作等待。","t":[5316,6697]},{"ar":"النجوم تضحك برقة. لكنني أفكر بعد ذلك:","zh":"若有个孩童笑逐颜开，金发披肩，对问话不答，你便识得他是谁了。","t":[6697,11882]},{"ar":"«يمكن للمرء","zh":"若此成真，请安慰我。","t":[11882,12987]},{"ar":"أن يشرد","zh":"请告知我他已归来。","t":[12987,13816]}]},{"id":"ch27p11","audio":"ch27p11.mp3","sents":[{"ar":"ذهنه أحيانًا","zh":"圣埃克苏佩里：简传","t":[103,1392]}]},{"id":"ch27p12","audio":"ch27p12.mp3","sents":[{"ar":"والأمر يستلزم مرة","zh":"他的朋友们称他为圣埃克苏佩里。","t":[103,1892]},{"ar":"واحدة فقط. لربما نسي القبة","zh":"实际上，他名叫安东尼·德·圣埃克苏佩里。","t":[1892,5750]},{"ar":"الزجاجية ذات","zh":"他是法国最伟大的作家之一。","t":[5750,6947]},{"ar":"مساء، أو انزلق","zh":"他也是航空业的先驱之一。","t":[6947,8500]},{"ar":"الخروف بلا","zh":"这是他的故事。","t":[8500,9566]}]},{"id":"ch27p13","audio":"ch27p13.mp3","sents":[{"ar":"ضجة خلال الليل، فتغرق","zh":"圣埃克苏佩里于1900年出生于里昂。","t":[103,2405]},{"ar":"الأجراس","zh":"早年，他梦想着冒险。","t":[2405,2945]},{"ar":"الصغيرة أنفسها بالدموع.","zh":"他最大的愿望是成为一名海军军官。","t":[2945,6053]},{"ar":"إن هذا لغز عظيم، فبالنسبة إلى","zh":"为了成为一名海军军官，必须通过一场极其艰难的考试。","t":[6053,9053]},{"ar":"من يحب الأمير","zh":"圣埃克苏佩里应试未果...","t":[9053,10079]},{"ar":"الصغير مثلي منكم، ما من","zh":"幸而，还有另一种解决办法——航空。","t":[10079,12342]},{"ar":"شيء في الكون","zh":"那时，航空极为危险。","t":[12342,13329]},{"ar":"يمكن أن يكون مماثلًا، ما","zh":"危险，风险——这正是圣埃克苏佩里所渴望的。","t":[13329,15763]},{"ar":"من أحد يعرف أن خروفًا","zh":"在服役期间，他学会了驾驶飞机。","t":[15763,17697]},{"ar":"لم يسبق أن رأيناه،","zh":"圣埃克苏佩里心中只有一个念头：飞翔。","t":[17697,19303]}]},{"id":"ch27p14","audio":"ch27p14.mp3","sents":[{"ar":"ربما أكل أو ربما لم يأكل زهرة... انظروا","zh":"服役结束后，他向一家航空公司经理表达了自己想成为一名飞行员的愿望。","t":[103,4368]},{"ar":"إلى السماء. اسألوا","zh":"导演对他说：“就像别人一样做吧。”","t":[4368,6711]},{"ar":"أنفسكم: هل أكل الخروف","zh":"首先，你得学会做一名机械师。","t":[6711,9211]}]},{"id":"ch27p15","audio":"ch27p15.mp3","sents":[{"ar":"الزهرة؟ نعم أو لا؟","zh":"圣埃克苏佩里努力成为一名机械师。","t":[103,3763]},{"ar":"وستدركون كيف أن","zh":"1927年，他终于实现了目标。","t":[3763,5316]},{"ar":"كل شيء يتغير...","zh":"他是编队中的飞行员。","t":[5316,7803]},{"ar":"ولن يفهم الراشدون أبدًا","zh":"他在地中海、撒哈拉上空完成了危险的飞行任务。","t":[7803,9750]},{"ar":"لماذا هذا الأمر مهم!","zh":"他在沙漠中央遭遇了许多事故。","t":[9750,12553]},{"ar":"هذا بالنسبة إليَّ","zh":"后来，他成为南美自己航空公司的总监。","t":[12553,13961]},{"ar":"أجمل وأحزن منظر طبيعي في العالم،","zh":"在那儿，他也在安第斯山脉上空完成了许多危险的任务。","t":[13961,17092]}]},{"id":"ch27p16","audio":"ch27p16.mp3","sents":[{"ar":"إنه المنظر الطبيعي عينه","zh":"对圣埃克苏佩里而言，飞行不仅仅是驾驶飞机。","t":[103,2274]},{"ar":"كما في آخر","zh":"也在沉思，在反思。","t":[2274,3195]},{"ar":"صورة، لكنني رسمته مرة ثانية كي أطبعه في ذاكرتكم.","zh":"在执行任务期间，圣埃克苏佩里深刻思考着孤独、友谊、生命的意义、人的境遇和自由。","t":[3195,9566]},{"ar":"إنه المكان","zh":"他发表了反思。","t":[9566,10526]},{"ar":"حيث ظهر الأمير","zh":"他的书籍立刻大获成功。","t":[10526,11986]}]},{"id":"ch27p17","audio":"ch27p17.mp3","sents":[{"ar":"الصغير على الأرض ثم اختفى. انظروا","zh":"不幸的是，圣埃克苏佩里供职的航空公司正面临严重的财务困境。","t":[103,3737]},{"ar":"بانتباه إلى المنظر","zh":"圣埃克苏佩里不得不离开公司。","t":[3737,5066]},{"ar":"الطبيعي","zh":"他成为一名记者。","t":[5066,5776]},{"ar":"لتتأكدوا من أن","zh":"他游历过西班牙、俄罗斯和德国。","t":[5776,6987]},{"ar":"تتذكروه إذا ما","zh":"他一有机会就飞行。","t":[6987,8592]}]},{"id":"ch27p18","audio":"ch27p18.mp3","sents":[{"ar":"قمتم بالسفر ذات","zh":"1939年，法国与德国开战。","t":[103,1445]},{"ar":"يوم إلى إفريقيا،","zh":"圣埃克苏佩里立刻应征入伍。","t":[1445,3129]},{"ar":"عبر الصحراء.","zh":"败局随之而至。","t":[3129,5224]},{"ar":"وإذا صادف أن","zh":"法国沦陷于希特勒的军队之手。","t":[5224,6644]}]},{"id":"ch27p19","audio":"ch27p19.mp3","sents":[{"ar":"وصلتم إلى هذه","zh":"圣埃克苏佩里不接受失败。","t":[103,1379]},{"ar":"البقعة،","zh":"他决定离开法国。","t":[1379,2208]},{"ar":"أرجو ألا تتابعوا","zh":"他在美国定居，继续写作。","t":[2208,3511]},{"ar":"السير بسرعة، تريثوا قليلًا تحت","zh":"在纽约，他出版了《小王子》，这是他最著名的作品之一。","t":[3511,6524]}]},{"id":"ch27p20","audio":"ch27p20.mp3","sents":[{"ar":"النجمة تمامًا، بعد","zh":"1942年，美军在北非登陆。","t":[103,2142]},{"ar":"ذلك، إذا جاء طفل","zh":"圣埃克苏佩里决定加入美国军队。","t":[2142,4050]},{"ar":"باتجاهكم، إذا ضحك، إذا","zh":"四十二岁时，他志愿成为了一名飞行员。","t":[4050,6787]},{"ar":"كانت لديه خصل","zh":"他被告知自己年纪太大。","t":[6787,8089]},{"ar":"شعر","zh":"他坚持不懈。","t":[8089,8524]},{"ar":"ذهبية، وإذا رفض","zh":"终于，他得到了满足。","t":[8524,10445]},{"ar":"أن يجيب عن","zh":"他得到了一架飞机。","t":[10445,11326]},{"ar":"الأسئلة، فأنتم بالتأكيد","zh":"他在被占领的法国上空完成了许多任务。","t":[11326,13734]}]},{"id":"ch27p21","audio":"ch27p21.mp3","sents":[{"ar":"ستعرفون من هو، لذا كونوا طيبين!","zh":"1944年7月31日，圣埃克苏佩里踏上他最后的使命。","t":[103,4263]},{"ar":"لا تتركوني أستسلم","zh":"他的飞机在地中海上空被德国人摧毁。","t":[4263,5789]},{"ar":"للحزن، اكتبوا لي","zh":"那天，圣埃克苏佩里未能归来……","t":[5789,7487]},{"ar":"بسرعة كي تخبروني أنه عاد.","zh":"在辽阔的天际，他觅得风险、死亡与荣耀。","t":[7487,10184]}]}]}]};